    // ===== IndexedDB-backed storage with synchronous in-memory cache =====
    // Replaces localStorage to bypass the ~5-10 MB browser quota.
    // The cache is hydrated once at boot from IndexedDB (and migrated from
    // localStorage if needed), then reads are synchronous and writes are
    // queued asynchronously in the background.
    const IDB_NAME = "sineus-app-storage";
    const IDB_STORE = "kv";

    const STORAGE_KEYS = [
      "agencia-postventa-demo-v1",
      "agencia-postventa-drivers-v1",
      "agencia-postventa-driver-rates-v1",
      "agencia-postventa-providers-v1",
      "agencia-postventa-transfers-v1",
      "agencia-postventa-destinations-v1",
      "agencia-postventa-bookings-v1",
      "agencia-postventa-auth-v1",
      "agencia-postventa-profiles-v1",
      "agencia-postventa-finance-providers-v1",
      "agencia-postventa-fuel-records-v1"
    ];

    const appStorage = (() => {
      const cache = new Map();
      let dbPromise = null;
      let writeQueue = Promise.resolve();

      function openDB() {
        if (dbPromise) return dbPromise;
        dbPromise = new Promise((resolve, reject) => {
          if (typeof indexedDB === "undefined") {
            reject(new Error("IndexedDB not available"));
            return;
          }
          const req = indexedDB.open(IDB_NAME, 1);
          req.onupgradeneeded = () => {
            const db = req.result;
            if (!db.objectStoreNames.contains(IDB_STORE)) {
              db.createObjectStore(IDB_STORE);
            }
          };
          req.onsuccess = () => resolve(req.result);
          req.onerror = () => reject(req.error);
          req.onblocked = () => reject(new Error("IndexedDB blocked"));
        });
        return dbPromise;
      }

      async function idbGetAll() {
        const db = await openDB();
        return new Promise((resolve, reject) => {
          const tx = db.transaction(IDB_STORE, "readonly");
          const store = tx.objectStore(IDB_STORE);
          const items = {};
          const cursorReq = store.openCursor();
          cursorReq.onsuccess = () => {
            const cursor = cursorReq.result;
            if (cursor) {
              items[cursor.key] = cursor.value;
              cursor.continue();
            } else {
              resolve(items);
            }
          };
          cursorReq.onerror = () => reject(cursorReq.error);
        });
      }

      async function idbSet(key, value) {
        const db = await openDB();
        return new Promise((resolve, reject) => {
          const tx = db.transaction(IDB_STORE, "readwrite");
          tx.objectStore(IDB_STORE).put(value, key);
          tx.oncomplete = () => resolve();
          tx.onerror = () => reject(tx.error);
          tx.onabort = () => reject(tx.error);
        });
      }

      async function idbDelete(key) {
        const db = await openDB();
        return new Promise((resolve, reject) => {
          const tx = db.transaction(IDB_STORE, "readwrite");
          tx.objectStore(IDB_STORE).delete(key);
          tx.oncomplete = () => resolve();
          tx.onerror = () => reject(tx.error);
          tx.onabort = () => reject(tx.error);
        });
      }

      async function init() {
        try {
          const stored = await idbGetAll();
          for (const [k, v] of Object.entries(stored)) cache.set(k, v);

          // One-time migration from localStorage so existing users don't lose data
          let migrated = false;
          for (const key of STORAGE_KEYS) {
            if (cache.has(key)) continue;
            try {
              const legacy = localStorage.getItem(key);
              if (legacy != null) {
                let parsed;
                try { parsed = JSON.parse(legacy); } catch { parsed = legacy; }
                cache.set(key, parsed);
                await idbSet(key, parsed);
                migrated = true;
              }
            } catch (e) { /* localStorage may be full or blocked, ignore */ }
          }

          // Free up localStorage if it was holding large data so the quota
          // error stops biting on first paint.
          if (migrated) {
            for (const key of STORAGE_KEYS) {
              try { localStorage.removeItem(key); } catch {}
            }
          }
        } catch (err) {
          console.warn("IndexedDB no disponible, usando solo memoria", err);
        }
      }

      // Synchronous API that mirrors localStorage:
      // values are stored already-parsed (objects), but getItem returns the
      // JSON string for compatibility with the existing call sites.
      function getItem(key) {
        if (!cache.has(key)) return null;
        const value = cache.get(key);
        if (typeof value === "string") return value;
        try { return JSON.stringify(value); } catch { return null; }
      }

      function setItem(key, value) {
        let parsed = value;
        if (typeof value === "string") {
          try { parsed = JSON.parse(value); } catch { parsed = value; }
        }
        cache.set(key, parsed);
        writeQueue = writeQueue.then(() => idbSet(key, parsed)).catch((err) => {
          console.warn("No se pudo guardar en IndexedDB", key, err);
        });
      }

      function removeItem(key) {
        cache.delete(key);
        writeQueue = writeQueue.then(() => idbDelete(key)).catch((err) => {
          console.warn("No se pudo borrar de IndexedDB", key, err);
        });
      }

      function clear() {
        cache.clear();
        writeQueue = writeQueue.then(async () => {
          const db = await openDB();
          return new Promise((resolve, reject) => {
            const tx = db.transaction(IDB_STORE, "readwrite");
            tx.objectStore(IDB_STORE).clear();
            tx.oncomplete = () => resolve();
            tx.onerror = () => reject(tx.error);
          });
        }).catch((err) => console.warn("No se pudo limpiar IndexedDB", err));
      }

      return { init, getItem, setItem, removeItem, clear };
    })();

