    // Setea el valor de un <select> SIN perder datos: si el valor guardado no está entre
    // las opciones (datos viejos: 'st.karen', 'BRASIL', 'MDZ', estrellas, 'INSTAGRAM'…),
    // lo agrega como una opción para que se muestre y NO se borre al guardar.
    function selectSetValueKeepingUnknown(selectEl, value) {
      if (!selectEl) return;
      const v = (value == null) ? "" : String(value);
      selectEl.value = v;
      if (v && selectEl.value !== v) {
        const opt = document.createElement("option");
        opt.value = v;
        opt.textContent = v;
        selectEl.appendChild(opt);
        selectEl.value = v;
      }
    }
    function stampClientFields(client, names) {
      if (!client || !Array.isArray(names)) return;
      if (!client.fieldStamps || typeof client.fieldStamps !== "object") client.fieldStamps = {};
      var t = Date.now();
      names.forEach(function(n) { client.fieldStamps[n] = t; });
    }

