    function normalizeFinanceProvider(p) {
      p = p || {};
      return {
        id: p.id || makeId(),
        name: String(p.name || "").trim(),
        cbu: String(p.cbu || "").trim(),
        alias: String(p.alias || "").trim(),
        bank: String(p.bank || "").trim(),
        holder: String(p.holder || "").trim(),
        taxId: String(p.taxId || "").trim(),
        email: String(p.email || "").trim(),
        phone: String(p.phone || "").trim(),
        address: String(p.address || "").trim(),
        notes: String(p.notes || "").trim()
      };
    }

    function saveFinanceProviders() {
      state.financeProviders = (state.financeProviders || []).map(normalizeFinanceProvider).filter((p) => p.name);
      appStorage.setItem(FINANCE_PROVIDERS_KEY, JSON.stringify(state.financeProviders));
      queueRemoteSave();
      renderAll();
    }

    function loadFuelRecords() {
      try {
        const raw = appStorage.getItem(FUEL_RECORDS_KEY);
        const parsed = raw ? JSON.parse(raw) : [];
        return Array.isArray(parsed) ? parsed.map(normalizeFuelRecord) : [];
      } catch {
        return [];
      }
    }

    function normalizeFuelRecord(r) {
      r = r || {};
      return {
        id: r.id || makeId(),
        driverId: String(r.driverId || ""),
        driverName: String(r.driverName || "").trim().toUpperCase(),
        vehicleId: String(r.vehicleId || ""),
        vehicleLabel: String(r.vehicleLabel || "").trim().toUpperCase(),
        date: r.date || "",
        amount: Number.parseFloat(r.amount) || 0,
        liters: r.liters ? Number.parseFloat(r.liters) : "",
        receiptImage: r.receiptImage || "", // dataURL base64
        receiptName: r.receiptName || "",
        notes: String(r.notes || "").trim(),
        createdAt: r.createdAt || new Date().toISOString()
      };
    }

    function saveFuelRecords() {
      state.fuelRecords = (state.fuelRecords || []).map(normalizeFuelRecord);
      appStorage.setItem(FUEL_RECORDS_KEY, JSON.stringify(state.fuelRecords));
      queueRemoteSave();
    }

    // ETAPA B: el combustible vive en su propia tabla `fuel_records` (RLS: cada chofer el suyo,
    // el staff todo). Alta/borrado escriben en la tabla; ya no en el bundle de config.
    function saveFuelLocal() {
      try { appStorage.setItem(FUEL_RECORDS_KEY, JSON.stringify(state.fuelRecords || [])); } catch (e) {}
    }
    async function upsertFuelRecordRemote(record) {
      try {
        if (!remoteEnabled() || !record || !record.id) return null;
        var sb = await getSupabaseClient();
        var res = await sb.from("fuel_records").upsert(
          [{ id: record.id, driver_id: record.driverId || "", data: record, updated_at: new Date().toISOString(), updated_by: state.currentUser || "" }],
          { onConflict: "id" }
        );
        if (res.error) { console.warn("No se pudo guardar el combustible en la nube:", res.error.message); return res.error.message || "error"; }
        return null;
      } catch (e) { console.warn("upsertFuelRecordRemote", e); return (e && e.message) || "error de conexión"; }
    }
    // Achica y comprime la foto del ticket ANTES de guardarla (una foto de celular pesa varios MB
    // y hacía fallar el guardado en silencio). Deja un JPEG chico (~ máx 1280px). (29/08)
    function compressImageFile(file, maxDim, quality) {
      return new Promise(function (resolve, reject) {
        try {
          var reader = new FileReader();
          reader.onload = function (e) {
            var img = new Image();
            img.onload = function () {
              try {
                var w = img.width, h = img.height;
                if (w >= h && w > maxDim) { h = Math.round(h * maxDim / w); w = maxDim; }
                else if (h > w && h > maxDim) { w = Math.round(w * maxDim / h); h = maxDim; }
                var cv = document.createElement("canvas"); cv.width = w; cv.height = h;
                cv.getContext("2d").drawImage(img, 0, 0, w, h);
                resolve(cv.toDataURL("image/jpeg", quality || 0.6));
              } catch (err) { reject(err); }
            };
            img.onerror = function () { reject(new Error("no se pudo leer la imagen")); };
            img.src = e.target.result;
          };
          reader.onerror = function () { reject(new Error("no se pudo abrir el archivo")); };
          reader.readAsDataURL(file);
        } catch (err) { reject(err); }
      });
    }
    async function deleteFuelRecordRemote(recordId) {
      try {
        if (!remoteEnabled() || !recordId) return;
        var sb = await getSupabaseClient();
        var res = await sb.from("fuel_records").delete().eq("id", recordId);
        if (res.error) console.warn("No se pudo borrar el combustible en la nube:", res.error.message);
      } catch (e) { console.warn("deleteFuelRecordRemote", e); }
    }
    // Staff: trae TODO el combustible desde la tabla (el chofer lo recibe en su bundle).
    async function fetchFuelRecordsIntoState() {
      try {
        if (!remoteEnabled()) return;
        var sb = await getSupabaseClient();
        var res = await sb.from("fuel_records").select("data");
        if (res.error) { console.warn("fetchFuelRecords", res.error.message); return; }
        state.fuelRecords = (res.data || []).map(function (r) { return normalizeFuelRecord(r.data || {}); });
        saveFuelLocal();
      } catch (e) { console.warn("fetchFuelRecordsIntoState", e); }
    }

    function loadCatalogProviders() {
      try {
        const raw = appStorage.getItem(PROVIDERS_KEY);
        const parsed = raw ? JSON.parse(raw) : null;
        const source = Array.isArray(parsed) ? parsed : defaultCatalogProviders();
        return withSystemCatalogProviders(source.map(normalizeCatalogProvider).filter((provider) => provider.name));
      } catch {
        return withSystemCatalogProviders(defaultCatalogProviders().map(normalizeCatalogProvider));
      }
    }

