    function defaultCatalogProviders() {
      // Fix #3 (25/07/2026): ANTES este "seed" devolvia Catena Zapata y Lagarde SIN id.
      // En un navegador nuevo o incognito (sin catalogo guardado localmente), este fallback
      // se cargaba y, al no tener id, normalizeCatalogProvider les asignaba un id NUEVO con
      // makeId() -> se creaban proveedores "fantasma" duplicados (Catena Zapata / Lagarde, 1
      // servicio) que se subian a la nube en cada apertura nueva/incognito. El catalogo real
      // ya vive en la nube (tablas), asi que este seed ya no hace falta y solo genera basura:
      // devolvemos vacio y el sistema adopta el catalogo real al sincronizar.
      return [];
    }

    function withSystemCatalogProviders(list) {
      const providersList = Array.isArray(list) ? list.slice() : [];
      if (!providersList.some(isAltaMountainProvider)) providersList.push(normalizeCatalogProvider(altaMountainProviderTemplate()));
      return providersList;
    }

    function hydrateCatalogProviders(list) {
      const providersList = withSystemCatalogProviders((Array.isArray(list) ? list : []).map(normalizeCatalogProvider).filter((provider) => provider.name));
      providersList.forEach((provider) => {
        provider.services.forEach((service) => {
          if (!service.id) service.id = makeId();
        });
      });
      return providersList;
    }

    function altaMountainProviderTemplate() {
      return {
        id: "provider-alta-montana",
        name: "Alta Montana",
        region: "Alta Montana",
        cancellationHours: "",
        services: []
      };
    }

