    function defaultDestinations() {
      return [
              "AEROPUERTO MENDOZA",
              "ALTA MONTANA",
              "ALTA MONTA\u00d1A",
              "BODEGAS LUJAN / MAIPU",
              "CHILE",
              "CITY TOUR",
              "CIUDAD DE MENDOZA",
              "HOTEL CENTRO",
              "LAS LE\u00d1AS",
              "LUJAN DE CUYO",
              "LUJAN/MAIPU",
              "MAIPU",
              "MENDOZA CIUDAD",
              "VALLE DE UCO"
      ].map((name) => ({ name: name }));
    }

    // ============== AVISOS DE CAMBIOS EN CLIENTES CERRADOS ==============
    // Detecta cuando alguien modifica algo de un cliente CERRADO (pasajeros, fechas, itinerario,
    // hoteles, bodegas, chofer, vehiculo, horarios, estados) y lo deja en un listado compartido.
    // Cada usuario tiene su propio "visto" (con fecha). Confirmado con Emilia (25/08).

    // "Huella" del cliente: 4 partes. Si alguna cambia, se genera un aviso indicando cual.
    function clientAvisoParts(client) {
      var pax = String(paxCount(client) || "");
      var fechas = (client.from || "") + " → " + (client.to || "");
      var hoteles = (client.hotels || [])
        .map(function (h) { return latinKey(h && h.name) + "|" + ((h && h.from) || "") + "|" + ((h && h.to) || ""); })
        .sort().join(" ; ");
      var servicios = (client.services || [])
        .map(function (s) {
          s = s || {};
          var stops = (s.stops || [])
            .map(function (st) { st = st || {}; return (st.time || "") + "|" + latinKey(st.provider) + "|" + latinKey(st.experience) + "|" + (st.status || ""); })
            .join(",");
          return (s.date || "") + "|" + latinKey(s.type) + "|" + latinKey(s.driver) + "|" + latinKey(s.vehicle) + "|" + (s.pax != null ? s.pax : "") + "|" + stops;
        })
        .sort().join(" ; ");
      return { pax: pax, fechas: fechas, hoteles: hoteles, servicios: servicios };
    }

    // Compara dos huellas y devuelve la lista legible de que cambio.
    function diffAvisoParts(oldP, newP) {
      var out = [];
      if (!oldP) return out;
      if (oldP.pax !== newP.pax) out.push("Pasajeros: " + (oldP.pax || "?") + " → " + (newP.pax || "?"));
      if (oldP.fechas !== newP.fechas) out.push("Fechas del viaje: " + (oldP.fechas || "?") + " → " + (newP.fechas || "?"));
      if (oldP.hoteles !== newP.hoteles) out.push("Hoteles");
      if (oldP.servicios !== newP.servicios) out.push("Itinerario / servicios (bodegas, horarios, chofer, vehículo o estados)");
      return out;
    }

    // Une dos listas de avisos por id y fusiona el "visto por" (nunca se pierden ticks).
    function mergeAvisos(a, b) {
      var byId = {};
      (Array.isArray(a) ? a : []).forEach(function (x) { if (x && x.id) byId[x.id] = Object.assign({}, x, { readBy: Object.assign({}, x.readBy || {}) }); });
      (Array.isArray(b) ? b : []).forEach(function (x) {
        if (!x || !x.id) return;
        if (!byId[x.id]) { byId[x.id] = Object.assign({}, x, { readBy: Object.assign({}, x.readBy || {}) }); return; }
        var merged = byId[x.id];
        merged.readBy = Object.assign({}, merged.readBy || {}, x.readBy || {});
      });
      return Object.keys(byId)
        .map(function (id) { return byId[id]; })
        .sort(function (x, y) { return String(y.at || "").localeCompare(String(x.at || "")); })
        .slice(0, 800);
    }

    // Recorre los clientes CERRADOS tocados en esta sesion y, si cambiaron respecto de su huella
    // guardada, agrega un aviso. Actualiza la huella. La 1a vez (sin huella) solo la fija (sin aviso).
    function detectClienteCerradoAvisos() {
      if (!state.currentUser) return;
      state.avisos = Array.isArray(state.avisos) ? state.avisos : [];
      state.clients.forEach(function (client) {
        if (!client || client.leadStatus !== "Cerrado") return;
        if (!sessionTouchedClients.has(client.id)) return;
        var parts = clientAvisoParts(client);
        var changes = diffAvisoParts(client.avisoBaseline, parts);
        if (client.avisoBaseline && changes.length) {
          state.avisos.unshift({
            id: makeId(),
            clientId: client.id,
            clientNumber: client.number || "",
            clientName: fullName(client) || "",
            at: new Date().toISOString(),
            by: state.currentUser || "",
            changes: changes,
            readBy: {}
          });
          state.avisos = state.avisos.slice(0, 800);
        }
        client.avisoBaseline = parts; // fija/actualiza la huella (silencioso la 1a vez).
      });
    }

    function saveClients() {
      state.clients.forEach((client) => {
        const version = operationalItineraryVersion(client);
        if (client.leadStatus === "Cerrado" && version) {
          // FIX INCIDENTE 07/08: NO regenerar (pisar) los servicios ya cargados en cada
          // guardado. Solo se generan desde el itinerario si el cliente aun no tiene.
          if (!(Array.isArray(client.services) && client.services.length)) {
            client.services = servicesFromItinerary(client, version, client.services || []);
          }
          removeActiveItineraryBookingsFromBank(client);
          // Cuando el cliente pasa a Cerrado, los pasos PENDIENTE suben a EN RESERVA.
          (version.steps || []).forEach((step) => {
            if (step.status === "PENDIENTE") step.status = "EN RESERVA";
          });
        }
      });
      state.clients = state.clients.map((client) => {
        const normalized = normalizeClient(client);
        normalized.status = computeClientStatus(normalized);
        return normalized;
      });
      try { detectClienteCerradoAvisos(); } catch (e) {}
      state.bookings = state.bookings.map(normalizeBooking).filter((booking) => booking.date || booking.providerName || booking.serviceName);
      appStorage.setItem(STORAGE_KEY, JSON.stringify(state.clients));
      appStorage.setItem(BOOKINGS_KEY, JSON.stringify(state.bookings));
      queueRemoteSave();
      renderAll();
    }

