    // ===== Configuracion de LIQUIDACION (sueldo fijo + valor por servicio, por vendedor) =====
    // Se guarda global (viaja por app_config, igual que rates) para que sea el mismo valor en
    // todas las computadoras. Por ahora solo Gianfranco; Karen se agrega cuando definamos sus reglas.
    function normalizeLiquidacionConfig(raw) {
      const src = raw && typeof raw === "object" ? raw : {};
      const g = src.gianfranco && typeof src.gianfranco === "object" ? src.gianfranco : {};
      const k = src.karen && typeof src.karen === "object" ? src.karen : {};
      const num = (v, def) => (v != null && Number.isFinite(Number(v)) && Number(v) >= 0 ? Number(v) : def);
      // VALORES POR MES (07/09, pedido de Emilia): el valor por servicio (y el sueldo) se guardan
      // POR MES ("2026-08": {...}). Si en septiembre cambia el valor, agosto queda como estaba.
      const byMonth = (raw) => {
        const out = {};
        const srcM = raw && typeof raw === "object" ? raw : {};
        Object.keys(srcM).forEach((ym) => {
          if (!/^\d{4}-\d{2}$/.test(ym) || !srcM[ym] || typeof srcM[ym] !== "object") return;
          out[ym] = { salary: num(srcM[ym].salary, 0), perService: num(srcM[ym].perService, 0) };
        });
        return out;
      };
      return {
        gianfranco: {
          salary: num(g.salary, 800000),
          perService: num(g.perService, 2500),
          byMonth: byMonth(g.byMonth)
        },
        // KAREN (07/09): comisiona SOLO por sus clientes (los que cerró ella) y por cada
        // servicio de esos pasajeros, EXCEPTO los traslados de aeropuerto (TRF IN / TRF OUT).
        // No tiene sueldo fijo: solo comisión.
        karen: {
          salary: num(k.salary, 0),
          perService: num(k.perService, 1500),
          byMonth: byMonth(k.byMonth)
        }
      };
    }
    // Valores vigentes para un vendedor en un mes dado: el guardado para ESE mes; si no hay,
    // el del ultimo mes anterior que tenga valor; si tampoco, el valor base.
    function liquidacionCfgForMonth(vendorKey, ym) {
      const all = normalizeLiquidacionConfig(state.liquidacionConfig);
      const v = all[vendorKey] || { salary: 0, perService: 0, byMonth: {} };
      const bm = v.byMonth || {};
      if (bm[ym]) return { salary: bm[ym].salary, perService: bm[ym].perService, source: ym };
      const prev = Object.keys(bm).filter((k) => k < ym).sort().pop();
      if (prev) return { salary: bm[prev].salary, perService: bm[prev].perService, source: prev };
      return { salary: Number(v.salary) || 0, perService: Number(v.perService) || 0, source: "" };
    }
    function loadLiquidacionConfig() {
      try {
        const raw = appStorage.getItem(LIQUIDACION_KEY);
        return normalizeLiquidacionConfig(raw ? JSON.parse(raw) : null);
      } catch (e) {
        return normalizeLiquidacionConfig(null);
      }
    }
    function persistLiquidacionConfig() {
      appStorage.setItem(LIQUIDACION_KEY, JSON.stringify(state.liquidacionConfig));
      queueRemoteSave();
    }

    // ===== Pagos de liquidacion (adelantos / pagos parciales por vendedor y mes) =====
    // Estructura: { "gianfranco|2026-08": [ {id,date,method,amount,note,by,at}, ... ] }
    function normalizeLiquidacionPayments(raw) {
      const out = {};
      const src = raw && typeof raw === "object" ? raw : {};
      Object.keys(src).forEach((key) => {
        const list = Array.isArray(src[key]) ? src[key] : [];
        out[key] = list.map((p) => ({
          id: p && p.id ? String(p.id) : makeId(),
          date: p && p.date ? String(p.date) : "",
          method: p && p.method ? String(p.method) : "",
          amount: p && Number.isFinite(Number(p.amount)) ? Number(p.amount) : 0,
          note: p && p.note ? String(p.note) : "",
          by: p && p.by ? String(p.by) : "",
          at: p && p.at ? String(p.at) : ""
        })).filter((p) => p.amount || p.date);
      });
      return out;
    }
    function loadLiquidacionPayments() {
      try {
        const raw = appStorage.getItem(LIQUIDACION_PAY_KEY);
        return normalizeLiquidacionPayments(raw ? JSON.parse(raw) : null);
      } catch (e) {
        return {};
      }
    }
    function persistLiquidacionPayments() {
      appStorage.setItem(LIQUIDACION_PAY_KEY, JSON.stringify(state.liquidacionPayments));
      queueRemoteSave();
    }
    function liquidacionPayKey(vendorKey, ym) { return vendorKey + "|" + ym; }
    // Memoria de esta sesión: pagos creados/borrados acá y meses de config editados acá.
    // Sirve para que una bajada de la nube no los pise antes de que suban.
    var sessionCreatedLiqPayIds = new Set();
    var sessionDeletedLiqPayIds = new Set();
    var sessionEditedLiqMonths = new Set();
    function liquidacionPaymentsFor(vendorKey, ym) {
      const arr = state.liquidacionPayments && state.liquidacionPayments[liquidacionPayKey(vendorKey, ym)];
      return Array.isArray(arr) ? arr : [];
    }
