    function saveDriverFuelRecord(driver) {
      const dateEl = document.getElementById("fuelInputDate");
      const vehEl = document.getElementById("fuelInputVehicle");
      const amtEl = document.getElementById("fuelInputAmount");
      const litEl = document.getElementById("fuelInputLiters");
      const photoEl = document.getElementById("fuelInputPhoto");
      const notesEl = document.getElementById("fuelInputNotes");
      const status = document.getElementById("fuelSaveStatus");

      const date = dateEl.value;
      const vehicleId = vehEl.value;
      const amount = Number.parseFloat(amtEl.value) || 0;
      const liters = litEl.value;
      const notes = notesEl.value.trim();

      if (!date) { status.textContent = "Falta la fecha"; status.style.color = "#B91C1C"; return; }
      if (amount <= 0) { status.textContent = "El monto debe ser mayor a 0"; status.style.color = "#B91C1C"; return; }

      // Vehiculo: empleados de Sineus => flota; tercerizados => auto propio.
      let vehicleLabel = "";
      if (driver.type === "EMPLEADO SINEUS") {
        const fv = (state.fleetVehicles || []).find((v) => v.id === vehicleId);
        if (fv) vehicleLabel = [fv.marca, fv.modelo].filter(Boolean).join(" ") + (fv.patente ? " (" + fv.patente + ")" : "");
      } else {
        const vehicle = (driver.vehicles || []).find((v) => v.id === vehicleId);
        if (vehicle) vehicleLabel = vehicle.label || ((vehicle.brand || "") + " " + (vehicle.model || "") + (vehicle.plate ? " (" + vehicle.plate + ")" : ""));
      }

      // CANDADO DOBLE TOQUE (07/09): a Héctor se le duplicó un ticket el 05/09 porque tocó
      // "Guardar" dos veces mientras la foto se procesaba (4 segundos entre uno y otro).
      // 1) El botón se bloquea apenas se toca. 2) Si ya existe un ticket idéntico (mismo
      // chofer, fecha, monto, litros y nota) cargado hace menos de 2 minutos, no se crea otro.
      const saveBtnEl = document.getElementById("saveFuelBtn");
      if (saveBtnEl && saveBtnEl.disabled) return;
      if (saveBtnEl) { saveBtnEl.disabled = true; saveBtnEl.textContent = "Guardando…"; }
      const unlockSaveBtn = () => { const b = document.getElementById("saveFuelBtn"); if (b) { b.disabled = false; b.textContent = "Guardar ticket"; } };
      const litersNum = Number.parseFloat(liters) || 0;
      const twin = (state.fuelRecords || []).find((r) => r && r.driverId === driver.id && r.date === date &&
        Math.abs((Number(r.amount) || 0) - amount) < 0.005 && Math.abs((Number.parseFloat(r.liters) || 0) - litersNum) < 0.005 &&
        String(r.notes || "").trim() === notes && (Date.now() - (Date.parse(r.createdAt || "") || 0)) < 2 * 60 * 1000);
      if (twin) {
        status.textContent = "Este ticket ya fue cargado hace un momento (no se duplicó).";
        status.style.color = "#B45309";
        unlockSaveBtn();
        return;
      }

      const proceed = async (receiptImage, receiptName) => {
        const record = normalizeFuelRecord({
          driverId: driver.id,
          driverName: (driver.name + " " + (driver.lastName || "")).trim(),
          vehicleId: vehicleId,
          vehicleLabel: vehicleLabel,
          date: date,
          amount: amount,
          liters: liters,
          receiptImage: receiptImage || "",
          receiptName: receiptName || "",
          notes: notes
        });
        status.textContent = "Guardando…"; status.style.color = "#64748b";
        if (!Array.isArray(state.fuelRecords)) state.fuelRecords = [];
        state.fuelRecords.push(record);
        saveFuelLocal();
        // AHORA esperamos la respuesta de la nube y confirmamos DE VERDAD.
        const err = await upsertFuelRecordRemote(record);
        if (err) {
          // No se guardó en la nube: lo sacamos del estado local para no mostrar algo falso.
          state.fuelRecords = (state.fuelRecords || []).filter((r) => r.id !== record.id);
          saveFuelLocal();
          console.warn("[Combustible] guardado rechazado:", err);
          status.textContent = "No se pudo guardar el ticket. Reintentá o avisá a la oficina.";
          status.style.color = "#B91C1C";
          unlockSaveBtn();
          renderDriverFuel(driver);
          return;
        }
        status.textContent = "Guardado correctamente";
        status.style.color = "#16A34A";
        setTimeout(() => { renderDriverFuel(driver); }, 600);
      };

      // Foto del ticket: se comprime ANTES de guardar. BLINDAJE (29/08): la foto NUNCA puede
      // trabar el guardado. Algunas fotos (ej. HEIC de iPhone) hacen que el navegador se cuelgue
      // procesándolas y el ticket no se guardaba nunca. Ahora, si tarda demasiado, se guarda el
      // ticket igual (sin la imagen) para no perder el gasto.
      const file = photoEl.files && photoEl.files[0];
      if (file) {
        status.textContent = "Procesando foto…"; status.style.color = "#64748b";
        const withTimeout = (p, ms) => Promise.race([
          p, new Promise((_, rej) => setTimeout(() => rej(new Error("timeout")), ms))
        ]);
        withTimeout(compressImageFile(file, 1000, 0.5), 9000)
          .then(async (dataUrl) => {
            // Si aún quedó muy pesada, un intento más chico; si no, se guarda sin foto.
            if (dataUrl && dataUrl.length > 1200000) {
              try { dataUrl = await withTimeout(compressImageFile(file, 800, 0.4), 7000); } catch (e) { dataUrl = ""; }
              if (dataUrl && dataUrl.length > 1200000) dataUrl = "";
            }
            proceed(dataUrl || "", dataUrl ? file.name : "");
          })
          .catch(() => {
            // La foto no se pudo procesar (formato raro / se colgó): guardamos SIN imagen.
            status.textContent = "La foto no se pudo adjuntar, pero el ticket se guardó.";
            status.style.color = "#B45309";
            setTimeout(() => proceed("", ""), 300);
          });
      } else {
        proceed("", "");
      }
    }

    function viewFuelPhoto(recordId) {
      const r = (state.fuelRecords || []).find((x) => x.id === recordId);
      if (!r || !r.receiptImage) return;
      const win = window.open("", "_blank");
      if (!win) return;
      win.document.write(
        '<html><head><title>Ticket combustible</title>' +
        '<style>body{margin:0;padding:20px;background:#1b3650;display:flex;align-items:center;justify-content:center;min-height:100vh;}' +
        'img{max-width:100%;max-height:90vh;border-radius:8px;box-shadow:0 8px 32px rgba(0,0,0,0.3);}</style>' +
        '</head><body><img src="' + r.receiptImage + '" alt="Ticket"></body></html>'
      );
    }

    function deleteFuelRecord(recordId, driver) {
      if (!confirm("Eliminar este ticket de combustible?")) return;
      state.fuelRecords = (state.fuelRecords || []).filter((r) => r.id !== recordId);
      saveFuelLocal();
      deleteFuelRecordRemote(recordId);
      renderDriverFuel(driver);
    }

    // ============== FINANZAS COMBUSTIBLE (vista directivos) ==============

    const fuelFinanceFilters = {
      from: "",
      to: "",
      driverId: "",
      vehicleId: ""
    };

    function renderFuelFinance() {
      const tbody = document.getElementById("fuelFinanceBody");
      const summary = document.getElementById("fuelFinanceSummary");
      if (!tbody) return;

      // Construir lista filtrada
      let records = (state.fuelRecords || []).slice();
      const f = fuelFinanceFilters;
      if (f.from) records = records.filter((r) => r.date >= f.from);
      if (f.to) records = records.filter((r) => r.date <= f.to);
      if (f.driverId) records = records.filter((r) => r.driverId === f.driverId);
      if (f.vehicleId) records = records.filter((r) => r.vehicleId === f.vehicleId);
      records.sort((a, b) => (b.date || "").localeCompare(a.date || ""));

      // Cargar opciones de filtros
      fillFuelFilterOptions();

      // Tabla
      tbody.innerHTML = "";
      if (records.length === 0) {
        tbody.innerHTML = '<tr><td colspan="7" class="conductor-empty">No hay registros de combustible para estos filtros.</td></tr>';
      } else {
        records.forEach((r) => {
          const tr = document.createElement("tr");
          tr.innerHTML =
            '<td>' + escapeHtml(displayDate(r.date) || r.date) + '</td>' +
            '<td><strong>' + escapeHtml(r.driverName) + '</strong></td>' +
            '<td>' + escapeHtml(r.vehicleLabel || "-") + '</td>' +
            '<td class="num">' + formatMoney(r.amount) + '</td>' +
            '<td class="num">' + (r.liters ? r.liters + " lt" : "-") + '</td>' +
            '<td>' + escapeHtml(r.notes || "-") + '</td>' +
            '<td>' + (r.receiptImage ? '<button class="btn-tiny btn-tiny-info" data-action="view-fuel-photo-admin" data-id="' + escapeHtml(r.id) + '">Ver foto</button>' : '<span style="color:#B91C1C;font-size:11px;">Sin foto</span>') + '</td>';
          tbody.append(tr);
        });
      }

      // Summary
      const total = records.reduce((s, r) => s + r.amount, 0);
      const byDriver = {};
      const byVehicle = {};
      records.forEach((r) => {
        const dKey = r.driverName || "(sin chofer)";
        byDriver[dKey] = (byDriver[dKey] || 0) + r.amount;
        const vKey = r.vehicleLabel || "(sin vehiculo)";
        byVehicle[vKey] = (byVehicle[vKey] || 0) + r.amount;
      });
      const topDriver = Object.entries(byDriver).sort((a, b) => b[1] - a[1])[0];
      const topVehicle = Object.entries(byVehicle).sort((a, b) => b[1] - a[1])[0];

      if (summary) {
        summary.innerHTML =
          '<div class="finance-summary-card"><p class="label">Registros</p><p class="value">' + records.length + '</p></div>' +
          '<div class="finance-summary-card"><p class="label">Gasto total</p><p class="value red">' + formatMoney(total) + '</p></div>' +
          '<div class="finance-summary-card"><p class="label">Choferes</p><p class="value">' + Object.keys(byDriver).length + '</p></div>' +
          '<div class="finance-summary-card"><p class="label">Vehiculos</p><p class="value">' + Object.keys(byVehicle).length + '</p></div>' +
          (topDriver ? '<div class="finance-summary-card"><p class="label">Chofer top</p><p class="value" style="font-size:12px;">' + escapeHtml(topDriver[0]) + '<br><span style="font-size:11px;color:#B91C1C;">' + formatMoney(topDriver[1]) + '</span></p></div>' : '') +
          (topVehicle ? '<div class="finance-summary-card"><p class="label">Vehiculo top</p><p class="value" style="font-size:12px;">' + escapeHtml(topVehicle[0]) + '<br><span style="font-size:11px;color:#B91C1C;">' + formatMoney(topVehicle[1]) + '</span></p></div>' : '');
      }

      // Handlers para ver foto
      tbody.querySelectorAll("[data-action='view-fuel-photo-admin']").forEach((btn) => {
        btn.addEventListener("click", () => viewFuelPhoto(btn.getAttribute("data-id")));
      });
    }

    function fillFuelFilterOptions() {
      const driverSel = document.getElementById("fuelFilterDriver");
      const vehicleSel = document.getElementById("fuelFilterVehicle");
      if (!driverSel) return;

      // Choferes empleados (solo ellos cargan combustible)
      const empleados = (state.drivers || []).filter((d) => d.type === "EMPLEADO SINEUS");
      driverSel.innerHTML = '<option value="">Todos los choferes</option>' +
        empleados.map((d) => {
          const sel = fuelFinanceFilters.driverId === d.id ? " selected" : "";
          const name = (d.name + " " + (d.lastName || "")).trim();
          return '<option value="' + escapeHtml(d.id) + '"' + sel + '>' + escapeHtml(name) + '</option>';
        }).join("");

      // Vehiculos de todos los empleados
      const allVehicles = [];
      empleados.forEach((d) => {
        (d.vehicles || []).forEach((v) => {
          allVehicles.push({ id: v.id, label: v.label || (v.brand + " " + v.model + " (" + v.plate + ")") });
        });
      });
      vehicleSel.innerHTML = '<option value="">Todos los vehiculos</option>' +
        allVehicles.map((v) => {
          const sel = fuelFinanceFilters.vehicleId === v.id ? " selected" : "";
          return '<option value="' + escapeHtml(v.id) + '"' + sel + '>' + escapeHtml(v.label) + '</option>';
        }).join("");
    }

    function setupFuelFinanceHandlers() {
      const fromEl = document.getElementById("fuelFilterFrom");
      const toEl = document.getElementById("fuelFilterTo");
      const driverSel = document.getElementById("fuelFilterDriver");
      const vehicleSel = document.getElementById("fuelFilterVehicle");
      const clearBtn = document.getElementById("fuelFilterClear");

      // Preset rapidos: hoy, semana, mes
      document.querySelectorAll("[data-fuel-preset]").forEach((btn) => {
        btn.addEventListener("click", () => {
          const preset = btn.getAttribute("data-fuel-preset");
          const today = new Date();
          const fmt = (d) => d.toISOString().split("T")[0];
          if (preset === "today") {
            fuelFinanceFilters.from = fmt(today);
            fuelFinanceFilters.to = fmt(today);
          } else if (preset === "week") {
            const start = new Date(today);
            start.setDate(today.getDate() - today.getDay()); // Domingo
            fuelFinanceFilters.from = fmt(start);
            fuelFinanceFilters.to = fmt(today);
          } else if (preset === "month") {
            const start = new Date(today.getFullYear(), today.getMonth(), 1);
            fuelFinanceFilters.from = fmt(start);
            fuelFinanceFilters.to = fmt(today);
          } else if (preset === "all") {
            fuelFinanceFilters.from = "";
            fuelFinanceFilters.to = "";
          }
          if (fromEl) fromEl.value = fuelFinanceFilters.from;
          if (toEl) toEl.value = fuelFinanceFilters.to;
          renderFuelFinance();
        });
      });

      if (fromEl) fromEl.addEventListener("change", () => { fuelFinanceFilters.from = fromEl.value; renderFuelFinance(); });
      if (toEl) toEl.addEventListener("change", () => { fuelFinanceFilters.to = toEl.value; renderFuelFinance(); });
      if (driverSel) driverSel.addEventListener("change", () => { fuelFinanceFilters.driverId = driverSel.value; renderFuelFinance(); });
      if (vehicleSel) vehicleSel.addEventListener("change", () => { fuelFinanceFilters.vehicleId = vehicleSel.value; renderFuelFinance(); });
      if (clearBtn) clearBtn.addEventListener("click", () => {
        fuelFinanceFilters.from = "";
        fuelFinanceFilters.to = "";
        fuelFinanceFilters.driverId = "";
        fuelFinanceFilters.vehicleId = "";
        if (fromEl) fromEl.value = "";
        if (toEl) toEl.value = "";
        if (driverSel) driverSel.value = "";
        if (vehicleSel) vehicleSel.value = "";
        renderFuelFinance();
      });
    }

    // ETAPA 3 subgrupos (04/09): deriva el "tipo" de servicio de un subgrupo a partir de SUS
    // paradas (para que la zona/tarifa se calcule bien por subgrupo). Espeja serviceTypeFromTourSteps
    // pero trabaja sobre stops (region/experience).
    function subTypeFromStops(stops) {
      var up = function (s) { return String(s || "").toUpperCase(); };
      stops = Array.isArray(stops) ? stops : [];
      if (stops.length && stops.every(function (s) { return up(s.experience).indexOf("CENA") !== -1; })) return "CENA";
      if (stops.some(function (s) { return up(s.region).indexOf("ALTA MONTA") !== -1; })) return "ALTA MONTANA";
      var regions = [];
      stops.forEach(function (s) { var t = regionServiceType(s.region); if (t && regions.indexOf(t) < 0) regions.push(t); });
      return regions.length ? regions.join(" / ") : "PASEO";
    }

    // Returns all trips of this driver across all clients and time
    function buildDriverTrips(driver) {
      const trips = [];
      // FIX PANEL CHOFER (05/08): la ficha guarda nombre y apellido POR SEPARADO, pero
      // Logistica guarda el nombre COMPLETO en la asignacion ("CARLOS ANGULO"). Antes se
      // comparaba solo con driver.name (nombre de pila) => casi ningun viaje coincidia y el
      // chofer no veia NADA en su panel. Ahora se compara por nombre COMPLETO (name + lastName)
      // + sub-choferes + el nombre de pila SOLO si es unico entre todos (para no mezclar dos
      // "ANDRES" u "OSCAR"). Verificado con datos reales: cada chofer ve exactamente lo suyo.
      const fullName = (driver.name + " " + (driver.lastName || "")).trim();
      const driverNames = [fullName];
      const firstLower = String(driver.name || "").trim().toLowerCase();
      const firstNameShared = (state.drivers || []).filter((d) => String(d.name || "").trim().toLowerCase() === firstLower).length > 1;
      if (driver.name && !firstNameShared) driverNames.push(driver.name);
      (driver.subDrivers || []).forEach((s) => driverNames.push(s.name));

      // Helper: chequea si un nombre dado coincide con el driver
      const matchesThisDriver = (name) => {
        if (!name) return false;
        if (driverNames.some((dn) => sameText(dn, name) || sameText(name, dn + " (de " + driver.name + ")"))) return true;
        if (driver.subDrivers && driver.subDrivers.some((s) => sameText(s.name, name))) return true;
        return false;
      };
      // Emparejamiento REFORZADO (07/08): primero por ID de ficha (a prueba de nombres
      // repetidos o sin apellido), y si no hay ID, por nombre (como antes).
      const assignMatches = (a) => {
        if (!a) return false;
        if (a.driverId) return a.driverId === driver.id;
        return matchesThisDriver(a.driver);
      };
      const serviceMainMatches = (service) => {
        if (service.driverId) return service.driverId === driver.id;
        return matchesThisDriver(service.driver);
      };

      (state.clients || []).forEach((client) => {
        (client.services || []).forEach((service, idx) => {
          // Determinar si este chofer participa en el servicio (sea como principal o en assignments)
          let myAssignment = null;
          let myAssignmentIndex = -1;
          if (Array.isArray(service.assignments) && service.assignments.length > 0) {
            myAssignmentIndex = service.assignments.findIndex((a) => assignMatches(a));
            myAssignment = myAssignmentIndex >= 0 ? service.assignments[myAssignmentIndex] : null;
            if (!myAssignment && !serviceMainMatches(service)) return;
          } else {
            if (!serviceMainMatches(service)) return;
          }

          // Determinar driver/vehicle/pax para este chofer en este servicio
          const myDriver = myAssignment ? myAssignment.driver : service.driver;
          const myVehicle = myAssignment ? myAssignment.vehicle : service.vehicle;
          const myPax = myAssignment ? (myAssignment.pax || 0) : (service.pax || 0);

          // ETAPA 2 subgrupos (04/09): si este chofer cubre un SUBGRUPO puntual (su asignación
          // tiene personas), le mostramos SOLO las actividades de su subgrupo, con su horario y
          // región. Si no es subgrupo, ve todo el servicio como siempre.
          var _mySig = (myAssignment && Array.isArray(myAssignment.participants) && myAssignment.participants.length)
            ? participantsSig(myAssignment.participants) : "";
          var _allStops = Array.isArray(service.stops) ? service.stops : [];
          var _myStops = _allStops;
          if (_mySig) {
            var _sm = stepParticipantsMapForClient(client);
            var _f = _allStops.filter(function (st) { return participantsSig(stopParticipants(st, _sm)) === _mySig; });
            if (_f.length) _myStops = _f;
          }
          var _myTimes = _myStops.map(function (s) { return (s.time || "").trim(); }).filter(Boolean).sort();
          var _myPickup = (_mySig && _myTimes.length) ? _myTimes[0] : (service.pickup || service.time || "");
          var _myTime   = (_mySig && _myTimes.length) ? _myTimes[0] : (service.time || service.pickup || ""); // mismo orden que antes
          var _myRegions = [];
          _myStops.forEach(function (s) { var r = (s.region || "").trim(); if (r && _myRegions.indexOf(r) < 0) _myRegions.push(r); });
          var _myTypeLabel = (_mySig && _myRegions.length) ? _myRegions.slice(0, 2).join(" / ") : (service.type || "");

          trips.push({
            clientId: client.id,
            // RESPONSABLE (07/09): si la ficha es una agencia, el chofer ve a la persona de referencia.
            clientName: (function () { try { const _li = tripLeadInfo(client); return _li ? tripLeadLabel(_li) : fullClientName(client); } catch (e) { return fullClientName(client); } })(),
            bookingName: fullClientName(client),
            clientNumber: client.number || "",
            date: service.date,
            time: _myTime,
            region: (_mySig && _myRegions.length) ? _myRegions[0] : (service.region || ""),
            type: _myTypeLabel || service.type || "",
            providerName: service.providerName || "",
            serviceName: service.serviceName || "",
            // Hotel de RETIRO + aviso de cambio de hotel, MISMA logica que el mensaje de
            // Logistica (buildWhatsappMessage): en paseos/traslados el chofer levanta a los
            // pasajeros desde el hotel donde AMANECEN (noche anterior); si el hotel de destino
            // es distinto, se avisa "cambio de hotel". (10/08)
            hotel: (function () {
              try {
                var isTour = Array.isArray(service.stops) && service.stops.length > 0;
                var isTransfer = String(service.type || "").toUpperCase().indexOf("TRASLADO") !== -1;
                if (isTour || isTransfer) {
                  var prev = shiftIsoDate(service.date, -1);
                  return hotelDetailsForDate(client, prev) || hotelDetailsForDate(client, service.date) || service.hotel || "";
                }
                return hotelDetailsForDate(client, service.date) || service.hotel || "";
              } catch (e) { return service.hotel || ""; }
            })(),
            hotelChange: (function () {
              try {
                var isTour = Array.isArray(service.stops) && service.stops.length > 0;
                var isTransfer = String(service.type || "").toUpperCase().indexOf("TRASLADO") !== -1;
                if (!(isTour || isTransfer)) return "";
                var prev = shiftIsoDate(service.date, -1);
                var dep = hotelDetailsForDate(client, prev) || hotelDetailsForDate(client, service.date) || "";
                var dest = hotelDetailsForDate(client, service.date) || "";
                if (dest && dep && dep !== "-" && !sameText(dep, dest)) return dest;
                return "";
              } catch (e) { return ""; }
            })(),
            pax: myPax || (_mySig && myAssignment ? (myAssignment.participants.length || 0) : 0) || service.pax || (service.participantCount != null ? service.participantCount : 0) || (Array.isArray(service.participants) ? service.participants.length : 0) || (Array.isArray(client.participants) ? client.participants.length : 0) || paxCount(client) || 0,
            status: service.status || "PENDIENTE",
            driver: myDriver || "",
            vehicle: myVehicle || "",
            itinerary: service.itinerary || "",
            flight: service.flightNumber || "",
            observations: service.observations || service.notes || "",
            driverNotice: service.driverNotice || "",
            // Fichas plegables (06/08): salida + paradas (bodegas con horario) para el detalle.
            pickup: _myPickup,
            stops: Array.isArray(_myStops) ? _myStops.map(function (s) {
              return { time: s.time || "", provider: s.provider || "", experience: s.experience || "" };
            }).filter(function (s) { return s.provider || s.experience; }) : [],
            // Indices para buscar el servicio original al marcar pagado
            _clientId: client.id,
            _serviceIndex: idx,
            _isMultiAssigned: Array.isArray(service.assignments) && service.assignments.length > 0,
            // ETAPA 3 subgrupos: datos del subgrupo de ESTE chofer, para liquidar por su parte
            // (zona + pax del subgrupo, no del día completo). Vacío si no es subgrupo.
            _subStops: _mySig ? _myStops : null,
            _subType: _mySig ? subTypeFromStops(_myStops) : "",
            _subPax: _mySig ? (myPax || (myAssignment ? myAssignment.participants.length : 0) || 0) : 0,
            // Índice de la asignación de este chofer (para el importe manual por subgrupo). -1 = ninguna.
            _assignmentIndex: myAssignmentIndex,
            // ¿El día está dividido entre choferes distintos? (para decidir override por subgrupo vs por día)
            _isSplitDay: Array.isArray(service.assignments) && service.assignments.filter(function (a) { return a && Array.isArray(a.participants) && a.participants.length; }).length >= 2
          });
        });
      });
      // Ordenar por fecha + hora
      trips.sort((a, b) => {
        const ka = sortableDate(a.date) + " " + (a.time || "");
        const kb = sortableDate(b.date) + " " + (b.time || "");
        return ka.localeCompare(kb);
      });
      return trips;
    }

    function fullClientName(client) {
      if (!client) return "";
      const parts = [];
      if (client.firstName) parts.push(client.firstName);
      if (client.lastName) parts.push(client.lastName);
      return parts.join(" ").trim() || client.name || "";
    }

    function renderDriverPanelStats(driver, trips) {
      const today = new Date();
      const todayKey = sortableDate(formatDateLocal(today));
      const weekStart = new Date(today);
      weekStart.setDate(today.getDate() - today.getDay());
      const weekStartKey = sortableDate(formatDateLocal(weekStart));
      const weekEnd = new Date(weekStart);
      weekEnd.setDate(weekStart.getDate() + 7);
      const weekEndKey = sortableDate(formatDateLocal(weekEnd));
      const month = today.getMonth();
      const year = today.getFullYear();

      const todayCount = trips.filter((t) => sortableDate(t.date) === todayKey).length;
      const weekCount = trips.filter((t) => {
        const k = sortableDate(t.date);
        return k >= weekStartKey && k < weekEndKey;
      }).length;
      // Liquidacion del mes
      const monthTrips = trips.filter((t) => {
        const d = parseLocalDate(t.date);
        return d && d.getMonth() === month && d.getFullYear() === year;
      });
      const monthAmount = monthTrips.reduce((sum, t) => sum + driverTripPayable(t, driver), 0);

      const stats = document.getElementById("driverPanelStats");
      stats.innerHTML = [
        '<div class="driver-panel-stat"><p class="label">Hoy</p><p class="value blue">' + todayCount + (todayCount === 1 ? ' viaje' : ' viajes') + '</p></div>',
        '<div class="driver-panel-stat"><p class="label">Esta semana</p><p class="value">' + weekCount + (weekCount === 1 ? ' viaje' : ' viajes') + '</p></div>',
        '<div class="driver-panel-stat"><p class="label">Liquidacion ' + monthNames[month].toLowerCase() + '</p><p class="value green">' + formatMoney(monthAmount) + '</p></div>'
      ].join("");
    }

    // Returns the agreed driver-fee amount for one trip according to rates table.
    // We use the type/region and driver type. Defensive: zero if can't compute.
    function rateAmountForTrip(trip, driver) {
      try {
        // Buscar tarifa por region o por type
        const label = trip.region || trip.type;
        if (!label) return 0;
        // Coincidencia por nombre NORMALIZADO (sin acentos ni mayus/minus): asi "Alta Montana"
        // matchea con "ALTA MONTAÑA", "LUJAN DE CUYO" con "LUJÁN DE CUYO", etc. (24/08)
        const wanted = latinKey(label);
        let rate = null;
        const rmap = state.rates || {};
        for (const k in rmap) { if (latinKey(k) === wanted) { rate = rmap[k]; break; } }
        if (!rate) return 0;
        const isEmployee = driver.type === "EMPLEADO SINEUS";
        const typeKey = isEmployee ? "employee" : "thirdParty";
        const rangeKey = paxRange(trip.pax || 0); // "Small" (1-4) o "Large" (5+)
        const val = rate[typeKey + rangeKey];
        return Number.parseFloat(val || "0") || 0;
      } catch { return 0; }
    }

    function parseLocalDate(s) {
      if (!s) return null;
      const parts = String(s).split("-");
      if (parts.length < 3) return null;
      return new Date(Number(parts[0]), Number(parts[1]) - 1, Number(parts[2]));
    }

    function formatDateLocal(d) {
      const m = String(d.getMonth() + 1).padStart(2, "0");
      const day = String(d.getDate()).padStart(2, "0");
      return d.getFullYear() + "-" + m + "-" + day;
    }

    function renderDriverTrips(driver, allTrips) {
      const list = document.getElementById("driverTripsList");
      const filterSel = document.getElementById("driverTripsFilter");
      const searchInput = document.getElementById("driverTripsSearch");
      const filter = filterSel ? filterSel.value : "all";
      const query = latinKey(searchInput ? searchInput.value : "");

      const today = new Date();
      const todayKey = sortableDate(formatDateLocal(today));
      const weekStart = new Date(today);
      weekStart.setDate(today.getDate() - today.getDay());
      const weekStartKey = sortableDate(formatDateLocal(weekStart));
      const weekEnd = new Date(weekStart);
      weekEnd.setDate(weekStart.getDate() + 7);
      const weekEndKey = sortableDate(formatDateLocal(weekEnd));

      let visible = allTrips.slice();
      if (filter === "today") visible = visible.filter((t) => sortableDate(t.date) === todayKey);
      else if (filter === "week") visible = visible.filter((t) => {
        const k = sortableDate(t.date);
        return k >= weekStartKey && k < weekEndKey;
      });
      else if (filter === "month") visible = visible.filter((t) => {
        const d = parseLocalDate(t.date);
        return d && d.getMonth() === today.getMonth() && d.getFullYear() === today.getFullYear();
      });
      else if (filter === "future") visible = visible.filter((t) => sortableDate(t.date) >= todayKey);
      else if (filter === "past") visible = visible.filter((t) => sortableDate(t.date) < todayKey);

      if (query) {
        visible = visible.filter((t) => {
          const text = latinKey([t.clientName, t.region, t.providerName, t.serviceName, t.hotel, t.date, t.flight, t.observations].join(" "));
          return text.includes(query);
        });
      }

      list.innerHTML = "";
      if (!visible.length) {
        list.innerHTML = '<div class="driver-empty-state">No hay viajes para mostrar con los filtros actuales.</div>';
        return;
      }

      // Mas nuevos ARRIBA (06/08): ordenamos descendente por fecha + hora.
      visible.sort(function (a, b) {
        var kb = sortableDate(b.date) + " " + (b.time || "");
        var ka = sortableDate(a.date) + " " + (a.time || "");
        return kb.localeCompare(ka);
      });
      visible.forEach(function (trip) { list.append(renderDriverTripCard(trip, todayKey)); });
    }

    // ===== FICHA DE VIAJE PLEGABLE (06/08) — compartida por Mis Viajes y Liquidacion =====
    function tripServiceLabel(trip) {
      return String(trip.type || trip.region || trip.serviceName || "Servicio").toUpperCase();
    }
    function tripDetailHtml(trip) {
      var html = "";
      // Aviso de dirección para este servicio (🔔), destacado arriba de todo.
      if (trip.driverNotice) html += '<div class="tripcard-notice">🔔 ' + escapeHtml(trip.driverNotice) + '</div>';
      // BLOQUE CLAVE para el chofer: a qué hora salir, de qué hotel retirar y en qué auto.
      // Se muestra SIEMPRE (con "a confirmar/coordinar" si falta), porque son los datos que
      // el chofer necesita sí o sí. (10/08)
      var key = "";
      key += '<div class="tripcard-key' + (trip.pickup ? '' : ' is-missing') + '">🕐 <b>Salida:</b> ' + (trip.pickup ? escapeHtml(trip.pickup) : 'a coordinar') + '</div>';
      key += '<div class="tripcard-key' + (trip.hotel ? '' : ' is-missing') + '">🏨 <b>Retirar en:</b> ' + (trip.hotel ? escapeHtml(trip.hotel) : 'a confirmar') + '</div>';
      if (trip.hotelChange) key += '<div class="tripcard-key tripcard-key-change">🏢 <b>Cambio de hotel,</b> se queda en ' + escapeHtml(trip.hotelChange) + '</div>';
      key += '<div class="tripcard-key' + (trip.vehicle ? '' : ' is-missing') + '">🚗 <b>Vehículo:</b> ' + (trip.vehicle ? escapeHtml(trip.vehicle) : 'a confirmar') + '</div>';
      var paxN = Number(trip.pax) || 0;
      if (paxN) key += '<div class="tripcard-key">👥 <b>Pasajeros:</b> ' + paxN + '</div>';
      if (trip.flight) key += '<div class="tripcard-key">✈️ <b>Vuelo:</b> ' + escapeHtml(trip.flight) + '</div>';
      html += '<div class="tripcard-keybox">' + key + '</div>';
      if (Array.isArray(trip.stops) && trip.stops.length) {
        var stops = trip.stops.map(function (s) {
          return '<div class="tripcard-stop"><b>📍 ' + escapeHtml(s.time || '') + '</b><span>' + escapeHtml(s.provider || '') + (s.experience ? ' — ' + escapeHtml(s.experience) : '') + '</span></div>';
        }).join("");
        html += '<div class="tripcard-stops">' + stops + '</div>';
      }
      if (trip.observations) html += '<div class="tripcard-obs">📝 ' + escapeHtml(trip.observations) + '</div>';
      return html;
    }
    // cfg: {dateLabel, paid, paxName, serviceLabel, priceLabel, detailHtml, footerHtml, dataAttrs}
    function buildTripCardEl(cfg) {
      var card = document.createElement("div");
      card.className = "tripcard" + (cfg.paid ? " paid" : "");
      if (cfg.dataAttrs) Object.keys(cfg.dataAttrs).forEach(function (k) { card.setAttribute(k, cfg.dataAttrs[k]); });
      card.innerHTML =
        '<div class="tripcard-sum">' +
          '<span class="tripcard-date">' + escapeHtml(cfg.dateLabel || '') + '</span>' +
          '<span class="tripcard-chev">›</span>' +
          '<span class="tripcard-pax">' + (cfg.hasNotice ? '<span class="tripcard-bell">🔔</span> ' : '') + escapeHtml(cfg.paxName || '') + '</span>' +
          '<span class="tripcard-svc">' + escapeHtml(cfg.serviceLabel || '') + '</span>' +
          (cfg.priceLabel ? '<span class="tripcard-price">' + escapeHtml(cfg.priceLabel) + '</span>' : '<span></span>') +
        '</div>' +
        '<div class="tripcard-detail">' + (cfg.detailHtml || '') + (cfg.footerHtml || '') + '</div>';
      card.querySelector(".tripcard-sum").addEventListener("click", function () { card.classList.toggle("open"); });
      return card;
    }
    function renderDriverTripCard(trip, todayKey) {
      var tripDateKey = sortableDate(trip.date);
      var card = buildTripCardEl({
        dateLabel: displayDate(trip.date) || "",
        paxName: trip.clientName,
        serviceLabel: tripServiceLabel(trip),
        hasNotice: !!trip.driverNotice,
        detailHtml: tripDetailHtml(trip)
      });
      if (tripDateKey === todayKey) card.classList.add("is-today");
      else if (tripDateKey < todayKey) card.classList.add("is-past");
      return card;
    }

    // Monto del servicio segun el MOTOR NUEVO (tabla de tarifas propios/terceros + deteccion).
    // Unifica el numero: el panel del chofer y la pantalla de Finanzas usan lo mismo.
    function newEngineAmountForTrip(t, driver) {
      const client = state.clients.find((c) => c.id === t._clientId);
      const service = client && client.services ? client.services[t._serviceIndex] : null;
      if (!client || !service) return 0;
      const key = serviceTariffKey(client.id, service);
      const ovr = state.driverTariffOverrides ? state.driverTariffOverrides[key] : null;
      // ETAPA 3 subgrupos: si el viaje es de un subgrupo, la zona y el pax se calculan sobre SU
      // parte (sus paradas + sus pasajeros), no sobre el día completo.
      const isSub = t && Array.isArray(t._subStops) && t._subStops.length > 0;
      const svcForZona = isSub ? Object.assign({}, service, { stops: t._subStops, type: t._subType || service.type }) : service;
      const zona = (ovr != null) ? ovr : suggestDriverZone(svcForZona, client, driver.type).zona;
      const pax = isSub ? (t._subPax || t.pax || paxCount(client))
                        : (service.participantCount != null ? service.participantCount : paxCount(client));
      const p = driverTariffPrice(driver.type, zona, pax);
      return (p === "" || p == null) ? 0 : (Number(p) || 0);
    }
    // Importe manual efectivo de un viaje: por SUBGRUPO si el día está dividido entre choferes
    // distintos (usa el override de la asignación de este chofer); si no, el override por servicio (día).
    // "" = no hay manual, se usa el cálculo automático.
    function tripManualOverrideValue(t) {
      try {
        const client = state.clients.find((c) => c.id === t._clientId);
        const service = client && client.services ? client.services[t._serviceIndex] : null;
        if (!service) return "";
        if (t && t._isSplitDay && t._assignmentIndex >= 0 &&
            Array.isArray(service.assignments) && service.assignments[t._assignmentIndex]) {
          const ov = service.assignments[t._assignmentIndex].amountOverride;
          return (ov != null && ov !== "") ? String(ov) : "";
        }
        return (service.driverAmountOverride != null && service.driverAmountOverride !== "") ? String(service.driverAmountOverride) : "";
      } catch (e) { return ""; }
    }
    // Monto a pagar de un viaje para el chofer: override manual si existe, si no el motor nuevo.
    // MISMA cuenta que usa la pestaña "Mi Liquidación", para que los totales coincidan. (24/08)
    function driverTripPayable(t, driver) {
      try {
        const override = tripManualOverrideValue(t);
        if (override !== "") return Number.parseFloat(override) || 0;
        return newEngineAmountForTrip(t, driver) || 0;
      } catch (e) { return 0; }
    }
    function renderDriverLiquidation(driver, allTrips) {
      const content = document.getElementById("driverLiquidationContent");
      const today = new Date();
      const defaultMonth = today.getMonth();
      const defaultYear = today.getFullYear();

      // Persistir filtro de mes/anio entre renders
      if (state.driverLiquidationMonth == null) state.driverLiquidationMonth = defaultMonth;
      if (state.driverLiquidationYear == null) state.driverLiquidationYear = defaultYear;
      const month = state.driverLiquidationMonth;
      const year = state.driverLiquidationYear;

      const monthTrips = allTrips.filter((t) => {
        const d = parseLocalDate(t.date);
        return d && d.getMonth() === month && d.getFullYear() === year;
      });

      // Calcular totales
      let totalAmount = 0, paidAmount = 0, pendingAmount = 0;
      const enriched = monthTrips.map((t) => {
        // Buscar el servicio original primero para detectar override
        const client = state.clients.find((c) => c.id === t._clientId);
        const service = client && client.services ? client.services[t._serviceIndex] : null;
        // Tarifa convenio (MOTOR NUEVO: tabla de tarifas propios/terceros + deteccion por zona).
        const conventionAmount = newEngineAmountForTrip(t, driver) || 0;
        // Override del directivo (si existe): por subgrupo si el día está dividido, si no por servicio.
        const override = tripManualOverrideValue(t);
        const hasOverride = override !== "";
        const amount = hasOverride ? (Number.parseFloat(override) || 0) : conventionAmount;
        totalAmount += amount;
        const paid = service && service.driverPaidDate;
        const paymentMethod = service ? (service.driverPaymentMethod || "TRANSFERENCIA") : "TRANSFERENCIA";
        const paymentDate = service ? service.driverPaidDate : "";
        if (paid) paidAmount += amount;
        else pendingAmount += amount;
        return {
          ...t,
          amount: amount,
          conventionAmount: conventionAmount,
          paid: !!paid,
          paymentMethod: paymentMethod,
          paymentDate: paymentDate || "",
          serviceRef: service,
          clientRef: client
        };
      }).sort((a, b) => (a.date || "").localeCompare(b.date || ""));

      // Selector de mes/anio
      const yearOptions = [];
      for (let y = defaultYear - 2; y <= defaultYear + 1; y++) {
        yearOptions.push('<option value="' + y + '"' + (y === year ? ' selected' : '') + '>' + y + '</option>');
      }
      const monthOptions = monthNames.map((n, i) =>
        '<option value="' + i + '"' + (i === month ? ' selected' : '') + '>' + n + '</option>').join("");

      let html =
        '<div class="liq-header-bar">' +
          '<div class="liq-title">' +
            '<h3>Liquidacion - ' + escapeHtml((driver.name + " " + (driver.lastName || "")).trim()) + '</h3>' +
            '<div class="liq-period-selectors">' +
              '<select id="liqMonthSel" class="liq-period-sel">' + monthOptions + '</select>' +
              '<select id="liqYearSel" class="liq-period-sel">' + yearOptions.join("") + '</select>' +
              '<button type="button" id="liqDownloadBtn" class="liq-download-btn">⬇ Descargar</button>' +
            '</div>' +
          '</div>' +
          '<div class="liq-summary-cards">' +
            '<div class="liq-card"><div class="lbl">Servicios</div><div class="val">' + monthTrips.length + '</div></div>' +
            '<div class="liq-card"><div class="lbl">Total a pagar</div><div class="val">' + formatMoney(totalAmount) + '</div></div>' +
            '<div class="liq-card paid"><div class="lbl">Pagado</div><div class="val">' + formatMoney(paidAmount) + '</div></div>' +
            '<div class="liq-card pending"><div class="lbl">Pendiente</div><div class="val">' + formatMoney(pendingAmount) + '</div></div>' +
          '</div>' +
        '</div>';

      if (monthTrips.length === 0) {
        html += '<div class="driver-empty-state">Sin servicios prestados en ' + monthNames[month] + ' ' + year + '.</div>';
      } else {
        var isDirectivo = canManageDriverFinance(state.currentUser);
        // Mas nuevos arriba (06/08)
        enriched.sort(function (a, b) { return sortableDate(b.date).localeCompare(sortableDate(a.date)); });
        html += '<div class="tripcard-list">';
        enriched.forEach(function (t) {
          var service = t.serviceRef;
          // t.amount ya es el importe EFECTIVO (manual por subgrupo/día si hay, si no el automático).
          var displayAmount = t.amount;
          var footer = '<div class="tripcard-foot">' +
            '<span class="pill ' + (t.paid ? 'ok' : 'pend') + '">' + (t.paid ? 'PAGADO' : 'PENDIENTE') + '</span>';
          if (isDirectivo) {
            footer += '<span class="liq-amount-wrap">$ <input type="number" step="any" min="0" class="liq-amount-input" value="' + (displayAmount || "") + '" placeholder="0" data-orig-amount="' + (t.conventionAmount || 0) + '" data-assign-idx="' + (t._assignmentIndex != null ? t._assignmentIndex : -1) + '" data-split="' + (t._isSplitDay ? '1' : '0') + '"></span>';
          } else {
            footer += '<span class="tripcard-amount">' + (displayAmount > 0 ? formatMoney(displayAmount) : '-') + '</span>';
          }
          footer += '</div>';
          if (isDirectivo) {
            footer += '<div class="tripcard-foot liq-pay-row">' +
              '<label class="liq-pay-field">Fecha pago<input type="date" class="liq-paydate" value="' + (t.paymentDate || "") + '"></label>' +
              '<label class="liq-pay-field">Medio ' + liqPaymentMethodSelect(t.paymentMethod) + '</label>' +
            '</div>';
          } else if (t.paid && t.paymentDate) {
            footer += '<div class="tripcard-paidinfo">Pagado el ' + escapeHtml(displayDate(t.paymentDate)) + (t.paymentMethod ? ' · ' + escapeHtml(t.paymentMethod) : '') + '</div>';
          }
          html += '<div class="tripcard' + (t.paid ? ' paid' : '') + '" data-liq-client="' + escapeHtml(t._clientId) + '" data-liq-svc-idx="' + t._serviceIndex + '">' +
            '<div class="tripcard-sum">' +
              '<span class="tripcard-date">' + escapeHtml(displayDate(t.date)) + '</span>' +
              '<span class="tripcard-chev">›</span>' +
              '<span class="tripcard-pax">' + (t.driverNotice ? '<span class="tripcard-bell">🔔</span> ' : '') + escapeHtml(t.clientName) + '</span>' +
              '<span class="tripcard-svc">' + escapeHtml(tripServiceLabel(t)) + '</span>' +
              '<span class="tripcard-price">' + (displayAmount > 0 ? formatMoney(displayAmount) : '-') + '</span>' +
            '</div>' +
            '<div class="tripcard-detail">' + tripDetailHtml(t) + footer + '</div>' +
          '</div>';
        });
        html += '</div>';
      }

      content.innerHTML = html;

      // Listeners de los selectores
      const mSel = document.getElementById("liqMonthSel");
      const ySel = document.getElementById("liqYearSel");
      if (mSel) mSel.addEventListener("change", () => {
        state.driverLiquidationMonth = Number.parseInt(mSel.value, 10);
        renderDriverLiquidation(driver, allTrips);
      });
      if (ySel) ySel.addEventListener("change", () => {
        state.driverLiquidationYear = Number.parseInt(ySel.value, 10);
        renderDriverLiquidation(driver, allTrips);
      });

      // Plegar/desplegar cada ficha al tocar su resumen
      content.querySelectorAll(".tripcard .tripcard-sum").forEach(function (sum) {
        sum.addEventListener("click", function () { sum.parentElement.classList.toggle("open"); });
      });

      // Descargar planilla (Excel)
      var dlBtn = document.getElementById("liqDownloadBtn");
      if (dlBtn) dlBtn.addEventListener("click", function () {
        downloadDriverLiquidation(driver, enriched, month, year);
      });

      // Listeners de fecha pago / medio pago / monto (solo dirección) — dentro de cada ficha
      content.querySelectorAll(".tripcard[data-liq-client]").forEach(function (card) {
        var clientId = card.getAttribute("data-liq-client");
        var svcIdx = Number.parseInt(card.getAttribute("data-liq-svc-idx"), 10);
        var dateInput = card.querySelector(".liq-paydate");
        var methodSel = card.querySelector(".liq-paymethod");
        var amountInput = card.querySelector(".liq-amount-input");
        if (dateInput) dateInput.addEventListener("change", function () {
          var client = state.clients.find(function (c) { return c.id === clientId; });
          if (!client || !client.services[svcIdx]) return;
          client.services[svcIdx].driverPaidDate = dateInput.value;
          touchClient(client.id);
          saveClients();
          renderDriverPanel();
        });
        if (methodSel) methodSel.addEventListener("change", function () {
          var client = state.clients.find(function (c) { return c.id === clientId; });
          if (!client || !client.services[svcIdx]) return;
          client.services[svcIdx].driverPaymentMethod = methodSel.value;
          touchClient(client.id);
          saveClients();
        });
        if (amountInput) amountInput.addEventListener("change", function () {
          var client = state.clients.find(function (c) { return c.id === clientId; });
          if (!client || !client.services[svcIdx]) return;
          var service = client.services[svcIdx];
          var newVal = amountInput.value.trim();
          var origVal = Number.parseFloat(amountInput.getAttribute("data-orig-amount") || 0) || 0;
          // Si el valor coincide con el automático (o está vacío), se limpia el manual.
          var clearing = (newVal === "" || Math.abs((Number.parseFloat(newVal) || 0) - origVal) < 0.01);
          var assignIdx = Number.parseInt(amountInput.getAttribute("data-assign-idx"), 10);
          var splitDay = amountInput.getAttribute("data-split") === "1";
          if (splitDay && assignIdx >= 0 && Array.isArray(service.assignments) && service.assignments[assignIdx]) {
            // Día dividido entre choferes: el importe manual va SOLO a este chofer/subgrupo.
            service.assignments[assignIdx].amountOverride = clearing ? "" : newVal;
          } else {
            service.driverAmountOverride = clearing ? "" : newVal;
          }
          touchClient(client.id);
          saveClients();
          renderDriverPanel();
        });
      });
    }

    // Descarga la liquidación del mes del chofer como Excel.
    function downloadDriverLiquidation(driver, enriched, month, year) {
      ensureXLSXLib().then(function (XLSX) {
        var rows = enriched.map(function (t) {
          return {
            "Fecha": displayDate(t.date),
            "Cliente": t.clientName,
            "Personas": t.pax || "",
            "Servicio": tripServiceLabel(t),
            "Hotel": t.hotel || "",
            "Vehiculo": t.vehicle || "",
            "Valor": t.amount || 0,
            "Estado": t.paid ? "PAGADO" : "PENDIENTE",
            "Fecha pago": t.paymentDate ? displayDate(t.paymentDate) : "",
            "Medio pago": t.paymentMethod || ""
          };
        });
        var total = enriched.reduce(function (s, t) { return s + (t.amount || 0); }, 0);
        rows.push({ "Fecha": "", "Cliente": "TOTAL", "Valor": total });
        var ws = XLSX.utils.json_to_sheet(rows);
        var wb = XLSX.utils.book_new();
        var nombre = (driver.name + " " + (driver.lastName || "")).trim();
        XLSX.utils.book_append_sheet(wb, ws, "Liquidacion");
        var mm = String((month || 0) + 1).padStart(2, "0");
        XLSX.writeFile(wb, "liquidacion_" + pdfFileSafe(nombre) + "_" + year + "-" + mm + ".xlsx");
      }).catch(function () {
        alert("No se pudo generar el Excel. Revisá tu conexión e intentá de nuevo.");
      });
    }

    function liqPaymentMethodSelect(current) {
      const methods = ["TRANSFERENCIA", "EFECTIVO", "CHEQUE", "DEPOSITO", "PENDIENTE"];
      const opts = methods.map((m) => '<option value="' + m + '"' + (m === current ? " selected" : "") + '>' + m + '</option>').join("");
      return '<select class="liq-paymethod">' + opts + '</select>';
    }

    function renderDriverProfileView(driver) {
      // C5 (07/08): "Mis datos" con edición. En modo edición muestra un formulario;
      // el chofer puede actualizar SU contacto y datos bancarios (nombre/DNI/tipo los
      // maneja administración). Guarda SOLO su ficha con saveMyDriverRecord.
      if (state.driverProfileEditing) { renderDriverProfileEdit(driver); return; }
      const content = document.getElementById("driverProfileContent");
      const fields = (label, value) => value ? '<div class="driver-profile-field"><div class="label">' + label + '</div><div class="value">' + escapeHtml(value) + '</div></div>' : '';
      const vehiclesHtml = (driver.vehicles || []).map((v) => {
        const label = v.label || (v.brand + " " + v.model + " " + v.plate).trim();
        const isDefault = v.id === driver.defaultVehicleId;
        return '<span class="driver-profile-vehicle' + (isDefault ? ' is-default' : '') + '">' + escapeHtml(label) + '</span>';
      }).join("") || '<span style="font-size:12px;color:#6b7c92;font-style:italic;">Sin autos asignados</span>';

      content.innerHTML =
        '<div class="driver-profile-card">' +
        '  <h3>Datos personales</h3>' +
        '  <div class="driver-profile-grid">' +
        fields("Nombre completo", (driver.name || "") + (driver.lastName ? " " + driver.lastName : "")) +
        fields("DNI", driver.dni) +
        fields("CUIT", driver.cuit) +
        fields("Tipo de chofer", driver.type === "EMPLEADO SINEUS" ? "Empleado Sineus" : "Tercerizado") +
        fields("Email", driver.email) +
        fields("Telefono", driver.phone) +
        fields("Direccion", driver.address) +
        fields("Fecha de ingreso", driver.joinDate ? displayDate(driver.joinDate) : "") +
        fields("Telefono de emergencia", driver.emergencyPhone) +
        fields("Contacto de emergencia", driver.emergencyContactName) +
        '  </div>' +
        '</div>' +
        '<div class="driver-profile-card">' +
        '  <h3>Datos bancarios</h3>' +
        '  <div class="driver-profile-grid">' +
        fields("Banco", driver.bank) +
        fields("Titular", driver.accountHolder) +
        fields("Cuenta", driver.accountNumber) +
        fields("CBU", driver.cbu) +
        fields("Alias", driver.alias) +
        '  </div>' +
        '</div>' +
        '<div class="driver-profile-card">' +
        '  <h3>Autos asignados</h3>' +
        '  <div class="driver-profile-vehicles">' + vehiclesHtml + '</div>' +
        '</div>' +
        '<div style="text-align:center;margin-top:16px;"><button type="button" class="btn btn-main" id="driverEditProfileBtn">✏️ Editar mis datos</button></div>';

      const editBtn = document.getElementById("driverEditProfileBtn");
      if (editBtn) editBtn.addEventListener("click", () => { state.driverProfileEditing = true; renderDriverPanel(); });
    }

    function renderDriverProfileEdit(driver) {
      const content = document.getElementById("driverProfileContent");
      const inp = (id, label, value, type) =>
        '<label class="driver-edit-field"><span>' + label + '</span>' +
        '<input type="' + (type || "text") + '" id="' + id + '" value="' + escapeHtml(value || "") + '"></label>';

      content.innerHTML =
        '<div class="driver-profile-card">' +
        '  <h3>Editar mis datos</h3>' +
        '  <p class="driver-edit-note">Nombre, DNI y tipo de chofer los administra la oficina. Vos podés actualizar tu contacto y tus datos bancarios.</p>' +
        '  <div class="driver-profile-grid">' +
        '    <div class="driver-profile-field"><div class="label">Nombre completo</div><div class="value">' + escapeHtml((driver.name || "") + (driver.lastName ? " " + driver.lastName : "")) + '</div></div>' +
        (driver.dni ? '<div class="driver-profile-field"><div class="label">DNI</div><div class="value">' + escapeHtml(driver.dni) + '</div></div>' : '') +
        '  </div>' +
        '  <div class="driver-edit-grid">' +
        inp("edit_phone", "Teléfono", driver.phone, "tel") +
        inp("edit_email", "Email", driver.email, "email") +
        inp("edit_address", "Dirección", driver.address) +
        inp("edit_emergencyPhone", "Teléfono de emergencia", driver.emergencyPhone, "tel") +
        inp("edit_emergencyContactName", "Contacto de emergencia", driver.emergencyContactName) +
        '  </div>' +
        '</div>' +
        '<div class="driver-profile-card">' +
        '  <h3>Datos bancarios</h3>' +
        '  <div class="driver-edit-grid">' +
        inp("edit_bank", "Banco", driver.bank) +
        inp("edit_accountHolder", "Titular", driver.accountHolder) +
        inp("edit_accountNumber", "Nº de cuenta", driver.accountNumber) +
        inp("edit_cbu", "CBU", driver.cbu) +
        inp("edit_alias", "Alias", driver.alias) +
        '  </div>' +
        '</div>' +
        '<div class="driver-edit-actions">' +
        '  <button type="button" class="btn btn-light" id="driverCancelEditBtn">Cancelar</button>' +
        '  <button type="button" class="btn btn-main" id="driverSaveProfileBtn">Guardar cambios</button>' +
        '  <span id="driverProfileSaveStatus" class="driver-edit-status"></span>' +
        '</div>';

      const cancelBtn = document.getElementById("driverCancelEditBtn");
      if (cancelBtn) cancelBtn.addEventListener("click", () => { state.driverProfileEditing = false; renderDriverPanel(); });

      const saveBtn = document.getElementById("driverSaveProfileBtn");
      if (saveBtn) saveBtn.addEventListener("click", async () => {
        const val = (id) => { const el = document.getElementById(id); return el ? el.value.trim() : ""; };
        driver.phone = val("edit_phone");
        driver.email = val("edit_email");
        driver.address = val("edit_address");
        driver.emergencyPhone = val("edit_emergencyPhone");
        driver.emergencyContactName = val("edit_emergencyContactName");
        driver.bank = val("edit_bank");
        driver.accountHolder = val("edit_accountHolder");
        driver.accountNumber = val("edit_accountNumber");
        driver.cbu = val("edit_cbu");
        driver.alias = val("edit_alias");
        driver.updatedAt = nowStamp();
        const idx = state.drivers.findIndex((d) => d.id === driver.id);
        if (idx >= 0) state.drivers[idx] = normalizeDriver(driver);
        try { appStorage.setItem(DRIVERS_KEY, JSON.stringify(state.drivers)); } catch (e) {}
        const status = document.getElementById("driverProfileSaveStatus");
        if (status) { status.textContent = "Guardando…"; status.style.color = "#6b7c92"; }
        const err = await saveMyDriverRecord(driver.id);
        if (err) {
          // NO se guardó en la nube: mensaje AMABLE para el chofer (el error técnico queda en
          // consola y en los logs de Supabase, para diagnóstico). No cerramos el formulario.
          console.warn("[Mis datos] guardado rechazado:", err);
          if (status) { status.textContent = "No se pudieron guardar los cambios. Reintentá o avisá a la oficina."; status.style.color = "#B91C1C"; }
          return;
        }
        if (status) { status.textContent = "Guardado ✓"; status.style.color = "#16A34A"; }
        setTimeout(() => { state.driverProfileEditing = false; renderDriverPanel(); }, 800);
      });
    }

    function renderDriverFilter() {
      const current = els.driverFilter.value;
      const options = driverOptions(current);
      fillSelect(els.driverFilter, options, "Todos los choferes");
      els.driverFilter.value = options.some((option) => sameText(option, current)) ? current : "";
    }

    function saveFleet() {
      state.fleetVehicles = (state.fleetVehicles || []).map(normalizeFleetVehicle);
      appStorage.setItem(FLEET_KEY, JSON.stringify(state.fleetVehicles));
      queueRemoteSave();
      renderAll();
    }

    function renderFleet() {
      const body = document.getElementById("fleetBody");
      if (!body) return;
      const vehicles = state.fleetVehicles || [];
      const countLabel = document.getElementById("fleetCountLabel");
      if (countLabel) countLabel.textContent = vehicles.length + " veh\u00edculo" + (vehicles.length === 1 ? "" : "s");
      body.innerHTML = "";
      if (!vehicles.length) {
        appendEmpty(body, 5, "Sin veh\u00edculos cargados");
        return;
      }
      vehicles.forEach((v) => {
        const tr = document.createElement("tr");
        tr.append(tableCell("td", v.marca || "-"));
        tr.append(tableCell("td", v.modelo || "-"));
        tr.append(tableCell("td", v.patente || "-"));
        tr.append(tableCell("td", v.color || "-"));
        const actions = document.createElement("td");
        actions.append(actionButton("Editar", "edit-fleet", v.id));
        actions.append(dangerButton("Eliminar", "delete-fleet", v.id));
        tr.append(actions);
        body.append(tr);
      });
    }

    function clearFleetForm() {
      ["fleetMarcaInput", "fleetModeloInput", "fleetPatenteInput", "fleetColorInput"].forEach((id) => { const el = document.getElementById(id); if (el) el.value = ""; });
      state.editingFleetId = "";
      const btn = document.getElementById("saveFleetButton");
      if (btn) btn.textContent = "Guardar vehiculo";
    }

    function saveFleetVehicle() {
      const get = (id) => { const el = document.getElementById(id); return el ? el.value : ""; };
      const data = { marca: get("fleetMarcaInput"), modelo: get("fleetModeloInput"), patente: get("fleetPatenteInput"), color: get("fleetColorInput") };
      if (!String(data.marca).trim() && !String(data.modelo).trim() && !String(data.patente).trim()) {
        alert("Carga al menos marca, modelo o patente.");
        return;
      }
      if (state.editingFleetId) {
        const v = (state.fleetVehicles || []).find((x) => x.id === state.editingFleetId);
        if (v) {
          const n = normalizeFleetVehicle(Object.assign({ id: v.id }, data));
          Object.assign(v, n);
          trackUserActivity("Edito vehiculo Sineus: " + n.marca + " " + n.modelo + " (" + n.patente + ")");
        }
      } else {
        const n = normalizeFleetVehicle(data);
        state.fleetVehicles = (state.fleetVehicles || []).concat([n]);
        sessionCreatedFleetIds.add(n.id);
        trackUserActivity("Agrego vehiculo Sineus: " + n.marca + " " + n.modelo + " (" + n.patente + ")");
      }
      clearFleetForm();
      saveFleet();
    }

    function editFleetVehicle(id) {
      const v = (state.fleetVehicles || []).find((x) => x.id === id);
      if (!v) return;
      state.editingFleetId = id;
      const set = (fid, val) => { const el = document.getElementById(fid); if (el) el.value = val || ""; };
      set("fleetMarcaInput", v.marca);
      set("fleetModeloInput", v.modelo);
      set("fleetPatenteInput", v.patente);
      set("fleetColorInput", v.color);
      const btn = document.getElementById("saveFleetButton");
      if (btn) btn.textContent = "Guardar cambios";
    }

    function deleteFleetVehicle(id) {
      const v = (state.fleetVehicles || []).find((x) => x.id === id);
      if (!v) return;
      if (!confirm("Eliminar el vehiculo " + (v.marca + " " + v.modelo).trim() + " (" + v.patente + ")?")) return;
      state.fleetVehicles = (state.fleetVehicles || []).filter((x) => x.id !== id);
      state.deletedFleetIds = [...(state.deletedFleetIds || []), id].slice(-1000);
      trackUserActivity("Elimino vehiculo Sineus: " + v.marca + " " + v.modelo + " (" + v.patente + ")");
      if (state.editingFleetId === id) clearFleetForm();
      saveFleet();
    }

    function renderDrivers() {
      renderFleet();
      const serviceRows = buildDriverServiceRows().filter((row) => isActivePeriodDate(row.date));
      els.driversBody.innerHTML = "";

      // Filters
      const query = latinKey(els.driversSearch ? els.driversSearch.value : "");
      const typeFilter = els.driversTypeFilter ? els.driversTypeFilter.value : "";
      const statusFilter = els.driversStatusFilter ? els.driversStatusFilter.value : "";

      let visible = (state.drivers || []).slice();
      if (typeFilter) visible = visible.filter((d) => d.type === typeFilter);
      if (statusFilter === "active") visible = visible.filter((d) => d.active !== false);
      if (statusFilter === "inactive") visible = visible.filter((d) => d.active === false);
      if (query) {
        visible = visible.filter((d) => {
          const text = latinKey([
            d.name, d.lastName, d.dni, d.cuit, d.phone, d.email,
            (d.vehicles || []).map((v) => v.label + " " + v.plate + " " + v.brand + " " + v.model).join(" "),
            (d.subDrivers || []).map((s) => s.name + " " + s.dni).join(" ")
          ].join(" "));
          return text.includes(query);
        });
      }

      visible.sort((a, b) => String(a.name || "").localeCompare(b.name || ""));

      if (!visible.length) {
        els.driversBody.innerHTML = '<div class="drivers-empty">' + ((state.drivers || []).length === 0 ? "Sin choferes cargados. Click en \"+ Nuevo chofer\" para agregar." : "Ningun chofer coincide con los filtros.") + '</div>';
        return;
      }

      visible.forEach((driver) => {
        const rows = serviceRows.filter((row) => sameText(row.driver, driver.name));
        const total = rows.reduce((sum, row) => sum + row.amount, 0);
        els.driversBody.append(renderDriverCard(driver, rows.length, total));
      });
    }

    function renderDriverCard(driver, servicesCount, totalLiquidation) {
      const card = document.createElement("div");
      card.className = "driver-card";
      if (driver.active === false) card.classList.add("is-inactive");
      const isEmployee = driver.type === "EMPLEADO SINEUS";
      const initials = (driver.name.charAt(0) + (driver.lastName ? driver.lastName.charAt(0) : (driver.name.charAt(1) || ""))).toUpperCase();

      // Vehicles chips
      const vehicleChips = (driver.vehicles || []).map((v) => {
        const isDefault = v.id === driver.defaultVehicleId;
        return '<span class="driver-vehicle-chip' + (isDefault ? ' is-default' : '') + '">' + escapeHtml(v.label || (v.model + " " + v.plate)) + '</span>';
      }).join("") || '<span style="font-size:11px;color:#6b7c92;font-style:italic;">Sin autos asignados</span>';

      // Sub-drivers list
      const subDriversList = (driver.subDrivers || []).length > 0
        ? '<div class="driver-card-vehicles"><div class="label">Sub-choferes (' + driver.subDrivers.length + ')</div>' +
          driver.subDrivers.map((s) => '<span class="driver-vehicle-chip">' + escapeHtml(s.name) + '</span>').join("") + '</div>'
        : '';

      card.innerHTML = [
        '<div class="driver-card-head">',
        '  <div class="driver-avatar ' + (isEmployee ? '' : 'tercerizado') + '">' + escapeHtml(initials) + '</div>',
        '  <div class="driver-card-name">',
        '    <strong>' + escapeHtml(driver.name + (driver.lastName ? " " + driver.lastName : "")) + '</strong>',
        '    <div class="driver-card-badges">',
        '      <span class="driver-badge ' + (isEmployee ? 'empleado' : 'tercero') + '">' + (isEmployee ? "EMPLEADO" : "TERCERO") + '</span>',
        '      <span class="driver-badge ' + (driver.active !== false ? 'active' : 'inactive') + '">' + (driver.active !== false ? "ACTIVO" : "INACTIVO") + '</span>',
        '    </div>',
        '  </div>',
        '</div>',
        '<div class="driver-card-body">',
        driver.dni ? '<div class="row"><span class="label">DNI</span><span>' + escapeHtml(driver.dni) + '</span></div>' : '',
        driver.phone ? '<div class="row"><span class="label">Telefono</span><span>' + escapeHtml(driver.phone) + '</span></div>' : '',
        '<div class="row"><span class="label">Servicios en el periodo</span><span><strong>' + servicesCount + '</strong> · ' + escapeHtml(formatMoney(totalLiquidation)) + '</span></div>',
        '</div>',
        '<div class="driver-card-vehicles">',
        '  <div class="label">Autos asignados (' + (driver.vehicles || []).length + ')</div>',
        vehicleChips,
        '</div>',
        subDriversList,
        renderDriverUserInfo(driver),
        '<div class="driver-card-actions">',
        '  <button class="btn btn-light" data-action="edit-driver" data-id="' + driver.id + '">Editar</button>',
        '  <button class="btn btn-light" data-action="generate-driver-user" data-id="' + driver.id + '">' + (driverHasUser(driver) ? "Resetear clave" : "Generar usuario") + '</button>',
        '  <button class="btn btn-light" data-action="toggle-driver-active" data-id="' + driver.id + '">' + (driver.active !== false ? "Desactivar" : "Activar") + '</button>',
        '  <button class="btn btn-danger" data-action="delete-driver" data-id="' + driver.id + '">Eliminar</button>',
        '</div>'
      ].join("");

      return card;
    }

    // ========== Modal de Chofer ==========
    let driverModalDraft = null; // borrador en edicion

    function openDriverModal(id) {
      const driver = id ? state.drivers.find((d) => d.id === id) : null;
      driverModalDraft = driver ? JSON.parse(JSON.stringify(driver)) : normalizeDriver({});
      state.activeDriverId = driverModalDraft.id;

      els.driverModalTitle.textContent = driver ? "Editar chofer" : "Nuevo chofer";
      els.driverFormName.value = driverModalDraft.name || "";
      els.driverFormLastName.value = driverModalDraft.lastName || "";
      els.driverFormDni.value = driverModalDraft.dni || "";
      els.driverFormCuit.value = driverModalDraft.cuit || "";
      els.driverFormType.value = driverModalDraft.type || "TERCERIZADO";
      els.driverFormStatus.value = driverModalDraft.active === false ? "inactive" : "active";
      els.driverFormEmail.value = driverModalDraft.email || "";
      els.driverFormPhone.value = driverModalDraft.phone || "";
      els.driverFormAddress.value = driverModalDraft.address || "";
      els.driverFormJoinDate.value = driverModalDraft.joinDate || "";
      els.driverFormTelegram.value = driverModalDraft.telegramId || "";
      els.driverFormEmergencyPhone.value = driverModalDraft.emergencyPhone || "";
      els.driverFormEmergencyContact.value = driverModalDraft.emergencyContactName || "";
      els.driverFormBank.value = driverModalDraft.bank || "";
      els.driverFormAccountHolder.value = driverModalDraft.accountHolder || "";
      els.driverFormAccountNumber.value = driverModalDraft.accountNumber || "";
      els.driverFormCbu.value = driverModalDraft.cbu || "";
      els.driverFormAlias.value = driverModalDraft.alias || "";
      els.driverFormNotes.value = driverModalDraft.notes || "";

      renderDriverVehiclesList();
      renderDriverSubDriversList();
      els.driverModal.classList.remove("hidden");
    }

    function closeDriverModal() {
      state.activeDriverId = "";
      driverModalDraft = null;
      els.driverModal.classList.add("hidden");
    }

    function renderDriverVehiclesList() {
      if (!driverModalDraft) return;
      const list = els.driverVehiclesList;
      list.innerHTML = "";
      (driverModalDraft.vehicles || []).forEach((vehicle, index) => {
        const row = document.createElement("div");
        row.className = "driver-item";
        const isDefault = vehicle.id === driverModalDraft.defaultVehicleId;
        row.innerHTML = '<input type="radio" name="defaultVehicle" ' + (isDefault ? "checked" : "") + ' data-vehicle-default="' + vehicle.id + '" title="Marcar como principal">' +
          '<input data-vehicle-field="label" data-index="' + index + '" placeholder="Etiqueta (ej: HIACE X12)" value="' + escapeHtml(vehicle.label || "") + '">' +
          '<input data-vehicle-field="model" data-index="' + index + '" placeholder="Marca y modelo" value="' + escapeHtml(vehicle.model || "") + '">' +
          '<input data-vehicle-field="plate" data-index="' + index + '" placeholder="Patente" value="' + escapeHtml(vehicle.plate || "") + '">' +
          '<input data-vehicle-field="capacity" data-index="' + index + '" placeholder="Pax" style="width:60px" value="' + escapeHtml(String(vehicle.capacity || "")) + '">' +
          '<button class="driver-item-remove" data-vehicle-remove="' + index + '" title="Eliminar">X</button>';
        list.append(row);
      });
    }

    function renderDriverSubDriversList() {
      if (!driverModalDraft) return;
      const list = els.driverSubDriversList;
      list.innerHTML = "";
      (driverModalDraft.subDrivers || []).forEach((sub, index) => {
        const row = document.createElement("div");
        row.className = "driver-item";
        row.style.gridTemplateColumns = "2fr 1fr 1fr auto";
        row.innerHTML = '<input data-subdriver-field="name" data-index="' + index + '" placeholder="Nombre completo" value="' + escapeHtml(sub.name || "") + '">' +
          '<input data-subdriver-field="dni" data-index="' + index + '" placeholder="DNI" value="' + escapeHtml(sub.dni || "") + '">' +
          '<input data-subdriver-field="phone" data-index="' + index + '" placeholder="Telefono" value="' + escapeHtml(sub.phone || "") + '">' +
          '<button class="driver-item-remove" data-subdriver-remove="' + index + '" title="Eliminar">X</button>';
        list.append(row);
      });
    }

    function addDriverVehicle() {
      if (!driverModalDraft) return;
      driverModalDraft.vehicles = driverModalDraft.vehicles || [];
      const newVehicle = normalizeVehicle({ label: "" });
      driverModalDraft.vehicles.push(newVehicle);
      // Si es el primer auto, marcarlo como principal por defecto
      if (driverModalDraft.vehicles.length === 1) {
        driverModalDraft.defaultVehicleId = newVehicle.id;
      }
      renderDriverVehiclesList();
    }

    function addDriverSubDriver() {
      if (!driverModalDraft) return;
      driverModalDraft.subDrivers = driverModalDraft.subDrivers || [];
      driverModalDraft.subDrivers.push(normalizeSubDriver({ name: "" }));
      renderDriverSubDriversList();
    }

    function syncDriverDraftFromInputs() {
      if (!driverModalDraft) return;
      // Auto-recolectar todos los inputs de autos
      els.driverVehiclesList.querySelectorAll("[data-vehicle-field]").forEach((input) => {
        const idx = Number(input.dataset.index);
        const field = input.dataset.vehicleField;
        if (driverModalDraft.vehicles[idx]) driverModalDraft.vehicles[idx][field] = input.value;
      });
      // Auto-default
      const defaultRadio = els.driverVehiclesList.querySelector("[data-vehicle-default]:checked");
      if (defaultRadio) driverModalDraft.defaultVehicleId = defaultRadio.dataset.vehicleDefault;
      // Sub-choferes
      els.driverSubDriversList.querySelectorAll("[data-subdriver-field]").forEach((input) => {
        const idx = Number(input.dataset.index);
        const field = input.dataset.subdriverField;
        if (driverModalDraft.subDrivers[idx]) driverModalDraft.subDrivers[idx][field] = input.value;
      });
    }

    function saveDriverFromForm() {
      if (!driverModalDraft) return;
      const name = els.driverFormName.value.trim();
      if (!name) {
        alert("Carga al menos el nombre del chofer.");
        return;
      }
      syncDriverDraftFromInputs();

      const payload = normalizeDriver({
        id: driverModalDraft.id,
        name: name,
        lastName: els.driverFormLastName.value,
        dni: els.driverFormDni.value,
        cuit: els.driverFormCuit.value,
        type: els.driverFormType.value,
        active: els.driverFormStatus.value === "active",
        email: els.driverFormEmail.value,
        phone: els.driverFormPhone.value,
        address: els.driverFormAddress.value,
        joinDate: els.driverFormJoinDate.value,
        telegramId: els.driverFormTelegram.value,
        emergencyPhone: els.driverFormEmergencyPhone.value,
        emergencyContactName: els.driverFormEmergencyContact.value,
        bank: els.driverFormBank.value,
        accountHolder: els.driverFormAccountHolder.value,
        accountNumber: els.driverFormAccountNumber.value,
        cbu: els.driverFormCbu.value,
        alias: els.driverFormAlias.value,
        notes: els.driverFormNotes.value,
        vehicles: (driverModalDraft.vehicles || []).filter((v) => (v.label || v.model || v.plate || "").trim()),
        subDrivers: (driverModalDraft.subDrivers || []).filter((s) => (s.name || "").trim()),
        defaultVehicleId: driverModalDraft.defaultVehicleId
      });

      // Validar que el default sea un auto que existe
      if (payload.defaultVehicleId && !payload.vehicles.find((v) => v.id === payload.defaultVehicleId)) {
        payload.defaultVehicleId = payload.vehicles.length > 0 ? payload.vehicles[0].id : "";
      }
      // Sello de edición para el candado de choferes: esta ficha es la más nueva.
      payload.updatedAt = nowStamp();

      const index = state.drivers.findIndex((d) => d.id === payload.id);
      if (index >= 0) state.drivers[index] = payload;
      else { state.drivers.push(payload); sessionCreatedDriverIds.add(payload.id); }

      closeDriverModal();
      saveDrivers();
    }

    function toggleDriverActive(id) {
      const driver = state.drivers.find((d) => d.id === id);
      if (!driver) return;
      driver.active = driver.active === false;
      saveDrivers();
    }

    // ========== Sistema de usuarios para choferes ==========
    function driverHasUser(driver) {
      if (!driver) return false;
      return Object.keys(state.profiles || {}).some((user) => {
        const p = state.profiles[user];
        return p && p.role === "driver" && p.driverId === driver.id;
      });
    }

    function driverUserId(driver) {
      if (!driver) return "";
      return Object.keys(state.profiles || {}).find((user) => {
        const p = state.profiles[user];
        return p && p.role === "driver" && p.driverId === driver.id;
      }) || "";
    }

    function renderDriverUserInfo(driver) {
      const userId = driverUserId(driver);
      if (!userId) {
        return '<div class="driver-card-vehicles"><div class="label" style="color:#A32D2D">Sin usuario generado</div></div>';
      }
      return '<div class="driver-card-vehicles"><div class="label">Usuario del chofer</div>' +
        '<span class="driver-vehicle-chip" style="background:#185FA5;color:#fff;border-color:#185FA5;">' + escapeHtml(userId) + '</span></div>';
    }

    // Genera o resetea el usuario de un chofer.
    // Usuario propuesto: st.<primer_nombre_en_minuscula>
    // Si ya existe ese usuario y NO es del mismo chofer, se le agrega .id corto.
    function generateDriverUserForId(driverId) {
      if (!requireAccess("choferes")) return;
      const driver = state.drivers.find((d) => d.id === driverId);
      if (!driver || !driver.name) {
        alert("El chofer no tiene nombre. Edita la ficha primero.");
        return;
      }
      const existing = driverUserId(driver);
      if (existing) {
        // Reset: pedir nueva clave
        const newPwd = window.prompt("Nueva contrasena para " + existing + " (4+ caracteres):", "1234");
        if (!newPwd || newPwd.length < 4) return;
        state.authUsers[existing] = newPwd;
        saveAuthUsers();
        alert("Clave de " + existing + " actualizada a: " + newPwd);
        return;
      }

      // Crear nuevo usuario
      const firstNameSlug = String(driver.name).toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9]/g, "");
      let proposed = "st." + firstNameSlug;
      // Si choca con otro usuario, agregar sufijo corto
      if (state.authUsers && state.authUsers[proposed]) {
        const shortId = driver.id.slice(-3);
        proposed = "st." + firstNameSlug + "." + shortId;
      }

      const username = window.prompt("Usuario propuesto para " + driver.name + ":", proposed);
      if (!username) return;
      const cleanUser = username.trim().toLowerCase();
      if (state.authUsers && state.authUsers[cleanUser]) {
        alert("Ese usuario ya existe. Elegi otro.");
        return;
      }
      const password = window.prompt("Contrasena inicial (4+ caracteres):", "1234");
      if (!password || password.length < 4) return;

      state.authUsers = state.authUsers || {};
      state.authUsers[cleanUser] = password;
      sessionCreatedUserIds.add(cleanUser);
      state.profiles = state.profiles || {};
      state.profiles[cleanUser] = {
        name: driver.name,
        lastname: driver.lastName || "",
        phone: driver.phone || "",
        email: driver.email || "",
        photo: "",
        disabled: false,
        role: "driver",
        driverId: driver.id,
        createdAt: nowStamp()
      };
      saveAuthUsers();
      saveProfiles();
      alert("Usuario creado: " + cleanUser + "\nContrasena: " + password + "\n\nPodes compartir estos datos con el chofer.");
      renderDrivers();
    }

    // ========== Modal Nuevo Usuario (desde Administracion) ==========
    function openNewUserModal() {
      if (!requireAccess("administracion")) return;
      document.getElementById("newUserName").value = "";
      document.getElementById("newUserLastName").value = "";
      document.getElementById("newUserUsername").value = "";
      document.getElementById("newUserPassword").value = "1234";
      document.getElementById("newUserType").value = "";
      document.getElementById("newUserEmail").value = "";
      document.getElementById("newUserPhone").value = "";
      document.getElementById("newUserDriverPickerWrap").style.display = "none";
      // Llenar dropdown de choferes disponibles (sin usuario)
      const picker = document.getElementById("newUserDriverPicker");
      picker.innerHTML = '<option value="">-- Crear nueva ficha de chofer automaticamente --</option>';
      (state.drivers || []).forEach((d) => {
        if (driverHasUser(d)) return; // saltar los que ya tienen
        const opt = document.createElement("option");
        opt.value = d.id;
        opt.textContent = (d.name || "") + (d.lastName ? " " + d.lastName : "") + " (" + (d.type === "EMPLEADO SINEUS" ? "Empleado" : "Tercero") + ")";
        picker.append(opt);
      });
      document.getElementById("newUserModal").classList.remove("hidden");
    }

    function closeNewUserModal() {
      document.getElementById("newUserModal").classList.add("hidden");
    }

    function onNewUserTypeChange() {
      const type = document.getElementById("newUserType").value;
      const isDriverType = USER_TYPES[type] && USER_TYPES[type].isDriver;
      document.getElementById("newUserDriverPickerWrap").style.display = isDriverType ? "block" : "none";
      // Sugerir nombre de usuario
      const name = document.getElementById("newUserName").value.trim();
      if (name && !document.getElementById("newUserUsername").value) {
        const slug = name.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9]/g, "");
        if (slug) document.getElementById("newUserUsername").value = "st." + slug;
      }
    }

    function confirmNewUser() {
      if (!requireAccess("administracion")) return;
      const name = document.getElementById("newUserName").value.trim();
      const lastName = document.getElementById("newUserLastName").value.trim();
      const username = document.getElementById("newUserUsername").value.trim().toLowerCase();
      const password = document.getElementById("newUserPassword").value;
      const userType = document.getElementById("newUserType").value;
      const email = document.getElementById("newUserEmail").value.trim();
      const phone = document.getElementById("newUserPhone").value.trim();
      const driverPickerId = document.getElementById("newUserDriverPicker").value;

      if (!name) { alert("Carga el nombre."); return; }
      if (!username) { alert("Carga un usuario (login)."); return; }
      if (!password || password.length < 4) { alert("La contrasena debe tener al menos 4 caracteres."); return; }
      if (!userType || !USER_TYPES[userType]) { alert("Selecciona el tipo de usuario."); return; }
      if (state.authUsers && state.authUsers[username]) { alert("Ese usuario ya existe. Elegi otro."); return; }

      const isDriverType = USER_TYPES[userType].isDriver;
      let linkedDriverId = "";

      if (isDriverType) {
        if (driverPickerId) {
          linkedDriverId = driverPickerId;
        } else {
          // Crear ficha de chofer automatica con el tipo correspondiente
          const newDriver = normalizeDriver({
            name: name.toUpperCase(),
            lastName: lastName.toUpperCase(),
            type: USER_TYPES[userType].driverType,
            active: true,
            email: email,
            phone: phone,
            notes: "Ficha creada automaticamente al crear el usuario " + username + "."
          });
          state.drivers = state.drivers || [];
          state.drivers.push(newDriver);
          sessionCreatedDriverIds.add(newDriver.id);
          linkedDriverId = newDriver.id;
          try { appStorage.setItem(DRIVERS_KEY, JSON.stringify(state.drivers)); } catch (e) {}
        }
      }

      // Crear usuario y perfil
      state.authUsers = state.authUsers || {};
      state.authUsers[username] = password;
      sessionCreatedUserIds.add(username);
      state.profiles = state.profiles || {};
      state.profiles[username] = normalizeProfile(username, {
        name: name.toUpperCase(),
        lastname: lastName.toUpperCase(),
        phone: phone,
        email: email,
        userType: userType,
        driverId: linkedDriverId,
        createdAt: nowStamp()
      });

      saveAuthUsers();
      saveProfiles();
      try { renderDrivers(); } catch (e) {}
      try { renderAdministracion(); } catch (e) {}

      const driverInfo = linkedDriverId ? "\nFicha de chofer vinculada." : "";
      alert("Usuario creado: " + username + "\nContrasena: " + password + "\nTipo: " + USER_TYPES[userType].label + driverInfo);
      closeNewUserModal();
    }

    function deleteUser(username) {
      if (!requireAccess("administracion")) return;
      if (allowedUsers.includes(username)) {
        alert("No se puede eliminar un usuario predeterminado de Sineus.");
        return;
      }
      if (username === state.currentUser) {
        alert("No podes eliminar tu propio usuario activo. Cerra sesion primero.");
        return;
      }
      if (!window.confirm("Eliminar el usuario " + username + "? Esta accion no se puede deshacer.")) return;
      delete state.authUsers[username];
      delete state.profiles[username];
      saveAuthUsers();
      saveProfiles();
      renderAdministracion();
    }

    function resetUserPassword(username) {
      if (!requireAccess("administracion")) return;
      const newPwd = window.prompt("Nueva contrasena para " + username + " (4+ caracteres):", "1234");
      if (!newPwd || newPwd.length < 4) return;
      state.authUsers[username] = newPwd;
      saveAuthUsers();
      saveProfiles();
      alert("Clave de " + username + " actualizada a: " + newPwd);
    }

