    function renderDriverRates() {
      const labels = rateLabels();
      els.driverRatesBody.innerHTML = "";
      if (!labels.length) {
        appendEmpty(els.driverRatesBody, 3, "Sin servicios para configurar");
        return;
      }

      labels.forEach((label) => {
        const tr = document.createElement("tr");
        appendCells(tr, [
          label,
          rateInput(label, "employee"),
          rateInput(label, "thirdParty")
        ]);
        els.driverRatesBody.append(tr);
      });
    }

    function renderDriverServices() {
      const selectedDriver = els.driverFilter.value;
      const rows = buildDriverServiceRows().filter((row) => isActivePeriodDate(row.date) && (!selectedDriver || sameText(row.driver, selectedDriver)));
      const total = rows.reduce((sum, row) => sum + row.amount, 0);
      els.driverServiceTotal.textContent = String(rows.length);
      els.driverAmountTotal.textContent = formatMoney(total);
      els.driverServicesBody.innerHTML = "";

      if (!rows.length) {
        appendEmpty(els.driverServicesBody, 11, "Sin servicios asociados a choferes");
        return;
      }

      rows.forEach((row) => {
        const tr = document.createElement("tr");
        appendCells(tr, [
          displayDate(row.date),
          row.number,
          row.client,
          servicePill(row.displayType),
          row.pickup,
          row.driver,
          row.vehicle,
          formatMoney(row.amount),
          paymentDateInput(row),
          paymentPill(row.driverPaidDate ? "PAGADO" : "PENDIENTE"),
          receiptControl(row)
        ]);
        els.driverServicesBody.append(tr);
      });
    }

    function buildDriverServiceRows() {
      const rows = [];
      state.clients.forEach((client) => {
        client.services.forEach((service, serviceIndex) => {
          if (!service.driver) return;
          rows.push({
            clientId: client.id,
            serviceIndex: serviceIndex,
            date: service.date,
            number: client.number,
            client: fullName(client),
            displayType: displayServiceLabel(service),
            pickup: service.pickup,
            driver: service.driver,
            vehicle: service.vehicle,
            driverPaidDate: service.driverPaidDate,
            driverReceiptName: service.driverReceiptName,
            amount: serviceRate(service, service.driver)
          });
        });
      });
      return rows.sort((a, b) => (sortableDate(a.date) + a.pickup).localeCompare(sortableDate(b.date) + b.pickup));
    }

    function rateInput(label, field) {
      const input = document.createElement("input");
      input.type = "number";
      input.min = "0";
      input.step = "100";
      input.placeholder = "0";
      input.dataset.rateKey = label;
      input.dataset.rateField = field;
      input.value = rateForLabel(label)[field] || "";
      return input;
    }

    function paymentDateInput(row) {
      const input = document.createElement("input");
      input.type = "date";
      input.dataset.action = "update-driver-payment";
      input.dataset.clientId = row.clientId;
      input.dataset.serviceIndex = String(row.serviceIndex);
      input.dataset.field = "driverPaidDate";
      input.value = row.driverPaidDate || "";
      return input;
    }

    function receiptControl(row) {
      const wrap = document.createElement("div");
      wrap.className = "receipt-control";
      const input = document.createElement("input");
      input.type = "file";
      input.dataset.action = "update-driver-receipt";
      input.dataset.clientId = row.clientId;
      input.dataset.serviceIndex = String(row.serviceIndex);
      const note = document.createElement("span");
      note.className = "file-note";
      note.textContent = row.driverReceiptName || "Sin comprobante";
      wrap.append(input, note);
      return wrap;
    }

    function paymentPill(status) {
      const span = document.createElement("span");
      span.className = "pill " + (status === "PAGADO" ? "pill-green" : "pill-gray");
      span.textContent = status;
      return span;
    }

    function appendCells(tr, values) {
      values.forEach((value) => {
        const td = document.createElement("td");
        if (value instanceof Node) {
          td.append(value);
        } else {
          td.textContent = value === 0 || value ? value : "-";
        }
        tr.append(td);
      });
    }

    function appendEmpty(tbody, colspan, text) {
      const tr = document.createElement("tr");
      tr.className = "empty-row";
      const td = document.createElement("td");
      td.colSpan = colspan;
      td.textContent = text;
      tr.append(td);
      tbody.append(tr);
    }

    function actionButton(text, action, id) {
      const button = document.createElement("button");
      button.type = "button";
      button.className = "table-button";
      button.textContent = text;
      button.dataset.action = action;
      button.dataset.id = id;
      return button;
    }

    function itineraryIconButton(action, id, label) {
      const button = actionButton("", action, id);
      button.classList.add("itinerary-icon-button");
      button.title = label || "Abrir itinerario";
      button.setAttribute("aria-label", label || "Abrir itinerario");
      button.innerHTML = [
        "<svg viewBox=\"0 0 24 24\" fill=\"none\" aria-hidden=\"true\">",
        "<rect x=\"5\" y=\"3\" width=\"14\" height=\"18\" rx=\"2.5\" fill=\"none\" stroke=\"white\" stroke-width=\"2\"/>",
        "<path d=\"M8 8.2h8M8 13h2.2M8 17h2.2\" stroke=\"white\" stroke-width=\"2\" stroke-linecap=\"round\"/>",
        "<path d=\"M12.8 12.8l1.3 1.3 2.9-3\" stroke=\"white\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>",
        "<path d=\"M8.5 5.2l3.6-2.2 3.4 2.2\" stroke=\"white\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>",
        "</svg>"
      ].join("");
      return button;
    }

    function senaLinkCell(client) {
      const wrapper = document.createElement("div");
      wrapper.className = "sena-link-cell";
      const input = document.createElement("input");
      input.type = "text";
      input.placeholder = "Link seña";
      input.value = client.depositLink || "";
      input.dataset.noUppercase = "true";
      input.dataset.action = "update-deposit-link";
      input.dataset.clientId = client.id;
      wrapper.append(input);
      const href = linkHref(client.depositLink);
      if (href) {
        const link = document.createElement("a");
        link.href = href;
        link.target = "_blank";
        link.rel = "noopener";
        link.textContent = "ABRIR";
        wrapper.append(link);
      }
      return wrapper;
    }

    function linkHref(value) {
      const text = String(value || "").trim();
      if (!text) return "";
      if (/^(https?:\/\/|mailto:)/i.test(text)) return text;
      if (text.includes(".")) return "https://" + text;
      return "";
    }

    /* ===================== HISTORIAL DE PAGOS ===================== */

    // Solo estos usuarios pueden ver y cargar pagos.
    function canManagePayments() {
      return paymentHistoryUsers.includes(state.currentUser || "");
    }

    // Moneda principal de cada metodo de cobro.
    function paymentCurrencyOf(method) {
      if (method === "USD efectivo") return "USD";
      if (method === "R$ efectivo") return "BRL";
      if (method === "AR$ efectivo") return "ARS";
      if (method === "R$ PIX") return "BRL"; // el cliente paga en R$ (pero llega en USD)
      return "USD";
    }

    function formatPaymentAmount(currency, value) {
      const amount = Number.parseFloat(value || "0") || 0;
      const prefix = currency === "USD" ? "US$ " : currency === "USDT" ? "USDT " : currency === "BRL" ? "R$ " : "AR$ ";
      return prefix + amount.toLocaleString("es-AR", { maximumFractionDigits: 2 });
    }

    // Celda del Acta de Cierre: boton "$" que abre la ficha de pagos.
    function paymentsCell(client) {
      const wrapper = document.createElement("div");
      wrapper.className = "payments-cell";
      if (!canManagePayments()) {
        const dash = document.createElement("span");
        dash.className = "payments-cell-empty";
        dash.textContent = "-";
        wrapper.append(dash);
        return wrapper;
      }
      const count = (client.payments || []).length;
      const button = document.createElement("button");
      button.type = "button";
      button.className = "payments-icon-button" + (count ? " has-payments" : "");
      button.dataset.action = "open-payments";
      button.dataset.id = client.id;
      button.title = "Historial de pagos";
      button.setAttribute("aria-label", "Historial de pagos");
      button.textContent = "$";
      wrapper.append(button);
      if (count) {
        const badge = document.createElement("span");
        badge.className = "payments-count";
        badge.textContent = String(count);
        wrapper.append(badge);
      }
      return wrapper;
    }

    function openPaymentsModal(clientId) {
      if (!canManagePayments()) {
        alert("Tu usuario no tiene permiso para ver el historial de pagos.");
        return;
      }
      const client = state.clients.find((item) => item.id === clientId);
      if (!client) return;
      const modal = document.getElementById("paymentsModal");
      if (!modal) return;
      state.activePaymentsClientId = client.id;
      if (!Array.isArray(client.payments)) client.payments = [];

      const title = document.getElementById("paymentsTitle");
      if (title) title.textContent = "Historial de pagos - " + (client.number || "") + " " + fullName(client);

      // Reset del formulario
      const dateInput = document.getElementById("paymentDateInput");
      const methodSelect = document.getElementById("paymentMethodSelect");
      const pixTypeSelect = document.getElementById("paymentPixTypeSelect");
      const amountInput = document.getElementById("paymentAmountInput");
      const payerInput = document.getElementById("paymentPayerInput");
      const usdInput = document.getElementById("paymentUsdReceivedInput");
      const linkInput = document.getElementById("paymentLinkInput");
      const noteInput = document.getElementById("paymentNoteInput");
      if (dateInput) dateInput.value = inputDate(nowStamp());
      if (methodSelect) methodSelect.value = "USD efectivo";
      if (pixTypeSelect) pixTypeSelect.value = "KAMIPAY";
      if (amountInput) amountInput.value = "";
      if (payerInput) payerInput.value = "";
      if (usdInput) usdInput.value = "";
      if (linkInput) linkInput.value = "";
      if (noteInput) noteInput.value = "";
      onPaymentMethodChange();

      renderPaymentsModalBody();
      modal.classList.remove("hidden");
      if (amountInput) setTimeout(() => amountInput.focus(), 0);
    }

    function closePaymentsModal() {
      state.activePaymentsClientId = "";
      const modal = document.getElementById("paymentsModal");
      if (modal) modal.classList.add("hidden");
    }

    function activePaymentsClient() {
      return state.clients.find((item) => item.id === state.activePaymentsClientId) || null;
    }

    // Muestra/oculta los campos de PIX (tipo) y los de Kamipay (USDT recibido + link).
    function onPaymentMethodChange() {
      const wrap = document.getElementById("paymentsAddGrid");
      const methodSelect = document.getElementById("paymentMethodSelect");
      const pixTypeSelect = document.getElementById("paymentPixTypeSelect");
      if (!wrap || !methodSelect) return;
      const isPix = methodSelect.value === "R$ PIX";
      const isKamipay = isPix && pixTypeSelect && pixTypeSelect.value === "KAMIPAY";
      wrap.classList.toggle("is-pix", isPix);
      wrap.classList.toggle("is-kamipay", isKamipay);
    }

    function renderPaymentsModalBody() {
      const client = activePaymentsClient();
      const listHost = document.getElementById("paymentsListHost");
      const totalsHost = document.getElementById("paymentsTotalsHost");
      if (!client || !listHost || !totalsHost) return;
      const payments = (client.payments || []).slice().sort((a, b) => {
        const da = a.date || "";
        const db = b.date || "";
        if (da !== db) return da < db ? 1 : -1; // mas reciente primero
        return 0;
      });

      // ----- Listado -----
      if (!payments.length) {
        listHost.innerHTML = '<div class="payments-empty">Todavia no hay pagos cargados para este cliente.</div>';
      } else {
        const rows = payments.map((p) => {
          const isPix = p.method === "R$ PIX";
          const isKamipay = isPix && p.pixType !== "TRANSFERENCIA";
          const currency = paymentCurrencyOf(p.method);
          const isUsd = currency === "USD";
          let amountCell;
          let methodLabel = p.method;
          let pillClass = "";
          if (isPix && isKamipay) {
            methodLabel = "R$ PIX (Kamipay)";
            pillClass = "m-pix";
            amountCell =
              '<div class="payments-amount-main">' + formatPaymentAmount("BRL", p.amount) + "</div>" +
              '<div class="payments-amount-sub">Recibido: ' + (p.usdReceived ? formatPaymentAmount("USDT", p.usdReceived) : "-") + "</div>";
            const href = linkHref(p.link);
            if (href) {
              amountCell += '<a class="payments-row-link" href="' + escapeHtml(href) + '" target="_blank" rel="noopener">Ver comprobante</a>';
            }
          } else if (isPix) {
            methodLabel = "R$ PIX (Transferencia)";
            pillClass = "m-transfer";
            amountCell = '<div class="payments-amount-main">' + formatPaymentAmount("BRL", p.amount) + "</div>";
          } else {
            pillClass = isUsd ? "m-usd" : "";
            amountCell = '<div class="payments-amount-main">' + formatPaymentAmount(currency, p.amount) + "</div>";
          }
          const meta = p.registeredBy
            ? '<div class="payments-meta">Cargado por ' + escapeHtml(displayUserName(p.registeredBy)) + (p.registeredAt ? " - " + escapeHtml(p.registeredAt) : "") + "</div>"
            : "";
          return "<tr>" +
            "<td>" + escapeHtml(displayDate(p.date) || "-") + "</td>" +
            "<td>" + (p.payer ? escapeHtml(p.payer) : "-") + "</td>" +
            '<td><span class="payments-method-pill ' + pillClass + '">' + escapeHtml(methodLabel) + "</span></td>" +
            "<td>" + amountCell + "</td>" +
            "<td>" + (p.note ? escapeHtml(p.note) : "") + meta + "</td>" +
            '<td><button type="button" class="payments-del" data-action="delete-payment" data-id="' + escapeHtml(p.id) + '">Eliminar</button></td>' +
            "</tr>";
        }).join("");
        listHost.innerHTML =
          '<table class="payments-table"><thead><tr>' +
          "<th>Fecha</th><th>Quien pago</th><th>Metodo</th><th>Monto</th><th>Nota</th><th></th>" +
          "</tr></thead><tbody>" + rows + "</tbody></table>";
      }

      // ----- Subtotales por moneda -----
      let usdEf = 0, usdt = 0, brlCash = 0, brlTransfer = 0, ars = 0, brlKamipaySent = 0;
      payments.forEach((p) => {
        const amount = Number.parseFloat(p.amount || "0") || 0;
        if (p.method === "USD efectivo") usdEf += amount;
        else if (p.method === "R$ efectivo") brlCash += amount;
        else if (p.method === "AR$ efectivo") ars += amount;
        else if (p.method === "R$ PIX") {
          if (p.pixType === "TRANSFERENCIA") {
            brlTransfer += amount; // se contabiliza como R$ transferencia
          } else {
            usdt += Number.parseFloat(p.usdReceived || "0") || 0; // Kamipay: llega en USDT
            brlKamipaySent += amount; // R$ que envio el cliente por Kamipay
          }
        }
      });

      const cards = [
        '<div class="payments-total-card"><div class="lbl">USD efectivo</div><div class="val">' + formatPaymentAmount("USD", usdEf) + "</div></div>",
        '<div class="payments-total-card"><div class="lbl">USDT (Kamipay)</div><div class="val">' + formatPaymentAmount("USDT", usdt) + "</div></div>",
        '<div class="payments-total-card"><div class="lbl">R$ efectivo</div><div class="val">' + formatPaymentAmount("BRL", brlCash) + "</div></div>",
        '<div class="payments-total-card"><div class="lbl">R$ transferencia</div><div class="val">' + formatPaymentAmount("BRL", brlTransfer) + "</div></div>",
        '<div class="payments-total-card"><div class="lbl">AR$ efectivo</div><div class="val">' + formatPaymentAmount("ARS", ars) + "</div></div>"
      ];
      let note = "";
      if (brlKamipaySent > 0) {
        note = '<div class="payments-total-note">Nota: por Kamipay el cliente envio ' + formatPaymentAmount("BRL", brlKamipaySent) + " en reales, que llegaron a la cuenta como USDT (ya sumados en la columna USDT).</div>";
      }
      totalsHost.innerHTML = '<div class="payments-totals">' + cards.join("") + note + "</div>";
    }

    function addPaymentFromForm() {
      if (!canManagePayments()) { alert("Tu usuario no tiene permiso para cargar pagos."); return; }
      const client = activePaymentsClient();
      if (!client) return;
      const methodSelect = document.getElementById("paymentMethodSelect");
      const pixTypeSelect = document.getElementById("paymentPixTypeSelect");
      const dateInput = document.getElementById("paymentDateInput");
      const amountInput = document.getElementById("paymentAmountInput");
      const payerInput = document.getElementById("paymentPayerInput");
      const usdInput = document.getElementById("paymentUsdReceivedInput");
      const linkInput = document.getElementById("paymentLinkInput");
      const noteInput = document.getElementById("paymentNoteInput");

      const method = methodSelect ? methodSelect.value : "USD efectivo";
      const amount = amountInput ? amountInput.value.trim() : "";
      if (!amount || !(Number.parseFloat(amount) > 0)) {
        alert("Carga el monto del pago (mayor a 0).");
        if (amountInput) amountInput.focus();
        return;
      }
      const isPix = method === "R$ PIX";
      const pixType = isPix && pixTypeSelect ? pixTypeSelect.value : "";
      const isKamipay = isPix && pixType !== "TRANSFERENCIA";
      if (isKamipay) {
        const usd = usdInput ? usdInput.value.trim() : "";
        if (!usd || !(Number.parseFloat(usd) > 0)) {
          alert("En un pago por PIX Kamipay, carga cuanto recibiste en USDT.");
          if (usdInput) usdInput.focus();
          return;
        }
      }

      const payment = normalizePayment({
        method: method,
        pixType: pixType,
        date: dateInput ? dateInput.value : "",
        amount: amount,
        payer: payerInput ? payerInput.value.trim() : "",
        usdReceived: isKamipay && usdInput ? usdInput.value.trim() : "",
        link: isKamipay && linkInput ? linkInput.value.trim() : "",
        note: noteInput ? noteInput.value.trim() : "",
        registeredBy: state.currentUser || "",
        registeredAt: nowStamp()
      });

      if (!Array.isArray(client.payments)) client.payments = [];
      client.payments.push(payment);
      touchClient(client.id);
      saveClients();
      // saveClients re-normaliza; volvemos a tomar el cliente para refrescar la ficha.
      renderPaymentsModalBody();

      // Limpiar el formulario para el proximo pago.
      if (amountInput) amountInput.value = "";
      if (payerInput) payerInput.value = "";
      if (usdInput) usdInput.value = "";
      if (linkInput) linkInput.value = "";
      if (noteInput) noteInput.value = "";
      if (amountInput) amountInput.focus();
    }

    function deletePayment(paymentId) {
      if (!canManagePayments()) { alert("Tu usuario no tiene permiso para eliminar pagos."); return; }
      const client = activePaymentsClient();
      if (!client || !Array.isArray(client.payments)) return;
      if (!confirm("Eliminar este pago del historial? Esta accion no se puede deshacer.")) return;
      client.payments = client.payments.filter((p) => p.id !== paymentId);
      // Dejar la MARCA DE BORRADO del pago: viaja a todas las compus por app_config
      // y evita que la proteccion de pagos ("nunca subir menos") lo vuelva a reponer.
      state.deletedPaymentIds = [...(state.deletedPaymentIds || []), paymentId].slice(-3000);
      touchClient(client.id);
      saveClients();
      renderPaymentsModalBody();
    }

