      if (t.indexOf("TRF IN") !== -1) return "svc-trf-in";
      if (t.indexOf("TRF OUT") !== -1) return "svc-trf-out";
      if (t.indexOf("ALTA MONTANA") !== -1) return "svc-alta";
      if (t.indexOf("VALLE DE UCO") !== -1) return "svc-uco";
      if (t.indexOf("LUJAN") !== -1 && t.indexOf("MAIPU") !== -1) return "svc-lujan-maipu";
      if (t.indexOf("LUJAN") !== -1) return "svc-lujan";
      if (t.indexOf("MAIPU") !== -1) return "svc-maipu";
      if (t.indexOf("SAN RAFAEL") !== -1) return "svc-rafael";
      if (t.indexOf("CITY TOUR") !== -1) return "svc-city";
      return "pill-blue";
