    function regionsForServiceStops(service) {
      const regions = [];
      (service.stops || []).forEach((stop) => {
        if (!stop.time && !stop.provider && !stop.experience && !stop.notes) return;
        const region = stop.region || regionForProvider(stop.provider) || "";
        if (region && !regions.includes(region)) regions.push(region);
      });
      return regions;
    }

    function displayServiceLabel(service) {
      const baseName = displayServiceName(service.type);
      if (!isTransferService(service.type)) return baseName;
      const regions = regionsForServiceStops(service).map(displayRegionShortName).filter(Boolean);
      return regions.length ? baseName + "/" + regions.join("+") : baseName;
    }

    // Version del itinerario que manda para OPERACIONES (Dia a Dia / Logistica):
    // 1) la version activa elegida, 2) si no, la ultima con el tick de "mostrar al
    // cliente", 3) recien si no hay ninguna, la ultima guardada.
    function operationalItineraryVersion(client) {
      // REGLA: el pasajero ve las versiones con TICK activo (showToClient).
      // Puede haber varias tickeadas (opciones para elegir). El activeItineraryId
      // solo se usa para elegir cual de las tickeadas es la principal.
      // Si ninguna esta tickeada, se muestra la ultima guardada (nunca ninguna).
      const versions = Array.isArray(client.itineraries) ? client.itineraries : [];
      const shown = versions.filter((v) => v.showToClient);
      if (shown.length) {
        // Si hay una activa Y ademas esta tickeada, gana esa.
        if (client.activeItineraryId) {
          const activeShown = shown.find((v) => v.id === client.activeItineraryId);
          if (activeShown) return activeShown;
        }
        // Si no, la mas nueva de las tickeadas.
        return shown[shown.length - 1];
      }
      // Nadie tickeo: la activa si existe, sino la ultima. El pasajero siempre ve algo.
      if (client.activeItineraryId) {
        const active = versions.find((v) => v.id === client.activeItineraryId);
        if (active) return active;
      }
      return latestItinerary(client);
    }

    // VERSIONES IGUALES MARCADAS DOS VECES (11/09, pedido de Emilia; ej. Jonatas 10556):
    // cuando dos compus guardan el mismo itinerario casi a la vez, cada una crea SU version
    // (identicas) y marca la suya; al unir las dos quedan marcadas. Regla: entre versiones con
    // el MISMO contenido (mismos pasos, mismos hoteles), solo queda marcada la mas nueva.
    // Versiones con contenido DISTINTO (opciones reales para el pasajero) no se tocan.
    function itineraryVersionSignature(v) {
      try {
        var steps = (v && Array.isArray(v.steps) ? v.steps : []).map(function (st) {
          return [st.date || "", st.kind || "", st.time || "", st.providerName || "", st.serviceName || "", st.transferType || "", (st.participants || []).length];
        }).sort(function (a, b) { return String(a).localeCompare(String(b)); });
        var hotels = (v && Array.isArray(v.hotels) ? v.hotels : []).map(function (h) { return [h.name || "", h.from || "", h.to || ""]; }).sort(function (a, b) { return String(a).localeCompare(String(b)); });
        return JSON.stringify([steps, hotels, (v && v.mode) || ""]);
      } catch (e) { return ""; }
    }
    function dedupeShownItineraryVersions(client) {
      var vs = client && Array.isArray(client.itineraries) ? client.itineraries : [];
      var shown = vs.filter(function (v) { return v && v.showToClient; });
      if (shown.length < 2) return false;
      var groups = {};
      shown.forEach(function (v) { var k = itineraryVersionSignature(v); (groups[k] = groups[k] || []).push(v); });
      var changed = false;
      Object.keys(groups).forEach(function (k) {
        var g = groups[k];
        if (g.length < 2) return;
        g.sort(function (a, b) { return (parseStampTs(b.createdAt) - parseStampTs(a.createdAt)) || ((b.metaAt || 0) - (a.metaAt || 0)); });
        g.slice(1).forEach(function (v) { v.showToClient = false; v.metaAt = Date.now(); changed = true; });
        if (client.activeItineraryId && g.slice(1).some(function (v) { return v.id === client.activeItineraryId; })) client.activeItineraryId = g[0].id;
      });
      if (changed) console.warn("[Versiones] Cliente " + (client.number || client.id) + ": habia versiones IGUALES marcadas dos veces; quedo marcada solo la mas nueva.");
      return changed;
    }

    // Version CERRADA (la que se pagó) = fuente de verdad para Logistica/Dia.
    // Prioridad: 1) la marcada con el boton "Cerrar" (closedItineraryId),
    // 2) si no, la unica con tick (showToClient), 3) si NO hay tick, la ultima
    // version generada. Si hay VARIOS ticks (no decidido), devuelve null: ambiguo,
    // no se proyecta nada (se respeta lo guardado).
    function closedItineraryVersionFor(client) {
      const versions = Array.isArray(client.itineraries) ? client.itineraries : [];
      if (!versions.length) return null;
      if (client.closedItineraryId) {
        const marked = versions.find((v) => v.id === client.closedItineraryId);
        if (marked) return marked;
      }
      const shown = versions.filter((v) => v.showToClient);
      if (shown.length === 1) return shown[0];
      if (shown.length === 0) return latestItinerary(client);
      // Varias marcadas pero con el MISMO contenido (duplicadas): usar la mas nueva.
      const sigs = new Set(shown.map(itineraryVersionSignature));
      if (sigs.size === 1) return shown.slice().sort((a, b) => parseStampTs(b.createdAt) - parseStampTs(a.createdAt))[0];
      return null; // varios ticks = no decidido
    }

    // RED DE SEGURIDAD: true si la proyeccion PERDERIA un chofer. Compara, por FECHA, el
    // conjunto de choferes asignados antes vs despues: si algun chofer que estaba asignado en
    // una fecha ya no aparece en esa fecha, NO se proyecta ese cliente (queda para revisar).
    function projectionWouldDropAssigned(oldServices, projected) {
      function driversByDate(list) {
        const m = {};
        (list || []).forEach(function (s) {
          const d = (s && s.driver ? String(s.driver).trim().toUpperCase() : "");
          if (!d || !s.date) return;
          (m[s.date] = m[s.date] || {})[d] = true;
        });
        return m;
      }
      const oldM = driversByDate(oldServices);
      const newM = driversByDate(projected);
      return Object.keys(oldM).some(function (date) {
        const after = newM[date] || {};
        return Object.keys(oldM[date]).some(function (drv) { return !after[drv]; });
      });
    }

    // Re-proyecta los servicios de un cliente cerrado desde su version CERRADA, conservando
    // el chofer y con la red de seguridad (nunca perder un viaje con chofer). Es EXPLICITA:
    // se llama al tocar "Cerrar" una version y al guardar el itinerario, NO en cada render
    // (asi no se repite el incidente ni se genera churn de sincronizacion). Devuelve:
    //   "ok"      -> se re-proyecto,
    //   "blocked" -> se abstuvo para no perder un viaje con chofer,
    //   "ambiguo" -> varios ticks / sin version, no se toco.
    function reprojectClosedServices(client) {
      if (!client || client.leadStatus !== "Cerrado") return "ambiguo";
      const version = closedItineraryVersionFor(client);
      if (!version) return "ambiguo";
      if (version.hotels && version.hotels.length) client.hotels = version.hotels.map(normalizeHotel);
      const projected = servicesFromItinerary(client, version, client.services || []);
      const old = client.services || [];
      // Set de stepIds que SÍ existen en la version cerrada. Sirve para detectar servicios
      // "fantasma": paseos que quedaron colgados de un paso de itinerario que se movió de día
      // o se quitó (su stepId ya no está en la version cerrada). (26/08)
      var _closedStepIds = {};
      var _closedStepDate = {};
      (version.steps || []).forEach(function (st) { if (st && st.id) { _closedStepIds[st.id] = 1; _closedStepDate[st.id] = sortableDate(st.date); } });
      function _isOrphanItineraryService(s) {
        var stops = (s && s.stops) || [];
        var withStep = stops.filter(function (st) { return st && st.itineraryStepId; });
        if (!withStep.length) return false; // sin stepId => no es derivado del itinerario (manual): no se toca
        // FANTASMA (10/09, Samara 11259): un paso puede seguir existiendo en la version cerrada pero
        // haber sido MOVIDO a otro dia (ej. Salentein del 11/09 paso al 14/09 como Alfa Crux, mismo
        // id). Si todos los pasos de este servicio ya no existen O estan en OTRA fecha => fantasma.
        var sd = sortableDate(s.date);
        return withStep.every(function (st) {
          var id = st.itineraryStepId;
          return !_closedStepIds[id] || (_closedStepDate[id] && sd && _closedStepDate[id] !== sd);
        });
      }
      // MERGE POR DÍA (granular): para cada fecha, se usa la versión cerrada SOLO si no se
      // pierde ningún chofer ya asignado ese día; si chocaría (ej. la versión pone un TRF ese
      // día pero en Logística hay un paseo con chofer), se conserva lo que estaba. Así se
      // corrigen los días que calzan (bodegas correctas) sin borrar ningún chofer. (10/08)
      function _byDate(list) { var m = {}; (list || []).forEach(function (s) { if (s && s.date) { (m[s.date] = m[s.date] || []).push(s); } }); return m; }
      // Junta TODOS los recursos asignados de un servicio: chofer principal, vehiculo, y ademas
      // los choferes/vehiculos de las asignaciones multiples. Antes solo miraba el chofer
      // principal, por eso al re-proyectar se perdian las asignaciones adicionales cargadas en
      // Logistica (bug: "se me borran los choferes"). (21/08)
      function _drvSet(list) {
        var s = {};
        (list || []).forEach(function (x) {
          if (!x) return;
          if (x.driver) s["D:" + String(x.driver).trim().toUpperCase()] = 1;
          if (x.vehicle) s["V:" + String(x.vehicle).trim().toUpperCase()] = 1;
          if (Array.isArray(x.assignments)) x.assignments.forEach(function (a) {
            if (!a) return;
            if (a.driver) s["D:" + String(a.driver).trim().toUpperCase()] = 1;
            if (a.vehicle) s["V:" + String(a.vehicle).trim().toUpperCase()] = 1;
          });
        });
        return s;
      }
      var _p = _byDate(projected), _o = _byDate(old);
      var _dates = {};
      Object.keys(_p).forEach(function (d) { _dates[d] = 1; });
      Object.keys(_o).forEach(function (d) { _dates[d] = 1; });
      var result = [];
      Object.keys(_dates).forEach(function (d) {
        var pd = _p[d], od = _o[d];
        if (!pd) {
          // Ese día NO existe en la versión cerrada. Antes se conservaba SIEMPRE lo que había
          // en Logística, y por eso un TRASLADO que se sacó del itinerario quedaba colgado
          // para siempre (ej. Juliana 10817: TRF IN 16/08 y TRF OUT 23/08 fantasmas). Ahora:
          //  - si tiene CHOFER asignado => se conserva (red de seguridad: nunca perder un viaje);
          //  - si es un TRASLADO SIN chofer => se descarta (se quitó del itinerario cerrado);
          //  - cualquier otra cosa sin chofer (paseos) => se conserva como antes (cambio acotado). (15/08)
          if (od) {
            var _keep = od.filter(function (s) {
              var _hasDrv = s && ((s.driver && String(s.driver).trim() !== "") ||
                (Array.isArray(s.assignments) && s.assignments.some(function (a) { return a && (a.driver || a.vehicle); })));
              if (_hasDrv) return true;                 // con chofer o asignacion: nunca se toca
              if (isTransferService(s.type)) return false; // traslado sin chofer quitado del itinerario => fuera
              if (_isOrphanItineraryService(s)) return false; // paseo FANTASMA: bodega movida de dia o quitada => fuera
              // (08/09) Servicio sin chofer FUERA de las fechas del viaje (quedo de una version
              // vieja, ej. Camila 10528 con un Valle de Uco del 02/09 cuando el viaje es 06-09/09) => fuera.
              var _cf = sortableDate(client.from), _ct = sortableDate(client.to), _sd = sortableDate(s.date);
              if (_cf && _ct && _sd && (_sd < _cf || _sd > _ct)) return false;
              return true;                              // paseo sin chofer cargado a mano: se conserva (por las dudas)
            });
            if (_keep.length) result = result.concat(_keep);
          }
          return;
        }
        if (!od) { result = result.concat(pd); return; }           // solo en la versión: usar versión
        var oDrv = _drvSet(od), pDrv = _drvSet(pd);
        var pierdeChofer = Object.keys(oDrv).some(function (k) { return !pDrv[k]; });
        result = result.concat(pierdeChofer ? od : pd);            // si perdería chofer, conservar
      });
      client.services = result;
      client.status = computeClientStatus(client);
      return "ok";
    }

    function operationalServicesForClient(client) {
      if (client.leadStatus !== "Cerrado") return client.services || [];
      // Si hay una version marcada como CERRADA (boton "Cerrar"), Logistica/Dia la SIGUEN
      // SIEMPRE: se re-proyecta desde esa version conservando choferes (idempotente + red de
      // seguridad). Asi la alineacion es firme aunque una sincronizacion traiga bodegas viejas.
      // Es acotado: solo clientes con closedItineraryId marcado (decision explicita del operador).
      if (client.closedItineraryId) {
        reprojectClosedServices(client);
        client.status = computeClientStatus(client);
        return client.services || [];
      }
      // Sin marca: NO se re-proyecta en cada render (eso pisaba datos = incidente 07/08).
      // Solo se generan si el cliente todavia NO tiene servicios.
      const version = operationalItineraryVersion(client);
      if (version) {
        if (version.hotels && version.hotels.length) client.hotels = version.hotels.map(normalizeHotel);
        if (!(Array.isArray(client.services) && client.services.length)) {
          client.services = servicesFromItinerary(client, version, client.services || []);
        } else {
          // Restaurar SOLO para mostrar los montos de traslado (y pax) que se derivan del
          // itinerario. Antes se recalculaban al regenerar en cada render; como ya NO
          // regeneramos, los recomponemos aca sin tocar bodegas ni choferes (08/08).
          overlayDerivedDisplayFields(client, version);
        }
        client.status = computeClientStatus(client);
      }
      return client.services || [];
    }

    // Recompone campos DERIVADOS solo-visuales (monto de traslado, cantidad de pax) sobre los
    // servicios existentes, tomandolos del itinerario. NO cambia fecha/tipo/bodegas/chofer, y
    // como normalizeService no guarda estos campos, no genera "churn" de sincronizacion.
    function overlayDerivedDisplayFields(client, version) {
      try {
        if (!client || !Array.isArray(client.services) || !client.services.length) return;
        version = version || closedItineraryVersionFor(client) || operationalItineraryVersion(client);
        if (!version) return;
        var projected = servicesFromItinerary(client, version, []); // [] = no consume los reales
        client.services.forEach(function (s) {
          var p = projected.find(function (x) { return x.date === s.date && x.type === s.type; })
               || projected.find(function (x) { return x.date === s.date && isTransferService(x.type) === isTransferService(s.type); })
               || projected.find(function (x) { return x.date === s.date; });
          if (!p) return;
          if (!s.transferAmountLabel && p.transferAmountLabel) s.transferAmountLabel = p.transferAmountLabel;
          if ((s.participantCount == null || s.participantCount === "") && p.participantCount != null) s.participantCount = p.participantCount;
        });
      } catch (e) { /* si algo falla, Logistica sigue mostrando lo que tenga */ }
    }

    function buildDiaRows() {
      const rows = [];
      state.clients.forEach((client) => {
        // El Dia a Dia solo muestra clientes CERRADOS (con reservas operativas).
        if (client.leadStatus !== "Cerrado") return;
        const services = operationalServicesForClient(client);
        if (client.leadStatus === "Cerrado" && !services.length) {
          rows.push({
            clientId: client.id,
            serviceIndex: -1,
            stopIndex: -1,
            date: client.from,
            number: client.number,
            time: "",
            provider: "PENDIENTE DE CARGA",
            client: fullName(client),
            pax: paxCount(client),
            experience: "CARGAR SERVICIOS",
            region: client.destination || "",
            status: "PENDIENTE",
            notes: "Cliente cerrado pendiente de carga de reservas",
            placeholder: true
          });
          return;
        }
        services.forEach((service, serviceIndex) => {
          service.stops.forEach((stop, stopIndex) => {
            if (!stop.provider && !stop.experience) return;
            rows.push({
              clientId: client.id,
              serviceIndex: serviceIndex,
              stopIndex: stopIndex,
              date: service.date,
              number: client.number,
              time: stop.time,
              provider: stop.provider,
              client: fullName(client),
              pax: ((stop.participantCount != null && stop.participantCount !== "" && Number(stop.participantCount) > 0) ? stop.participantCount : (service.participantCount != null && service.participantCount !== "" ? service.participantCount : paxCount(client))),
              experience: stop.experience,
              region: stop.region || regionForProvider(stop.provider) || service.region,
              status: stop.status,
              notes: stop.notes,
              reservationNumber: service.reservationNumber || ""
            });
          });
        });
      });
      return rows.sort((a, b) => (sortableDate(a.date) + a.time).localeCompare(sortableDate(b.date) + b.time));
    }

    // ============================ MODULO LIQUIDACION ============================
    // Estado de UI del modulo (vendedor y mes elegidos). Se resuelve en cada render.
    const liquidacionUi = { vendor: "gianfranco", ym: "" };

    // Estilos del modulo, inyectados una sola vez (para no tener que subir styles.css aparte).
    function ensureLiquidacionStyles() {
      if (document.getElementById("liq-styles")) return;
      const st = document.createElement("style");
      st.id = "liq-styles";
      st.textContent = [
        ".liq-header{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px;margin-bottom:16px;}",
        ".liq-title{font-size:20px;font-weight:800;letter-spacing:1px;color:#2f5d3a;margin:0;}",
        ".liq-controls{display:flex;gap:12px;flex-wrap:wrap;}",
        ".liq-control{display:flex;flex-direction:column;font-size:11px;font-weight:700;color:#5a6b7a;gap:4px;text-transform:uppercase;}",
        ".liq-control select{padding:8px 10px;border:1px solid #cdd6df;border-radius:8px;font-size:14px;min-width:170px;background:#fff;}",
        ".liq-config{display:flex;gap:14px;flex-wrap:wrap;margin-bottom:16px;}",
        ".liq-config-item{display:flex;flex-direction:column;gap:5px;background:#f6f8f6;border:1px solid #e0e6e0;border-radius:10px;padding:10px 14px;font-size:12px;font-weight:700;color:#5a6b7a;text-transform:uppercase;}",
        ".liq-config-item input{padding:6px 8px;border:1px solid #cdd6df;border-radius:6px;font-size:15px;width:150px;}",
        ".liq-config-item b{font-size:16px;color:#22303c;text-transform:none;}",
        ".liq-summary{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:12px;margin-bottom:22px;}",
        ".liq-card{background:#fff;border:1px solid #e2e6ea;border-radius:12px;padding:14px 16px;display:flex;flex-direction:column;gap:6px;}",
        ".liq-card span{font-size:12px;color:#66727d;font-weight:600;}",
        ".liq-card strong{font-size:22px;color:#22303c;font-weight:800;}",
        ".liq-card-total{background:#2f5d3a;border-color:#2f5d3a;}",
        ".liq-card-total span{color:#cfe6d5;}",
        ".liq-card-total strong{color:#fff;}",
        ".liq-detail-head{font-size:14px;font-weight:800;color:#2f5d3a;margin:8px 0 10px;display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;}",
        ".liq-table{width:100%;}",
        ".liq-table th{background:#2f5d3a;color:#fff;position:sticky;top:0;}",
        ".liq-table td{font-size:13px;}",
        ".liq-empty{padding:24px;background:#f6f8f6;border:1px dashed #c3ccd5;border-radius:12px;color:#556;font-size:15px;line-height:1.5;}",
        ".liq-card-pagado{background:#eaf6ee;border-color:#bfe3cb;}",
        ".liq-card-pagado strong{color:#217a3f;}",
        ".liq-card-parcial{background:#fff7e6;border-color:#f0dca8;}",
        ".liq-card-parcial strong{color:#a8791b;}",
        ".liq-card-pend{background:#fdecec;border-color:#f2c4c4;}",
        ".liq-card-pend strong{color:#b3352f;}",
        ".liq-pay{margin:22px 0;background:#fff;border:1px solid #e2e6ea;border-radius:12px;padding:16px;}",
        ".liq-pay-head{display:flex;justify-content:space-between;align-items:center;font-size:14px;font-weight:800;color:#2f5d3a;margin-bottom:12px;flex-wrap:wrap;gap:8px;}",
        ".liq-badge{font-size:12px;font-weight:800;padding:4px 12px;border-radius:20px;letter-spacing:.5px;}",
        ".liq-badge-pagado{background:#217a3f;color:#fff;}",
        ".liq-badge-parcial{background:#e0a41b;color:#fff;}",
        ".liq-badge-pend{background:#c0413a;color:#fff;}",
        ".liq-pay-form{display:flex;gap:12px;flex-wrap:wrap;align-items:flex-end;margin-bottom:14px;padding-bottom:14px;border-bottom:1px solid #eef1f4;}",
        ".liq-pay-form input,.liq-pay-form select{padding:8px 10px;border:1px solid #cdd6df;border-radius:8px;font-size:14px;}",
        ".liq-control-wide{flex:1;min-width:200px;}",
        ".liq-control-wide input{width:100%;}",
        ".liq-pay-table{width:100%;}",
        ".liq-pay-table th{background:#eef2f5;color:#2f5d3a;}",
        ".liq-del-pay{padding:2px 10px;color:#b3352f;font-weight:800;}"
      ].join("");
      document.head.appendChild(st);
    }

    // Etiqueta de mes tipo "AGOSTO 2026" a partir de "YYYY-MM".
    function liquidacionMonthLabel(ym) {
      const parts = String(ym || "").split("-");
      if (parts.length < 2) return ym || "-";
      const m = Number(parts[1]);
      return (monthNames[m - 1] || parts[1]) + " " + parts[0];
    }

    // Servicios operativos (mismos renglones que Logistica) de un mes dado.
    // Regla Gianfranco: TODOS los servicios de la agencia ese mes (los cierre quien los cierre).
    // ¿El vendedor de este cliente es el que buscamos? Tolerante: el campo "seller" puede venir
    // como "st.karen", "karen" o "KAREN" segun cuando se cargo la ficha.
    function clientSellerIs(client, vendorKey) {
      if (!client) return false;
      var s = String(client.seller || "").trim().toUpperCase();
      if (!s) return false;
      if (s.indexOf("ST.") === 0) s = s.slice(3);
      return s === String(vendorKey || "").trim().toUpperCase();
    }
    // ¿Es un traslado de aeropuerto (TRF IN / TRF OUT)? Esos NO comisionan para Karen.
    function isAirportTransferType(type) {
      var t = String(type || "").toUpperCase();
      return t.indexOf("TRF IN") !== -1 || t.indexOf("TRF OUT") !== -1;
    }
    function liquidacionRowsForVendor(vendorKey, ym, allRows) {
      if (vendorKey === "gianfranco") {
        // Gianfranco: TODOS los servicios de la agencia ese mes (los cierre quien los cierre).
        return allRows.filter((r) => isoYearMonth(r.date) === ym);
      }
      if (vendorKey === "karen") {
        // Karen (07/09): SOLO los servicios de SUS clientes (los que cerró ella), y sin contar
        // los traslados de aeropuerto (TRF IN / TRF OUT). Todo lo demás (Valle de Uco, Maipú,
        // Luján, Alta Montaña, cenas, etc.) comisiona.
        var byId = {};
        (state.clients || []).forEach(function (c) { if (c && c.id) byId[c.id] = c; });
        return allRows.filter(function (r) {
          if (isoYearMonth(r.date) !== ym) return false;
          if (isAirportTransferType(r.type)) return false;
          return clientSellerIs(byId[r.clientId], "karen");
        });
      }
      // Otros vendedores: reglas propias, aun no definidas.
      return [];
    }

    // Exporta la liquidacion del mes a un Excel (.xlsx) real, con resumen + detalle,
    // usando la misma libreria (SheetJS) que ya usa Dia a Dia / Actividad.
    function downloadLiquidacionExcel(vendorKey, ym, rows, cfg) {
      const count = rows.length;
      const perService = Number(cfg.perService) || 0;
      const salary = Number(cfg.salary) || 0;
      const commission = count * perService;
      const total = salary + commission;
      const vendorLabel = vendorKey === "gianfranco" ? "GIANFRANCO" : vendorKey.toUpperCase();
      const payments = liquidacionPaymentsFor(vendorKey, ym).slice().sort((a, b) => String(a.date).localeCompare(String(b.date)));
      const paid = payments.reduce((s, p) => s + (Number(p.amount) || 0), 0);
      const saldo = total - paid;
      const aoa = [];
      aoa.push(["LIQUIDACION - " + vendorLabel]);
      aoa.push(["Mes", liquidacionMonthLabel(ym)]);
      aoa.push([]);
      aoa.push(["Sueldo fijo", salary]);
      aoa.push(["Cantidad de servicios", count]);
      aoa.push(["Valor por servicio", perService]);
      aoa.push(["Comision (servicios x valor)", commission]);
      aoa.push(["TOTAL A LIQUIDAR", total]);
      aoa.push(["Pagado", paid]);
      aoa.push(["Saldo pendiente", saldo]);
      aoa.push([]);
      if (payments.length) {
        aoa.push(["PAGOS REGISTRADOS"]);
        aoa.push(["Fecha", "Metodo", "Monto", "Concepto / Nota", "Registro"]);
        payments.forEach((p) => {
          aoa.push([displayDate(p.date) || "", p.method || "", Number(p.amount) || 0, p.note || "", displaySellerName(p.by) || p.by || ""]);
        });
        aoa.push([]);
      }
      if (vendorKey === "karen") {
        // Planilla por cliente (07/09): #, N cliente, cliente, cantidad, valor; y abajo el detalle.
        const gmap = {}; const groups = [];
        rows.forEach((r) => { const k = r.clientId || String(r.number || ""); if (!gmap[k]) { gmap[k] = { number: r.number, client: r.client, services: [] }; groups.push(gmap[k]); } gmap[k].services.push(r); });
        groups.sort((a, b) => String(a.services[0].date).localeCompare(String(b.services[0].date)));
        aoa.push(["CLIENTES DE KAREN - " + liquidacionMonthLabel(ym)]);
        aoa.push(["#", "N Cliente", "Cliente", "Cant. servicios", "Valor por servicio", "Total"]);
        groups.forEach((g, i) => { aoa.push([i + 1, String(g.number || ""), g.client || "", g.services.length, perService, g.services.length * perService]); });
        aoa.push(["", "", "TOTAL", count, "", commission]);
        aoa.push([]);
        aoa.push(["DETALLE DE SERVICIOS"]);
        aoa.push(["N Cliente", "Cliente", "Fecha", "Servicio", "Pick up", "Valor"]);
        groups.forEach((g) => { g.services.slice().sort((a, b) => String(a.date).localeCompare(String(b.date))).forEach((r) => { aoa.push([String(g.number || ""), g.client || "", displayDate(r.date) || "", r.displayType || r.type || "", r.pickup || "", perService]); }); });
      } else {
      aoa.push(["DETALLE DE SERVICIOS"]);
      aoa.push(["#", "Fecha", "N Cliente", "Cliente", "Servicio", "Chofer"]);
      rows.forEach((r, i) => {
        const chofer = (r.driverNames && r.driverNames.length) ? r.driverNames.join(", ") : (r.driver || "");
        aoa.push([i + 1, displayDate(r.date) || "", String(r.number || ""), r.client || "", r.displayType || r.type || "", chofer]);
      });
      }
      ensureXLSXLib().then((XLSX) => {
        const ws = XLSX.utils.aoa_to_sheet(aoa);
        ws["!cols"] = [{ wch: 5 }, { wch: 12 }, { wch: 10 }, { wch: 30 }, { wch: 24 }, { wch: 24 }];
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, "Liquidacion");
        XLSX.writeFile(wb, "liquidacion_" + vendorKey + "_" + String(ym).replace("-", "_") + ".xlsx");
      }).catch((err) => {
        console.error(err);
        alert("No se pudo cargar la libreria para generar el Excel. Verifica tu conexion a internet.");
      });
    }

    function renderLiquidacion() {
      const host = document.getElementById("liquidacionBody");
      if (!host) return;
      if (!state.currentUser || !canAccess("liquidacionView")) { host.innerHTML = ""; return; }
      ensureLiquidacionStyles();

      const isDir = isDirectorUser(state.currentUser);
      const canManagePay = canManageLiquidacionPayments(); // Direccion + Iperique
      const isManager = isDir || canManagePay; // ve selector de vendedor (no es un vendedor)
      const selfVendorUser = liquidacionUsers.indexOf(state.currentUser) !== -1 ? state.currentUser : "";
      const userToVendorKey = { "st.gianfranco": "gianfranco", "st.karen": "karen" };

      // Vendedor objetivo: un vendedor ve SOLO el suyo; la Direccion puede elegir.
      if (selfVendorUser) {
        liquidacionUi.vendor = userToVendorKey[selfVendorUser] || "gianfranco";
      } else if (!liquidacionUi.vendor) {
        liquidacionUi.vendor = "gianfranco";
      }
      const vendorKey = liquidacionUi.vendor;
      const vendorLabel = vendorKey === "gianfranco" ? "GIANFRANCO" : vendorKey === "karen" ? "KAREN" : vendorKey.toUpperCase();

      // Renglones operativos (Logistica) reales, sin placeholders "CARGAR SERVICIOS".
      const allRows = buildLogisticaRows().filter((r) => !r.placeholder);

      // Meses disponibles (los que tienen servicios) + el mes activo del sistema.
      const monthsSet = {};
      allRows.forEach((r) => { const m = isoYearMonth(r.date); if (m) monthsSet[m] = true; });
      const activeYm = state.activeYear + "-" + pad(state.activeMonth);
      monthsSet[activeYm] = true;
      const months = Object.keys(monthsSet).sort().reverse();
      if (!liquidacionUi.ym || months.indexOf(liquidacionUi.ym) === -1) {
        liquidacionUi.ym = months.indexOf(activeYm) !== -1 ? activeYm : (months[0] || activeYm);
      }
      const ym = liquidacionUi.ym;

      const monthOptions = months.map((m) => "<option value=\"" + m + "\"" + (m === ym ? " selected" : "") + ">" + escapeHtml(liquidacionMonthLabel(m)) + "</option>").join("");
      const vendorSelector = isManager
        ? "<label class=\"liq-control\">Vendedor <select id=\"liqVendorSelect\">"
          + "<option value=\"gianfranco\"" + (vendorKey === "gianfranco" ? " selected" : "") + ">GIANFRANCO</option>"
          + "<option value=\"karen\"" + (vendorKey === "karen" ? " selected" : "") + ">KAREN</option>"
          + "</select></label>"
        : "";

      const head =
        "<div class=\"liq-header\">"
        + "<h2 class=\"liq-title\">LIQUIDACION</h2>"
        + "<div class=\"liq-controls\">"
        + vendorSelector
        + "<label class=\"liq-control\">Mes <select id=\"liqMonthSelect\">" + monthOptions + "</select></label>"
        + "</div>"
        + "</div>";

      // Vendedores sin reglas definidas: aviso claro, no numeros erroneos.
      if (vendorKey !== "gianfranco" && vendorKey !== "karen") {
        host.innerHTML = head
          + "<div class=\"liq-empty\">La liquidacion de <b>" + escapeHtml(vendorLabel) + "</b> todavia no esta configurada.</div>";
        const ms0 = document.getElementById("liqMonthSelect");
        if (ms0) ms0.addEventListener("change", (e) => { liquidacionUi.ym = e.target.value; renderLiquidacion(); });
        const vs0 = document.getElementById("liqVendorSelect");
        if (vs0) vs0.addEventListener("change", (e) => { liquidacionUi.vendor = e.target.value; renderLiquidacion(); });
        return;
      }

      // Valores del MES elegido (cada mes guarda su propio valor por servicio y sueldo).
      const cfg = liquidacionCfgForMonth(vendorKey, ym);
      const rows = liquidacionRowsForVendor(vendorKey, ym, allRows);
      const count = rows.length;
      const commission = count * (Number(cfg.perService) || 0);
      const total = (Number(cfg.salary) || 0) + commission;

      // Pagos (adelantos / parciales) de este vendedor y mes.
      const payments = liquidacionPaymentsFor(vendorKey, ym).slice().sort((a, b) => String(a.date).localeCompare(String(b.date)));
      const paid = payments.reduce((s, p) => s + (Number(p.amount) || 0), 0);
      const saldo = total - paid;
      const payState = paid <= 0 ? "pend" : (saldo > 0.5 ? "parcial" : "pagado");
      const payStateLabel = payState === "pend" ? "PENDIENTE DE PAGO" : (payState === "parcial" ? "PAGO PARCIAL" : "PAGADO");

      // Config: editable solo por Direccion (un vendedor no cambia su propio sueldo).
      const configBox =
        "<div class=\"liq-config\">"
        + "<div class=\"liq-config-item\"><span>Sueldo fijo</span>"
        + (isDir
            ? "<input type=\"number\" id=\"liqSalary\" value=\"" + (Number(cfg.salary) || 0) + "\" min=\"0\" step=\"1000\">"
            : "<b>" + formatMoney(cfg.salary) + "</b>")
        + "</div>"
        + "<div class=\"liq-config-item\"><span>Valor por servicio</span>"
        + (isDir
            ? "<input type=\"number\" id=\"liqPerService\" value=\"" + (Number(cfg.perService) || 0) + "\" min=\"0\" step=\"100\">"
            : "<b>" + formatMoney(cfg.perService) + "</b>")
        + "</div>"
        + "<div class=\"liq-config-item\" style=\"font-size:11px;color:#66727d;max-width:420px;\"><span>Valores de <b>" + escapeHtml(liquidacionMonthLabel(ym)) + "</b>"
        + (cfg.source === ym ? " (guardados para este mes)" : (cfg.source ? " (heredados de " + escapeHtml(liquidacionMonthLabel(cfg.source)) + ", todav\u00eda no se fij\u00f3 un valor propio)" : " (valor base, todav\u00eda no se fij\u00f3 un valor por mes)"))
        + ". Cada mes guarda su propio valor: si lo cambi\u00e1s ac\u00e1, se aplica a este mes y a los siguientes; los meses anteriores no cambian.</span></div>"
        + "</div>";

      // Nota de la regla del vendedor, para que quede claro qué se está contando.
      const reglaNota = vendorKey === "karen"
        ? "<div class=\"liq-empty\" style=\"padding:12px 16px;margin-bottom:14px;\">Karen comisiona <b>solo por sus clientes</b> (los que cerró ella) y por <b>cada servicio</b> de esos pasajeros — <b>sin contar</b> los traslados de aeropuerto (TRF IN / TRF OUT).</div>"
        : "";
      const summary =
        "<div class=\"liq-summary\">"
        + "<div class=\"liq-card\"><span>Servicios de " + escapeHtml(liquidacionMonthLabel(ym)) + (vendorKey === "karen" ? " (sus clientes)" : "") + "</span><strong>" + count + "</strong></div>"
        + "<div class=\"liq-card\"><span>Comision (" + count + " × " + formatMoney(cfg.perService) + ")</span><strong>" + formatMoney(commission) + "</strong></div>"
        + ((Number(cfg.salary) || 0) > 0 ? "<div class=\"liq-card\"><span>Sueldo fijo</span><strong>" + formatMoney(cfg.salary) + "</strong></div>" : "")
        + "<div class=\"liq-card liq-card-total\"><span>TOTAL A LIQUIDAR</span><strong>" + formatMoney(total) + "</strong></div>"
        + "<div class=\"liq-card\"><span>Pagado</span><strong>" + formatMoney(paid) + "</strong></div>"
        + "<div class=\"liq-card liq-card-" + payState + "\"><span>Saldo pendiente</span><strong>" + formatMoney(saldo) + "</strong></div>"
        + "</div>";

      // ----- Bloque de PAGOS (adelantos / parciales) -----
      const canManageThis = canManagePay; // Direccion + Iperique registran/borran pagos
      let payRowsHtml = "";
      if (payments.length) {
        payments.forEach((p) => {
          payRowsHtml +=
            "<tr>"
            + "<td>" + escapeHtml(displayDate(p.date) || "-") + "</td>"
            + "<td>" + escapeHtml(p.method || "-") + "</td>"
            + "<td>" + formatMoney(p.amount) + "</td>"
            + "<td>" + escapeHtml(p.note || "") + "</td>"
            + "<td>" + escapeHtml(displaySellerName(p.by) || p.by || "") + "</td>"
            + (canManageThis ? "<td><button class=\"btn btn-light liq-del-pay\" type=\"button\" data-del-pay=\"" + escapeHtml(p.id) + "\">✕</button></td>" : "")
            + "</tr>";
        });
      } else {
        payRowsHtml = "<tr><td colspan=\"" + (canManageThis ? 6 : 5) + "\" style=\"text-align:center;padding:14px;color:#889;\">Todavia no se registraron pagos de este mes.</td></tr>";
      }
      const payForm = canManageThis
        ? "<div class=\"liq-pay-form\">"
          + "<label class=\"liq-control\">Fecha <input type=\"date\" id=\"liqPayDate\" value=\"" + escapeHtml(todayIsoDate()) + "\"></label>"
          + "<label class=\"liq-control\">Metodo <select id=\"liqPayMethod\">" + LIQUIDACION_PAY_METHODS.map((m) => "<option value=\"" + m + "\">" + m + "</option>").join("") + "</select></label>"
          + "<label class=\"liq-control\">Monto <input type=\"number\" id=\"liqPayAmount\" min=\"0\" step=\"1000\" value=\"" + (saldo > 0 ? Math.round(saldo) : 0) + "\"></label>"
          + "<label class=\"liq-control liq-control-wide\">Concepto / Nota <input type=\"text\" id=\"liqPayNote\" placeholder=\"Ej: Adelanto, Sueldo fijo, Comisiones\"></label>"
          + "<button class=\"btn btn-main\" id=\"liqPayAdd\" type=\"button\">Registrar pago</button>"
          + "</div>"
        : "";
      const payBlock =
        "<div class=\"liq-pay\">"
        + "<div class=\"liq-pay-head\"><span>Pagos del mes</span>"
        + "<span class=\"liq-badge liq-badge-" + payState + "\">" + payStateLabel + "</span></div>"
        + payForm
        + "<table class=\"client-payment-table liq-pay-table\"><thead><tr>"
        + "<th>Fecha</th><th>Metodo</th><th>Monto</th><th>Concepto / Nota</th><th>Registro</th>"
        + (canManageThis ? "<th></th>" : "")
        + "</tr></thead><tbody>" + payRowsHtml + "</tbody></table>"
        + "</div>";

      let tableRows = "";
      const perSvc = Number(cfg.perService) || 0;
      // KAREN (07/09, pedido de Emilia): planilla POR CLIENTE. Columnas: #, N° cliente, nombre,
      // cantidad de servicios, valor (cantidad × valor del mes) y un "+" que despliega cuáles
      // fueron esos servicios. Sin chofer.
      const groupedByClient = vendorKey === "karen";
      const groups = [];
      if (groupedByClient) {
        const gmap = {};
        rows.forEach((r) => {
          const k = r.clientId || String(r.number || "") + "|" + (r.client || "");
          if (!gmap[k]) { gmap[k] = { number: r.number, client: r.client, services: [] }; groups.push(gmap[k]); }
          gmap[k].services.push(r);
        });
        groups.forEach((g) => g.services.sort((a, b) => String(a.date).localeCompare(String(b.date))));
        groups.sort((a, b) => String(a.services[0].date).localeCompare(String(b.services[0].date)) || (Number(a.number) || 0) - (Number(b.number) || 0));
      }
      if (groupedByClient && groups.length) {
        groups.forEach((g, i) => {
          const detailLines = g.services.map((r) =>
            "<div style=\"display:flex;gap:14px;padding:3px 0;border-bottom:1px dashed #e5e9ee;font-size:12px;\">"
            + "<span style=\"width:90px;color:#66727d;\">" + escapeHtml(displayDate(r.date) || "-") + "</span>"
            + "<span style=\"width:170px;font-weight:700;\">" + escapeHtml(r.displayType || r.type || "-") + "</span>"
            + "<span style=\"color:#66727d;\">" + escapeHtml(r.pickup ? "Pick up " + r.pickup : "") + "</span>"
            + "<span style=\"margin-left:auto;font-weight:700;\">" + formatMoney(perSvc) + "</span>"
            + "</div>").join("");
          tableRows +=
            "<tr>"
            + "<td>" + (i + 1) + "</td>"
            + "<td>" + escapeHtml(String(g.number || "")) + "</td>"
            + "<td style=\"text-align:left;\">" + escapeHtml(g.client || "-") + "</td>"
            + "<td><b>" + g.services.length + "</b></td>"
            + "<td><b>" + formatMoney(g.services.length * perSvc) + "</b></td>"
            + "<td><button type=\"button\" class=\"btn btn-light liq-expand\" data-liq-expand=\"" + i + "\" title=\"Ver qu\u00e9 servicios fueron\" style=\"padding:2px 10px;font-weight:800;\">+</button></td>"
            + "</tr>"
            + "<tr id=\"liqDetail" + i + "\" style=\"display:none;\"><td colspan=\"6\" style=\"text-align:left;background:#f8fafc;padding:6px 14px 8px 44px;\">" + detailLines + "</td></tr>";
        });
        tableRows +=
          "<tr style=\"background:#eef2f5;font-weight:800;\"><td></td><td></td><td style=\"text-align:left;\">TOTAL</td><td>" + count + "</td><td>" + formatMoney(commission) + "</td><td></td></tr>";
      } else if (groupedByClient) {
        tableRows = "<tr><td colspan=\"6\" style=\"text-align:center;padding:18px;\">No hay servicios de clientes de Karen en " + escapeHtml(liquidacionMonthLabel(ym)) + ".</td></tr>";
      } else if (count) {
        rows.forEach((r, i) => {
          const chofer = (r.driverNames && r.driverNames.length) ? r.driverNames.join(", ") : (r.driver || "-");
          tableRows +=
            "<tr>"
            + "<td>" + (i + 1) + "</td>"
            + "<td>" + escapeHtml(displayDate(r.date) || "-") + "</td>"
            + "<td>" + escapeHtml(String(r.number || "")) + "</td>"
            + "<td>" + escapeHtml(r.client || "-") + "</td>"
            + "<td>" + escapeHtml(r.displayType || r.type || "-") + "</td>"
            + "<td>" + escapeHtml(chofer) + "</td>"
            + "</tr>";
        });
      } else {
        tableRows = "<tr><td colspan=\"6\" style=\"text-align:center;padding:18px;\">No hay servicios en " + escapeHtml(liquidacionMonthLabel(ym)) + ".</td></tr>";
      }

      const detailHeadCols = groupedByClient
        ? "<th>#</th><th>N\u00b0 cliente</th><th style=\"text-align:left;\">Cliente</th><th>Servicios</th><th>Valor (\u00d7 " + formatMoney(perSvc) + ")</th><th></th>"
        : "<th>#</th><th>Fecha</th><th>N\u00b0</th><th>Cliente</th><th>Servicio</th><th>Chofer</th>";
      const detail =
        "<div class=\"liq-detail\">"
        + "<div class=\"liq-detail-head\"><span>" + (groupedByClient ? "Clientes de Karen con servicios en " + escapeHtml(liquidacionMonthLabel(ym)) + " (" + groups.length + " clientes \u00b7 " + count + " servicios)" : "Detalle de servicios (" + count + ")") + "</span>"
        + (count ? "<button class=\"btn btn-main\" id=\"liqExportBtn\" type=\"button\">↓ Exportar a Excel</button>" : "")
        + "</div>"
        + "<table class=\"client-payment-table liq-table\"><thead><tr>"
        + detailHeadCols
        + "</tr></thead><tbody>" + tableRows + "</tbody></table>"
        + "</div>";

      host.innerHTML = head + configBox + summary + payBlock + detail;

      // Listeners (se re-enganchan en cada render; los nodos viejos se descartan).
      const ms = document.getElementById("liqMonthSelect");
      if (ms) ms.addEventListener("change", (e) => { liquidacionUi.ym = e.target.value; renderLiquidacion(); });
      const vs = document.getElementById("liqVendorSelect");
      if (vs) vs.addEventListener("change", (e) => { liquidacionUi.vendor = e.target.value; renderLiquidacion(); });
      const exportBtn = document.getElementById("liqExportBtn");
      if (exportBtn) exportBtn.addEventListener("click", () => downloadLiquidacionExcel(vendorKey, ym, rows, cfg));
      host.querySelectorAll("[data-liq-expand]").forEach((btn) => {
        btn.addEventListener("click", () => {
          const tr = document.getElementById("liqDetail" + btn.getAttribute("data-liq-expand"));
          if (!tr) return;
          const open = tr.style.display !== "none";
          tr.style.display = open ? "none" : "";
          btn.textContent = open ? "+" : "\u2212";
        });
      });

      // Registrar un pago (Direccion + Iperique).
      const payAdd = document.getElementById("liqPayAdd");
      if (payAdd) payAdd.addEventListener("click", () => {
        const dEl = document.getElementById("liqPayDate");
        const mEl = document.getElementById("liqPayMethod");
        const aEl = document.getElementById("liqPayAmount");
        const nEl = document.getElementById("liqPayNote");
        const amount = Math.round(Number(aEl && aEl.value) || 0);
        if (!amount || amount <= 0) { alert("Ingresa un monto mayor a 0."); return; }
        if (!dEl || !dEl.value) { alert("Elegi la fecha del pago."); return; }
        const key = liquidacionPayKey(vendorKey, ym);
        const map = Object.assign({}, state.liquidacionPayments || {});
        const list = Array.isArray(map[key]) ? map[key].slice() : [];
        const newPay = { id: makeId(), date: dEl.value, method: (mEl && mEl.value) || "Efectivo", amount: amount, note: (nEl && nEl.value || "").trim(), by: state.currentUser || "", at: nowStamp() };
        list.push(newPay);
        sessionCreatedLiqPayIds.add(newPay.id);
        map[key] = list;
        state.liquidacionPayments = map;
        persistLiquidacionPayments();
        renderLiquidacion();
      });
      // Borrar un pago (Direccion + Iperique).
      host.querySelectorAll("[data-del-pay]").forEach((btn) => {
        btn.addEventListener("click", () => {
          const id = btn.getAttribute("data-del-pay");
          if (!window.confirm("Eliminar este pago registrado?")) return;
          sessionDeletedLiqPayIds.add(id);
          const key = liquidacionPayKey(vendorKey, ym);
          const map = Object.assign({}, state.liquidacionPayments || {});
          map[key] = (map[key] || []).filter((p) => p.id !== id);
          state.liquidacionPayments = map;
          persistLiquidacionPayments();
          renderLiquidacion();
        });
      });

      if (isDir) {
        const sal = document.getElementById("liqSalary");
        const per = document.getElementById("liqPerService");
        const saveCfg = () => {
          const cfgNow = normalizeLiquidacionConfig(state.liquidacionConfig);
          if (!cfgNow[vendorKey]) cfgNow[vendorKey] = { salary: 0, perService: 0, byMonth: {} };
          if (!cfgNow[vendorKey].byMonth) cfgNow[vendorKey].byMonth = {};
          // Se guarda para el MES que se esta viendo (no pisa los meses anteriores).
          const cur = liquidacionCfgForMonth(vendorKey, ym);
          cfgNow[vendorKey].byMonth[ym] = {
            salary: sal ? Math.max(0, Number(sal.value) || 0) : cur.salary,
            perService: per ? Math.max(0, Number(per.value) || 0) : cur.perService
          };
          sessionEditedLiqMonths.add(vendorKey + "|" + ym);
          state.liquidacionConfig = cfgNow;
          persistLiquidacionConfig();
          renderLiquidacion();
        };
        if (sal) sal.addEventListener("change", saveCfg);
        if (per) per.addEventListener("change", saveCfg);
      }
    }

    // ============================ MODULO HOTELES ============================
    const hotelesUi = { search: "", zoneFilter: "", editingId: "" };
    function ensureHotelesStyles() {
      if (document.getElementById("hoteles-styles")) return;
      const st = document.createElement("style");
      st.id = "hoteles-styles";
      st.textContent = [
        ".htl-header{margin-bottom:14px;}",
        ".htl-title{font-size:20px;font-weight:800;letter-spacing:1px;color:#2f5d3a;margin:0 0 4px;}",
        ".htl-sub{font-size:12px;color:#66727d;font-weight:600;}",
        ".htl-add{display:flex;gap:10px;flex-wrap:wrap;align-items:center;background:#f6f8f6;border:1px solid #e0e6e0;border-radius:10px;padding:12px;margin-bottom:14px;}",
        ".htl-add input,.htl-add select,.htl-toolbar input,.htl-toolbar select{padding:8px 10px;border:1px solid #cdd6df;border-radius:8px;font-size:14px;}",
        ".htl-add input{min-width:220px;}",
        ".htl-toolbar{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:10px;}",
        ".htl-toolbar input{min-width:240px;}",
        ".htl-table{width:100%;}",
        ".htl-table th{background:#2f5d3a;color:#fff;position:sticky;top:0;}",
        ".htl-table td{font-size:13px;vertical-align:middle;}",
        ".htl-zone-sel{padding:5px 8px;border:1px solid #cdd6df;border-radius:6px;font-size:13px;}",
        ".htl-loc-inp{padding:5px 8px;border:1px solid #e2e6ea;border-radius:6px;font-size:13px;width:100%;max-width:220px;}",
        ".htl-name-inp{padding:5px 8px;border:1px solid #cdd6df;border-radius:6px;font-size:13px;width:100%;max-width:260px;}",
        ".htl-actions{white-space:nowrap;}",
        ".htl-edit{padding:2px 10px;font-weight:700;}",
        ".htl-del{padding:2px 10px;color:#b3352f;font-weight:800;}",
        ".htl-zone-empty{background:#fdf0e6;}"
      ].join("");
      document.head.appendChild(st);
    }
    function renderHoteles() {
      const host = document.getElementById("hotelesBody");
      if (!host) return;
      if (!state.currentUser || !canAccess("hotelesView")) { host.innerHTML = ""; return; }
      ensureHotelesStyles();
      const cat = (state.hotelsCatalog || []).slice().sort((a, b) => String(a.name).localeCompare(String(b.name), "es"));
      const total = cat.length;
      const byZone = {};
      cat.forEach((h) => { const z = h.zone || "Sin zona"; byZone[z] = (byZone[z] || 0) + 1; });
      const zonesLine = HOTEL_ZONES.map((z) => z + ": " + (byZone[z] || 0)).join("  ·  ") + (byZone["Sin zona"] ? ("  ·  Sin zona: " + byZone["Sin zona"]) : "");
      const zoneOpts = (sel) => HOTEL_ZONES.map((z) => "<option value=\"" + z + "\"" + (z === sel ? " selected" : "") + ">" + z + "</option>").join("");

      let bodyRows = "";
      cat.forEach((h) => {
        const editing = hotelesUi.editingId === h.id;
        const nameCell = editing
          ? "<td><input class=\"htl-name-inp\" data-htl-name-edit=\"" + escapeHtml(h.id) + "\" value=\"" + escapeHtml(h.name) + "\"></td>"
          : "<td>" + escapeHtml(h.name) + "</td>";
        const actionsCell = editing
          ? "<td class=\"htl-actions\"><button class=\"btn btn-main htl-save\" type=\"button\" data-htl-save=\"" + escapeHtml(h.id) + "\">Guardar</button> <button class=\"btn btn-light htl-cancel\" type=\"button\" data-htl-cancel=\"" + escapeHtml(h.id) + "\">Cancelar</button></td>"
          : "<td class=\"htl-actions\"><button class=\"btn btn-light htl-edit\" type=\"button\" data-htl-edit=\"" + escapeHtml(h.id) + "\" title=\"Editar\">✎ Editar</button> <button class=\"btn btn-light htl-del\" type=\"button\" data-htl-del=\"" + escapeHtml(h.id) + "\" title=\"Eliminar\">✕</button></td>";
        bodyRows +=
          "<tr data-htl-name=\"" + escapeHtml(slugHotel(h.name)) + "\" data-htl-zone-row=\"" + escapeHtml(h.zone || "") + "\" data-htl-loc-row=\"" + escapeHtml(slugHotel(h.locality)) + "\">"
          + nameCell
          + "<td><select class=\"htl-zone-sel" + (h.zone ? "" : " htl-zone-empty") + "\" data-htl-zone=\"" + escapeHtml(h.id) + "\"><option value=\"\">(elegir)</option>" + zoneOpts(h.zone) + "</select></td>"
          + "<td><input class=\"htl-loc-inp\" data-htl-loc=\"" + escapeHtml(h.id) + "\" value=\"" + escapeHtml(h.locality || "") + "\" placeholder=\"-\"></td>"
          + actionsCell
          + "</tr>";
      });

      host.innerHTML =
        "<div class=\"htl-header\"><h2 class=\"htl-title\">HOTELES</h2><div class=\"htl-sub\">" + total + " hoteles  ·  " + zonesLine + "</div></div>"
        + "<div class=\"htl-add\">"
        + "<input id=\"htlNewName\" placeholder=\"Nombre del hotel\">"
        + "<select id=\"htlNewZone\"><option value=\"\">Zona…</option>" + zoneOpts("") + "</select>"
        + "<input id=\"htlNewLoc\" placeholder=\"Localidad (opcional)\">"
        + "<button class=\"btn btn-main\" id=\"htlAdd\" type=\"button\">Agregar hotel</button>"
        + "</div>"
        + "<div class=\"htl-toolbar\">"
        + "<input id=\"htlSearch\" placeholder=\"Buscar hotel…\" value=\"" + escapeHtml(hotelesUi.search) + "\">"
        + "<select id=\"htlZoneFilter\"><option value=\"\">Todas las zonas</option>" + zoneOpts(hotelesUi.zoneFilter) + "</select>"
        + "</div>"
        + "<table class=\"client-payment-table htl-table\"><thead><tr><th>Hotel</th><th>Zona</th><th>Localidad</th><th></th></tr></thead><tbody id=\"htlTbody\">" + bodyRows + "</tbody></table>";

      const applyFilter = () => {
        const s = document.getElementById("htlSearch");
        const zf = document.getElementById("htlZoneFilter");
        hotelesUi.search = s ? s.value : "";
        hotelesUi.zoneFilter = zf ? zf.value : "";
        const q = slugHotel(hotelesUi.search);
        const z = hotelesUi.zoneFilter;
        host.querySelectorAll("#htlTbody tr").forEach((tr) => {
          const name = tr.getAttribute("data-htl-name") || "";
          const loc = tr.getAttribute("data-htl-loc-row") || "";
          const zone = tr.getAttribute("data-htl-zone-row") || "";
          const okQ = !q || name.indexOf(q) !== -1 || loc.indexOf(q) !== -1;
          const okZ = !z || zone === z;
          tr.style.display = (okQ && okZ) ? "" : "none";
        });
      };
      applyFilter();

      const sEl = document.getElementById("htlSearch");
      if (sEl) sEl.addEventListener("input", applyFilter);
      const zfEl = document.getElementById("htlZoneFilter");
      if (zfEl) zfEl.addEventListener("change", applyFilter);

      const addBtn = document.getElementById("htlAdd");
      if (addBtn) addBtn.addEventListener("click", () => {
        const nEl = document.getElementById("htlNewName");
        const zEl = document.getElementById("htlNewZone");
        const lEl = document.getElementById("htlNewLoc");
        const name = (nEl && nEl.value || "").trim();
        const zone = (zEl && zEl.value) || "";
        if (!name) { alert("Escribi el nombre del hotel."); return; }
        if (!zone) { alert("Elegi la zona del hotel."); return; }
        const exists = (state.hotelsCatalog || []).some((h) => slugHotel(h.name) === slugHotel(name) && h.zone === zone);
        if (exists) { alert("Ese hotel ya esta cargado en esa zona."); return; }
        state.hotelsCatalog = (state.hotelsCatalog || []).concat([normalizeHotelCatalogItem({ name: name, zone: zone, locality: (lEl && lEl.value || "").trim() })]);
        persistHotelsCatalog();
        renderHoteles();
      });

      host.querySelectorAll("[data-htl-zone]").forEach((sel) => {
        sel.addEventListener("change", () => {
          const id = sel.getAttribute("data-htl-zone");
          const h = (state.hotelsCatalog || []).find((x) => x.id === id);
          if (h) { h.zone = sel.value; persistHotelsCatalog(); renderHoteles(); }
        });
      });
      host.querySelectorAll("[data-htl-loc]").forEach((inp) => {
        inp.addEventListener("change", () => {
          const id = inp.getAttribute("data-htl-loc");
          const h = (state.hotelsCatalog || []).find((x) => x.id === id);
          if (h) { h.locality = inp.value.trim(); persistHotelsCatalog(); }
        });
      });
      host.querySelectorAll("[data-htl-del]").forEach((btn) => {
        btn.addEventListener("click", () => {
          const id = btn.getAttribute("data-htl-del");
          const h = (state.hotelsCatalog || []).find((x) => x.id === id);
          if (!h) return;
          if (!window.confirm("Eliminar el hotel \"" + h.name + "\" del catalogo?")) return;
          state.hotelsCatalog = (state.hotelsCatalog || []).filter((x) => x.id !== id);
          persistHotelsCatalog();
          renderHoteles();
        });
      });
      // Editar (nombre): abre modo edicion en la fila.
      host.querySelectorAll("[data-htl-edit]").forEach((btn) => {
        btn.addEventListener("click", () => { hotelesUi.editingId = btn.getAttribute("data-htl-edit"); renderHoteles(); });
      });
      host.querySelectorAll("[data-htl-cancel]").forEach((btn) => {
        btn.addEventListener("click", () => { hotelesUi.editingId = ""; renderHoteles(); });
      });
      host.querySelectorAll("[data-htl-save]").forEach((btn) => {
        btn.addEventListener("click", () => {
          const id = btn.getAttribute("data-htl-save");
          const h = (state.hotelsCatalog || []).find((x) => x.id === id);
          if (!h) return;
          const inp = host.querySelector("[data-htl-name-edit=\"" + id + "\"]");
          const newName = (inp && inp.value || "").trim();
          if (!newName) { alert("El nombre no puede quedar vacio."); return; }
          const collision = (state.hotelsCatalog || []).some((x) => x.id !== id && slugHotel(x.name) === slugHotel(newName) && x.zone === h.zone);
          if (collision) { alert("Ya existe otro hotel con ese nombre en la misma zona."); return; }
          h.name = newName;
          hotelesUi.editingId = "";
          persistHotelsCatalog();
          renderHoteles();
        });
      });
    }

    // ============================ MODULO TARIFAS CHOFERES ============================
    function ensureTarifasStyles() {
      if (document.getElementById("tarifas-styles")) return;
      const st = document.createElement("style");
      st.id = "tarifas-styles";
      st.textContent = [
        ".tar-title{font-size:20px;font-weight:800;letter-spacing:1px;color:#2f5d3a;margin:0 0 4px;}",
        ".tar-sub{font-size:12px;color:#66727d;font-weight:600;margin-bottom:16px;}",
        ".tar-section-title{font-size:15px;font-weight:800;color:#22303c;margin:18px 0 8px;}",
        ".tar-table{width:100%;margin-bottom:8px;}",
        ".tar-table th{background:#2f5d3a;color:#fff;}",
        ".tar-table td{font-size:13px;}",
        ".tar-table input{padding:5px 8px;border:1px solid #cdd6df;border-radius:6px;font-size:13px;}",
        ".tar-zona{width:100%;min-width:200px;}",
        ".tar-precio{width:110px;text-align:right;}",
        ".tar-del{padding:2px 10px;color:#b3352f;font-weight:800;}",
        ".tar-add{margin:4px 0 10px;}"
      ].join("");
      document.head.appendChild(st);
    }
    function renderTarifas() {
      const host = document.getElementById("tarifasBody");
      if (!host) return;
      if (!state.currentUser || !canAccess("tarifasView")) { host.innerHTML = ""; return; }
      ensureTarifasStyles();
      const T = state.driverTariffs || { propios: [], terceros: [] };
      const money = (v) => (v === "" || v == null) ? "" : String(v);
      // PROPIOS
      let pRows = "";
      (T.propios || []).forEach((r, i) => {
        pRows += "<tr>"
          + "<td><input class=\"tar-zona\" data-tar-pz=\"" + i + "\" value=\"" + escapeHtml(r.zona) + "\"></td>"
          + "<td><input class=\"tar-precio\" type=\"number\" min=\"0\" data-tar-p14=\"" + i + "\" value=\"" + escapeHtml(money(r.p14)) + "\" placeholder=\"A cot\"></td>"
          + "<td><input class=\"tar-precio\" type=\"number\" min=\"0\" data-tar-p517=\"" + i + "\" value=\"" + escapeHtml(money(r.p517)) + "\" placeholder=\"A cot\"></td>"
          + "<td><button class=\"btn btn-light tar-del\" type=\"button\" data-tar-pdel=\"" + i + "\">✕</button></td>"
          + "</tr>";
      });
      // TERCEROS
      let tRows = "";
      (T.terceros || []).forEach((r, i) => {
        tRows += "<tr>"
          + "<td><input class=\"tar-zona\" data-tar-tz=\"" + i + "\" value=\"" + escapeHtml(r.zona) + "\"></td>"
          + "<td><input class=\"tar-precio\" type=\"number\" min=\"0\" data-tar-tp=\"" + i + "\" value=\"" + escapeHtml(money(r.precio)) + "\" placeholder=\"A cot\"></td>"
          + "<td><button class=\"btn btn-light tar-del\" type=\"button\" data-tar-tdel=\"" + i + "\">✕</button></td>"
          + "</tr>";
      });
      host.innerHTML =
        "<h2 class=\"tar-title\">TARIFAS CHOFERES</h2>"
        + "<div class=\"tar-sub\">Lo que se le paga al chofer por servicio. PROPIOS = empleados (por cantidad de pasajeros). TERCEROS = auto propio (precio único).</div>"
        + "<div class=\"tar-section-title\">PROPIOS (empleados)</div>"
        + "<table class=\"client-payment-table tar-table\"><thead><tr><th>Zona / Servicio</th><th>1 a 4 pax</th><th>5 a 17 pax</th><th></th></tr></thead><tbody>" + pRows + "</tbody></table>"
        + "<button class=\"btn btn-light tar-add\" id=\"tarAddP\" type=\"button\">+ Agregar fila (propios)</button>"
        + "<div class=\"tar-section-title\">TERCEROS (auto propio)</div>"
        + "<table class=\"client-payment-table tar-table\"><thead><tr><th>Zona / Servicio</th><th>Precio</th><th></th></tr></thead><tbody>" + tRows + "</tbody></table>"
        + "<button class=\"btn btn-light tar-add\" id=\"tarAddT\" type=\"button\">+ Agregar fila (terceros)</button>";

      const commit = () => { persistDriverTariffs(); };
      // editar campos (change = al salir del campo)
      host.querySelectorAll("[data-tar-pz]").forEach((el) => el.addEventListener("change", () => { T.propios[+el.getAttribute("data-tar-pz")].zona = el.value.trim(); commit(); }));
      host.querySelectorAll("[data-tar-p14]").forEach((el) => el.addEventListener("change", () => { T.propios[+el.getAttribute("data-tar-p14")].p14 = _tarNum(el.value); commit(); }));
      host.querySelectorAll("[data-tar-p517]").forEach((el) => el.addEventListener("change", () => { T.propios[+el.getAttribute("data-tar-p517")].p517 = _tarNum(el.value); commit(); }));
      host.querySelectorAll("[data-tar-tz]").forEach((el) => el.addEventListener("change", () => { T.terceros[+el.getAttribute("data-tar-tz")].zona = el.value.trim(); commit(); }));
      host.querySelectorAll("[data-tar-tp]").forEach((el) => el.addEventListener("change", () => { T.terceros[+el.getAttribute("data-tar-tp")].precio = _tarNum(el.value); commit(); }));
      host.querySelectorAll("[data-tar-pdel]").forEach((el) => el.addEventListener("click", () => { if (!window.confirm("Eliminar esta fila de tarifa?")) return; T.propios.splice(+el.getAttribute("data-tar-pdel"), 1); persistDriverTariffs(); renderTarifas(); }));
      host.querySelectorAll("[data-tar-tdel]").forEach((el) => el.addEventListener("click", () => { if (!window.confirm("Eliminar esta fila de tarifa?")) return; T.terceros.splice(+el.getAttribute("data-tar-tdel"), 1); persistDriverTariffs(); renderTarifas(); }));
      const addP = document.getElementById("tarAddP");
      if (addP) addP.addEventListener("click", () => { T.propios.push({ zona: "", p14: "", p517: "" }); persistDriverTariffs(); renderTarifas(); });
      const addT = document.getElementById("tarAddT");
      if (addT) addT.addEventListener("click", () => { T.terceros.push({ zona: "", precio: "" }); persistDriverTariffs(); renderTarifas(); });
    }

    // ============================ LIQUIDACION DE CHOFERES (C2 + C3) ============================
    function _drvU(s) { return String(s || "").toUpperCase(); }
    function _isLargoStop(st) { const p = _drvU(st && st.provider); return p.indexOf("PIEDRA INFINITA") !== -1 || p.indexOf("ALFA CRUX") !== -1; }
    // DETECTOR (C2): dado un servicio, sugiere la zona/tarifa del chofer.
    function suggestDriverZone(service, client, driverType) {
      const t = _drvU(service.type);
      const stops = Array.isArray(service.stops) ? service.stops : [];
      const regions = [...new Set(stops.map((s) => _drvU(s.region)).filter(Boolean))];
      const nBod = stops.length;
      const emp = driverType === "EMPLEADO SINEUS";
      const zEnd = hotelZoneForName(hotelForDate(client, service.date));
      const zStart = hotelZoneForName(hotelForDate(client, shiftIsoDate(service.date, -1))) || zEnd;
      const OK = (z) => ({ zona: z, revisar: false, motivo: "" });
      const REV = (m) => ({ zona: "", revisar: true, motivo: m });
      // Traslados aeropuerto (por zona del hotel)
      if (t.indexOf("TRF IN") !== -1 || t.indexOf("TRF OUT") !== -1) {
        const z = t.indexOf("TRF IN") !== -1 ? zEnd : zStart;
        if (!z) return REV("falta zona del hotel");
        if (z === "Centro") return OK("TRANSFER CENTRO");
        if (z === "Valle de Uco") return OK("TRANSFER UCO");
        return OK(emp ? "TRANSFER LUJAN" : "TRANSFER LUJAN/MAIPU");
      }
      // Servicios con nombre propio (antes que cena, para "X / CENA")
      if (t.indexOf("ALTA MONTA") !== -1) return OK(emp ? (zStart === "Valle de Uco" ? "ALTA MONTAÑA DESDE UCO" : "ALTA MONTAÑA") : "ALTA MONTAÑA");
      if (t.indexOf("CACHEUTA") !== -1) return OK("CACHEUTA FULL DAY");
      if (t.indexOf("POTRERILLOS") !== -1) return OK(emp ? "POTRERILLOS ALMUERZO" : "POTRERILLOS SALIDA CENTRO");
      if (t.indexOf("VILLAVICENCIO") !== -1) return OK("VILLAVICENCIO");
      if (t.indexOf("LEÑAS") !== -1 || t.indexOf("LENAS") !== -1) return OK("VIAJE LAS LEÑAS");
      if (t.indexOf("CITY TOUR") !== -1) return OK("CITY TOUR");
      // Cena
      if (t.indexOf("CENA") !== -1) {
        const z = zEnd || zStart;
        if (z === "Centro") return OK("CENA CENTRO");
        if (z === "Valle de Uco") return OK(emp ? "CENA UCO" : "CENA UCO-CORTO");
        if (z === "Lujan" || z === "Maipu") return OK("CENA LUJAN");
        return REV("falta zona del hotel (cena)");
      }
      // Paseos por region
      const inUco = regions.some((r) => r.indexOf("UCO") !== -1);
      const inLM = regions.some((r) => r.indexOf("LUJAN") !== -1 || r.indexOf("MAIPU") !== -1);
      if (inUco && !inLM) {
        if (emp) return OK(nBod <= 1 ? "V. UCO ALM 1 BOD" : "V. UCO");
        const largo = stops.some(_isLargoStop);
        return OK("V. UCO " + (largo ? "LARGO" : "CORTO") + " " + (nBod <= 1 ? "1 BOD" : "2 A 3 BOD"));
      }
      if (inLM && !inUco) {
        if (emp) return OK(nBod <= 1 ? "LUJAN / MAIPU 1 BODEGA" : "LUJAN / MAIPU (2 A 3 BOD)");
        const cruce = zStart && zEnd && zStart !== zEnd;
        if (cruce && nBod >= 2) return OK("LUJAN MAIPU CRUCE 2 A 3 BOD");
        return OK(nBod <= 1 ? "LUJAN / MAIPU 1 BOD" : "LUJAN / MAIPU 2 A 3 BOD");
      }
      return REV("tipo/región no reconocido");
    }
    function _sameZonaKey(a, b) { return _drvU(a).replace(/\s+/g, " ").trim() === _drvU(b).replace(/\s+/g, " ").trim(); }
    function driverTariffPrice(driverType, zona, pax) {
      if (!zona) return "";
      const T = state.driverTariffs || { propios: [], terceros: [] };
      if (driverType === "EMPLEADO SINEUS") {
        const r = (T.propios || []).find((x) => _sameZonaKey(x.zona, zona));
        if (!r) return "";
        return (Number(pax) || 0) <= 4 ? r.p14 : r.p517;
      }
      const r = (T.terceros || []).find((x) => _sameZonaKey(x.zona, zona));
      return r ? r.precio : "";
    }
    function driverServicesForMonth(driverName, ym) {
      const out = [];
      (state.clients || []).forEach((c) => {
        if (c.leadStatus !== "Cerrado") return;
        operationalServicesForClient(c).forEach((s) => {
          if (isoYearMonth(s.date) !== ym) return;
          const drivers = [s.driver].concat((Array.isArray(s.assignments) ? s.assignments : []).map((a) => a.driver)).filter(Boolean);
          if (!drivers.some((d) => sameText(d, driverName))) return;
          out.push({ client: c, service: s });
        });
      });
      out.sort((a, b) => String(a.service.date).localeCompare(String(b.service.date)));
      return out;
    }
    // Igual que driverServicesForMonth pero por RANGO de fechas ISO (desde/hasta inclusive).
    // Sirve para liquidar por semana, quincena o mes según lo que elija la dirección.
    function driverServicesForRange(driverName, fromIso, toIso) {
      const out = [];
      const lo = String(fromIso || ""), hi = String(toIso || "");
      (state.clients || []).forEach((c) => {
        if (c.leadStatus !== "Cerrado") return;
        operationalServicesForClient(c).forEach((s) => {
          const d = String(s.date || "");
          if (!d) return;
          if (lo && d < lo) return;
          if (hi && d > hi) return;
          const drivers = [s.driver].concat((Array.isArray(s.assignments) ? s.assignments : []).map((a) => a.driver)).filter(Boolean);
          if (!drivers.some((dr) => sameText(dr, driverName))) return;
          out.push({ client: c, service: s });
        });
      });
      out.sort((a, b) => String(a.service.date).localeCompare(String(b.service.date)));
      return out;
    }
    // Primer y último día (ISO) de un mes "YYYY-MM".
    function ymRange(ym) {
      const parts = String(ym || "").split("-");
      if (parts.length < 2) return { from: "", to: "" };
      const y = Number(parts[0]), m = Number(parts[1]);
      if (!y || !m) return { from: "", to: "" };
      const last = new Date(y, m, 0).getDate();
      return { from: y + "-" + pad(m) + "-01", to: y + "-" + pad(m) + "-" + pad(last) };
    }

    const liqChoferUi = { driver: "", ym: "", from: "", to: "", payMethod: LIQUIDACION_PAY_METHODS[1] };
