        ".lqc-pay{margin-top:22px;border:1px solid #e2e6ea;border-radius:12px;padding:16px 18px;background:#fbfcfe;}",
        ".lqc-pay h4{margin:0 0 12px;font-size:14px;color:var(--blue,#174f8f);font-weight:800;text-transform:uppercase;letter-spacing:.02em;}",
        ".lqc-pay-form{display:flex;gap:10px;flex-wrap:wrap;align-items:flex-end;}",
