        ".lqc-pay-list{margin-top:14px;display:flex;flex-direction:column;gap:8px;}",
        ".lqc-pay-row{display:flex;gap:12px;align-items:center;flex-wrap:wrap;background:#fff;border:1px solid #e6ebf0;border-radius:8px;padding:8px 12px;font-size:13px;}",
        ".lqc-pay-row .amt{font-weight:800;color:#1f7a44;}",
        ".lqc-pay-row .meta{color:#66727d;}",
        ".lqc-pay-del{margin-left:auto;background:#fff;border:1px solid #e0b4b0;color:#b3352f;border-radius:6px;padding:4px 10px;cursor:pointer;font-weight:700;}",
