    function renderItineraryTransfers(client) {
      els.itineraryTransfersBody.classList.toggle("collapsed", state.itineraryTransfersCollapsed);
      els.toggleItineraryTransfersButton.textContent = state.itineraryTransfersCollapsed ? "Mostrar v" : "Ocultar ^";
      els.toggleItineraryTransfersButton.setAttribute("aria-expanded", String(!state.itineraryTransfersCollapsed));
      els.itineraryTransfersBody.innerHTML = "";
      const transfers = state.draftItinerarySteps
        .map((step, index) => ({ step: step, index: index }))
        .filter((row) => row.step.kind === "transfer");
      if (!transfers.length) {
        els.itineraryTransfersBody.append(emptyBlock("No hay traslados, puedes agregar uno con el boton Agregar traslado."));
        return;
      }
      transfers.forEach((row) => {
        els.itineraryTransfersBody.append(renderItineraryTransferCard(row.step, row.index, client));
      });
    }

    function renderItineraryTourDays(client) {
      const mode = normalizeItineraryMode(state.draftItineraryMode);
      els.itineraryTourDaysBody.innerHTML = "";
      const tours = state.draftItinerarySteps
        .map((step, index) => ({ step: step, index: index }))
        .filter((row) => row.step.kind !== "transfer");
      const groups = {};
      tours.forEach((row) => {
        const key = row.step.date || client.from || "";
        groups[key] = groups[key] || [];
        groups[key].push(row);
      });
      const dates = new Set(travelDates(client));
      Object.keys(groups).forEach((date) => dates.add(date || client.from || ""));
      if (!dates.size) dates.add(client && client.from ? client.from : state.activeYear + "-" + pad(state.activeMonth) + "-01");
      [...dates].filter(Boolean).sort().forEach((date) => {
        const block = document.createElement("div");
        block.className = "itinerary-section";
        const title = (dayName(date) ? dayName(date) + " " : "") + (displayDateLong(date) || "Sin fecha");
        block.innerHTML = [
          "<div class=\"itinerary-section-head\">",
          "<span></span>",
          mode === "transfers"
            ? "<div class=\"itinerary-head-actions\"><button class=\"btn btn-light add-tour-on-date\" data-add-tour-date=\"\" type=\"button\">Agregar bodega sin valor</button><button class=\"btn btn-light collapse-toggle\" data-toggle-tour-date=\"\" type=\"button\">Ocultar ^</button></div>"
            : "<div class=\"itinerary-head-actions\"><button class=\"btn btn-light add-tour-on-date\" data-add-tour-date=\"\" type=\"button\">Agregar bodega</button><button class=\"btn btn-light\" data-add-dinner-date=\"\" type=\"button\">Agregar cena</button><button class=\"btn btn-light\" data-add-standalone-transfer=\"\" type=\"button\">Crear traslado</button><button class=\"btn btn-light collapse-toggle\" data-toggle-tour-date=\"\" type=\"button\">Ocultar ^</button></div>",
          "</div>",
          "<div class=\"itinerary-section-body\"></div>",
          "<div class=\"itinerary-section-footer\"><button class=\"btn btn-main\" data-create-booking-date=\"\" type=\"button\">Crear reserva</button></div>"
        ].join("");
        block.querySelector("span").textContent = title;
        block.querySelector("[data-add-tour-date]").dataset.addTourDate = date;
        if (block.querySelector("[data-add-dinner-date]")) block.querySelector("[data-add-dinner-date]").dataset.addDinnerDate = date;
        if (block.querySelector("[data-add-standalone-transfer]")) block.querySelector("[data-add-standalone-transfer]").dataset.addStandaloneTransfer = date;
        if (block.querySelector("[data-create-booking-date]")) block.querySelector("[data-create-booking-date]").dataset.createBookingDate = date;
        block.querySelector("[data-toggle-tour-date]").dataset.toggleTourDate = date;
        const body = block.querySelector(".itinerary-section-body");
        body.classList.toggle("collapsed", Boolean(state.itineraryDayCollapsed[date]));
        block.querySelector("[data-toggle-tour-date]").textContent = state.itineraryDayCollapsed[date] ? "Mostrar v" : "Ocultar ^";
        if (groups[date] && groups[date].length) {
          groups[date].forEach((row) => body.append(
            row.step.standaloneTransfer ? renderItineraryStandaloneTransferCard(row.step, row.index, client) :
            isDinnerStep(row.step) ? renderItineraryDinnerCard(row.step, row.index, client) :
            renderItineraryTourCard(row.step, row.index, client)
          ));
        } else {
          body.append(emptyBlock("Sin bodegas o reservas cargadas para esta fecha."));
        }
        els.itineraryTourDaysBody.append(block);
      });
    }

    function travelDates(client) {
      const start = dateValue(client && client.from);
      const end = dateValue(client && client.to);
      if (!start || !end || end < start) return client && client.from ? [inputDate(client.from)] : [];
      const dates = [];
      const current = new Date(start);
      const limit = new Date(end);
      while (current.getTime() <= limit.getTime() && dates.length < 45) {
        dates.push(current.getFullYear() + "-" + pad(current.getMonth() + 1) + "-" + pad(current.getDate()));
        current.setDate(current.getDate() + 1);
      }
      return dates;
    }

    function transferTypeOptionsHtml(mode, baseOptions) {
      const options = (baseOptions || []).slice();
      if (itineraryModeAllowsReservationFee(mode) && !options.some((item) => item[0] === "Tasa de reserva")) {
        options.push(["Tasa de reserva", "Tasa de reserva"]);
      }
      return options.map((item) => "<option value=\"" + escapeHtml(item[0]) + "\">" + escapeHtml(item[1]) + "</option>").join("");
    }

    function regularTransferFieldsHtml(mode, placeholder) {
      if (!itineraryModeAllowsTransfers(mode)) return "";
      return [
        "<label>Tipo de traslado<select data-itinerary-field=\"transferType\">" + transferTypeOptionsHtml(mode, [["", "Seleccionar"], ["Privado", "Privado"], ["Regular", "Regular"], ["Sin traslado", "Sin traslado"]]) + "</select></label>",
        "<label class=\"wide transfer-only-field\">Traslado<input data-transfer-combo list=\"itineraryTransferOptions\" placeholder=\"" + escapeHtml(placeholder || "Buscar por nombre, X5, origen o destino") + "\"></label>",
        "<label class=\"transfer-only-field\">Moneda Traslado<select data-itinerary-field=\"transferCurrency\"><option value=\"USD\">USD</option><option value=\"ARS\">ARS</option><option value=\"BRL\">BRL</option></select></label>",
        "<label class=\"transfer-only-field\">Precio Traslado<input data-itinerary-field=\"transferValue\" inputmode=\"decimal\"></label>",
        "<label class=\"wine-check transfer-only-field\"><input data-itinerary-field=\"freezeTransferValue\" type=\"checkbox\"> Congelar valor</label>",
        "<label class=\"wine-check transfer-only-field\"><input data-itinerary-field=\"courtesyTransfer\" type=\"checkbox\"> Cortesia</label>"
      ].join("");
    }

