    function renderPuquiosPage(client, date, steps, context) {
      var language = context.language || clientItineraryLanguage(client);
      var content = puquiosContent(language);
      var dinnerSteps = (steps || []).filter(isDinnerStep);
      var page = document.createElement("section");
      page.className = "client-page alta-mountain-page puquios-page";
      var pickup = (steps.find(function(step) { return step.pickup; }) || {}).pickup || "-";
      var dayParticipantIds = [].concat.apply([], steps.map(function(step) { return normalizeParticipantIds(step.participants); }));
      dayParticipantIds = dayParticipantIds.filter(function(id, i, arr) { return arr.indexOf(id) === i; });
      var hotel = hotelForDate(client, date, dayParticipantIds, context) || itineraryText(language, "hotel");

      var descParagraphs = content.description.map(function(p) { return "<p class=\"sr-desc-p\">" + escapeHtml(p) + "</p>"; }).join("");
      var notIncludesList = content.notIncludes.map(function(v) { return "<li>\u2718 " + escapeHtml(v) + "</li>"; }).join("");
      var gallery = puquiosImages.map(function(src) {
        return "<div class=\"sr-gallery-item\"><img src=\"" + src + "\" alt=\"Los Puquios\"></div>";
      }).join("");

      page.innerHTML = [
        "<div class=\"alta-head puquios-head\">",
        "<div class=\"alta-brand\">",
        "<div class=\"alta-title-row\"><span class=\"puquios-icon\">\u2744\uFE0F</span><h3>LOS PUQUIOS</h3></div>",
        "<div class=\"alta-subtitle\">" + escapeHtml(content.subtitle) + "</div>",
        "</div>",
        "<div class=\"alta-info-card\">",
        altaInfoLine("pin", itineraryText(language, "altaPickupPlace"), hotel),
        altaInfoLine("calendar", itineraryText(language, "altaDate"), displayDateLongForLanguage(date, language) || "-"),
        altaInfoLine("clock", itineraryText(language, "altaDepartureTime"), pickup),
        "</div>",
        "</div>",
        "<div class=\"sr-gallery\">" + gallery + "</div>",
        "<div class=\"sr-body\">",
        descParagraphs,
        "<div class=\"sr-section\"><div class=\"sr-section-title\">" + escapeHtml(content.notIncludesTitle) + "</div><ul class=\"sr-check-list sr-no-list\">" + notIncludesList + "</ul></div>",
        "<div class=\"puquios-closing\">\u2728 " + escapeHtml(content.closing) + "</div>",
        "</div>"
      ].join("");

      var otherSteps = (steps || []).filter(function(step) { return !isPuquiosStep(step) && !isDinnerStep(step) && step.kind !== "transfer" && !step.standaloneTransfer; });
      if (otherSteps.length) {
        var otherBlock = document.createElement("div");
        otherBlock.className = "alta-dinner-block";
        otherBlock.innerHTML = "<div class=\"client-stops\"></div>";
        var otherContainer = otherBlock.querySelector(".client-stops");
        otherSteps.forEach(function(step) { otherContainer.append(renderClientStop(step, context)); });
        page.append(otherBlock);
      }
      if (dinnerSteps.length) {
        var dinnerBlock = document.createElement("div");
        dinnerBlock.className = "alta-dinner-block";
        dinnerBlock.innerHTML = "<h4>" + escapeHtml(itineraryText(language, "altaDinner")) + "</h4><div class=\"client-stops\"></div>";
        var container = dinnerBlock.querySelector(".client-stops");
        dinnerSteps.forEach(function(step) { container.append(renderClientStop(step, context)); });
        page.append(dinnerBlock);
      }
      if (itineraryModeAllowsExperiences(context.mode)) {
        var valuesRow = document.createElement("div");
        valuesRow.className = "alta-actions-row alta-actions-values";
        valuesRow.append(renderClientDailyValues(client, withDayTransfers(steps, steps.filter(function(step) { return step.kind !== "transfer"; })), context));
        page.append(valuesRow);
      }
      return page;
    }

