    function renderSanRafaelPage(client, date, steps, context) {
      const language = context.language || clientItineraryLanguage(client);
      const content = sanRafaelContent(language);
      const dinnerSteps = (steps || []).filter(isDinnerStep);
      const page = document.createElement("section");
      page.className = "client-page alta-mountain-page sanrafael-page";
      const pickup = (steps.find((step) => step.pickup) || {}).pickup || "-";
      const dayParticipantIds = [...new Set(steps.flatMap((step) => normalizeParticipantIds(step.participants)))];
      const hotel = hotelForDate(client, date, dayParticipantIds, context) || itineraryText(language, "hotel");

      const descParagraphs = content.description.map(function(p) { return "<p class=\"sr-desc-p\">" + escapeHtml(p) + "</p>"; }).join("");
      const visitsList = content.visits.map(function(v) { return "<li>\u2714 " + escapeHtml(v) + "</li>"; }).join("");
      const includesList = content.includes.map(function(v) { return "<li>\u2714 " + escapeHtml(v) + "</li>"; }).join("");
      const notIncludesList = content.notIncludes.map(function(v) { return "<li>\u2718 " + escapeHtml(v) + "</li>"; }).join("");

      const gallery = sanRafaelImages.map(function(src) {
        return "<div class=\"sr-gallery-item\"><img src=\"" + src + "\" alt=\"San Rafael\"></div>";
      }).join("");

      page.innerHTML = [
        "<div class=\"alta-head sanrafael-head\">",
        "<div class=\"alta-brand\">",
        "<div class=\"alta-title-row\">" + mountainIconSvg() + "<h3>SAN RAFAEL</h3></div>",
        "<div class=\"alta-subtitle\">" + escapeHtml(content.subtitle) + "</div>",
        "</div>",
        "<div class=\"alta-info-card\">",
        altaInfoLine("pin", itineraryText(language, "altaPickupPlace"), hotel),
        altaInfoLine("calendar", itineraryText(language, "altaDate"), displayDateLongForLanguage(date, language) || "-"),
        altaInfoLine("clock", itineraryText(language, "altaDepartureTime"), pickup),
        "</div>",
        "</div>",
        "<div class=\"sr-gallery\">" + gallery + "</div>",
        "<div class=\"sr-body\">",
        descParagraphs,
        "<div class=\"sr-important\">" + escapeHtml(content.important) + "</div>",
        "<div class=\"sr-section\"><div class=\"sr-section-title\">" + escapeHtml(content.pickupTitle) + "</div><p class=\"sr-desc-p\">" + escapeHtml(content.pickupText) + "</p></div>",
        "<div class=\"sr-lists\">",
        "<div class=\"sr-list-col\"><div class=\"sr-section-title\">" + escapeHtml(content.visitsTitle) + "</div><ul class=\"sr-check-list\">" + visitsList + "</ul></div>",
        "<div class=\"sr-list-col\"><div class=\"sr-section-title\">" + escapeHtml(content.includesTitle) + "</div><ul class=\"sr-check-list\">" + includesList + "</ul><div class=\"sr-section-title sr-mt\">" + escapeHtml(content.notIncludesTitle) + "</div><ul class=\"sr-check-list sr-no-list\">" + notIncludesList + "</ul></div>",
        "</div>",
        "</div>"
      ].join("");

      if (dinnerSteps.length) {
        const dinnerBlock = document.createElement("div");
        dinnerBlock.className = "alta-dinner-block";
        dinnerBlock.innerHTML = "<h4>" + escapeHtml(itineraryText(language, "altaDinner")) + "</h4><div class=\"client-stops\"></div>";
        const container = dinnerBlock.querySelector(".client-stops");
        dinnerSteps.forEach(function(step) { container.append(renderClientStop(step, context)); });
        page.append(dinnerBlock);
      }
      if (itineraryModeAllowsExperiences(context.mode)) {
        const valuesRow = document.createElement("div");
        valuesRow.className = "alta-actions-row alta-actions-values";
        valuesRow.append(renderClientDailyValues(client, withDayTransfers(steps, steps.filter(function(step) { return isSanRafaelStep(step) || isDinnerStep(step); })), context));
        page.append(valuesRow);
      }
      return page;
    }

    function isDinnerStep(step) {
      const provider = step && step.providerId ? findCatalogProvider(step.providerId) : null;
      const service = step && step.providerId && step.providerServiceId ? findProviderService(step.providerId, step.providerServiceId) : null;
      // 1. Si el tipo de servicio es explicitamente Almuerzo/Visita, NO es cena
      if (service && service.type && service.type !== "Cena") return false;
      if (step && step.serviceType && (step.serviceType === "Almuerzo" || step.serviceType === "Visita" || step.serviceType === "Visita y degustacion")) return false;
      // 2. Si el tipo es explicitamente Cena, SI es cena
      if (service && service.type === "Cena") return true;
      if (step && step.serviceType === "Cena") return true;
      if (step && step.kind === "dinner") return true;
      // 3. Fallback para datos antiguos sin tipo explicito: buscar solo en nombre del servicio
      const text = latinKey([
        step && step.kind,
        step && step.serviceType,
        step && step.region,
        step && step.serviceName,
        service && service.name
      ].join(" "));
      return Boolean(text.includes("cena") || text.includes("dinner") || text.includes("jantar"));
    }

    function altaMountainSubtitle(language) {
      const lang = normalizeServiceLanguage(language);
      if (lang === "Portugues") return "Natureza em sua maior expressao";
      if (lang === "Ingles") return "Nature at its finest";
      return "Naturaleza en su mayor expresion";
    }

    function altaInfoLine(icon, label, value) {
      // Support old call signature (icon, fullText) for backwards compatibility
      if (typeof value === "undefined") {
        return "<div class=\"alta-info-line\"><span class=\"alta-info-icon\">" + altaInfoIcon(icon) + "</span><span>" + escapeHtml(label) + "</span></div>";
      }
      return "<div class=\"alta-info-line\"><span class=\"alta-info-icon\">" + altaInfoIcon(icon) + "</span><span><strong style=\"display:block;font-size:11px;opacity:0.7;letter-spacing:2px;margin-bottom:3px\">" + escapeHtml(label) + "</strong>" + escapeHtml(value) + "</span></div>";
    }

    function altaInfoIcon(icon) {
      if (icon === "calendar") return "D";
      if (icon === "clock") return "H";
      return "P";
    }

    function mountainIconSvg() {
      return "<svg class=\"alta-mountain-icon\" viewBox=\"0 0 220 95\" fill=\"none\" aria-hidden=\"true\"><path d=\"M8 76 58 17l22 29 20-27 62 57\" stroke=\"currentColor\" stroke-width=\"9\" stroke-linejoin=\"round\"/><path d=\"M58 17 70 58 83 47l17-28 17 38 22-18 23 37\" stroke=\"currentColor\" stroke-width=\"7\" stroke-linejoin=\"round\"/><path d=\"M24 83c36-10 65-12 102-4 25 5 49 4 74-5\" stroke=\"currentColor\" stroke-width=\"9\" stroke-linecap=\"round\"/></svg>";
    }

