    function showProviderPanel(panelId) {
      var panels = ["providersPanel", "providerServicesPanel", "providerTrashPanel"];
      panels.forEach(function(id) {
        var el = document.getElementById(id);
        if (el) el.classList.toggle("hidden", id !== panelId);
      });
      document.querySelectorAll("[data-provider-tab]").forEach(function(tab) {
        tab.classList.toggle("active", tab.dataset.providerTab === panelId);
      });
      if (panelId === "providerTrashPanel") renderProviderTrash();
    }

    function renderProviderTrash() {
      var body = document.getElementById("providerTrashBody");
      var emptyMsg = document.getElementById("providerTrashEmpty");
      if (!body) return;
      body.innerHTML = "";
      cleanupOldTrashedProviders();
      var items = state.trashedProviders || [];
      if (emptyMsg) emptyMsg.style.display = items.length ? "none" : "block";
      items.forEach(function(provider) {
        var tr = document.createElement("tr");
        var tms = provider.trashedAt ? trashedAtMs(provider.trashedAt) : 0;
        var age = tms ? Math.floor((Date.now() - tms) / 86400000) : 0;
        var remaining = Math.max(0, 30 - age);
        appendCells(tr, [
          provider.name || "-",
          (provider.services || []).length,
          provider.trashedAt ? timeAgo(provider.trashedAt) : "-",
          remaining + " dias"
        ]);
        var restoreBtn = document.createElement("button");
        restoreBtn.className = "table-button";
        restoreBtn.textContent = "Restaurar";
        restoreBtn.onclick = function() { restoreProvider(provider.id); renderProviderTrash(); };
        var restoreTd = document.createElement("td");
        restoreTd.append(restoreBtn);
        tr.append(restoreTd);
        var deleteBtn = document.createElement("button");
        deleteBtn.className = "table-button danger";
        deleteBtn.textContent = "Eliminar";
        deleteBtn.onclick = function() { permanentlyDeleteProvider(provider.id); renderProviderTrash(); };
        var deleteTd = document.createElement("td");
        deleteTd.append(deleteBtn);
        tr.append(deleteTd);
        body.append(tr);
      });
    }

    function saveTransferFromForm() {
      const payload = normalizeTransfer({
        id: state.activeTransferId || makeId(),
        origin: els.transferOriginInput.value,
        destination: els.transferDestinationInput.value,
        name: els.transferNameInput.value,
        vehicle: els.transferVehicleInput.value,
        value: els.transferValueInput.value,
        currency: els.transferCurrencyInput.value,
        details: state.activeTransferId && findTransfer(state.activeTransferId) ? findTransfer(state.activeTransferId).details : "",
        hidden: els.transferHiddenInput.checked
      });
      if (!payload.origin && !payload.destination) {
        alert("Carga origen o destino del traslado.");
        return;
      }
      const index = state.transfers.findIndex((transfer) => transfer.id === payload.id);
      if (index >= 0) state.transfers[index] = payload;
      else state.transfers.push(payload);
      clearTransferForm();
      saveTransfers();
    }

