    els.closeNoCloseReasonButton.addEventListener("click", closeNoCloseReasonModal);
    els.cancelNoCloseReasonButton.addEventListener("click", closeNoCloseReasonModal);
    els.saveNoCloseReasonButton.addEventListener("click", saveNoCloseReasonFromModal);
    els.noCloseReasonModal.addEventListener("click", (event) => {
      if (event.target === els.noCloseReasonModal) closeNoCloseReasonModal();
    });
    els.statsTabs.forEach((tab) => {
      tab.addEventListener("click", () => {
        state.activeStatsTab = tab.dataset.statsTab || "vendedores";
        renderEstadisticas();
      });
    });
    var vgYearFilter = document.getElementById("ventaGeneralYearFilter");
    if (vgYearFilter) vgYearFilter.addEventListener("change", function() { try { renderVentaGeneral(); } catch (e) {} });
    var sellerYearF = document.getElementById("sellerYearFilter");
    if (sellerYearF) sellerYearF.addEventListener("change", function() { try { renderSellerPerformanceStats(state.clients.slice()); } catch (e) {} });
    var sellerMetricF = document.getElementById("sellerMetricFilter");
    if (sellerMetricF) sellerMetricF.addEventListener("change", function() { try { renderSellerPerformanceStats(state.clients.slice()); } catch (e) {} });
    if (els.printStatsButton) els.printStatsButton.addEventListener("click", printStatsReport);

    els.closeItineraryButton.addEventListener("click", closeItineraryModal);
    els.cancelItineraryButton.addEventListener("click", closeItineraryModal);
    els.saveItineraryButton.addEventListener("click", saveItinerary);
    if (els.downloadItineraryButton) els.downloadItineraryButton.addEventListener("click", downloadCurrentItineraryPdf);
    els.copyItineraryLinkButton.addEventListener("click", copyCurrentItineraryLink);
    els.openItineraryLinkButton.addEventListener("click", openCurrentItineraryLink);
    [els.itineraryLanguageInput, els.itineraryNotesInput, els.itineraryUsdRateInput, els.itineraryBrlRateInput].forEach((control) => {
      control.addEventListener("input", () => {
        const client = state.clients.find((item) => item.id === state.activeItineraryClientId);
        if (client) {
          renderItineraryTotals(client);
          renderItineraryPreview(client);
        }
      });
      control.addEventListener("change", () => {
        const client = state.clients.find((item) => item.id === state.activeItineraryClientId);
        if (client) {
          renderItineraryTotals(client);
          renderItineraryPreview(client);
        }
      });
    });
    els.addItineraryStepButton.addEventListener("click", () => {
      const client = state.clients.find((item) => item.id === state.activeItineraryClientId);
      state.draftItinerarySteps.push(makeItineraryStep(client, client && client.from ? client.from : ""));
      renderItineraryDraft();
    });
    els.addItineraryTransferButton.addEventListener("click", () => {
      const client = state.clients.find((item) => item.id === state.activeItineraryClientId);
      state.draftItinerarySteps.push(makeItineraryTransferStep(client, "TRF IN"));
      renderItineraryDraft();
    });
    els.addItineraryParticipantButton.addEventListener("click", () => {
      state.draftItineraryParticipants.push(normalizeItineraryParticipant({ name: "Integrante " + (state.draftItineraryParticipants.length + 1), type: "Adulto", age: "", drinksWine: true, dietary: "" }));
      ensureItineraryParticipantsOnSteps();
      renderItineraryDraft();
    });
    els.addItineraryHotelButton.addEventListener("click", () => {
      const client = state.clients.find((item) => item.id === state.activeItineraryClientId);
      state.draftItineraryHotels.push(normalizeHotel({
        name: "",
        from: client ? client.from : "",
        to: client ? client.to : "",
        participants: state.draftItineraryParticipants.map((person) => person.id)
      }));
      renderItineraryHotels();
      renderItineraryPreview(client);
    });
    els.addItineraryDiscountButton.addEventListener("click", () => {
      state.draftItineraryDiscounts.push(normalizeItineraryDiscount({ currency: "ARS", amount: "", note: "" }));
      renderItineraryDraft();
    });
    els.toggleItineraryParticipantsButton.addEventListener("click", () => {
      state.itineraryParticipantsCollapsed = !state.itineraryParticipantsCollapsed;
      renderItineraryParticipants();
    });
    els.toggleItineraryHotelsButton.addEventListener("click", () => {
      state.itineraryHotelsCollapsed = !state.itineraryHotelsCollapsed;
      renderItineraryHotels();
    });
    els.toggleItineraryTransfersButton.addEventListener("click", () => {
      state.itineraryTransfersCollapsed = !state.itineraryTransfersCollapsed;
      renderItineraryTransfers(state.clients.find((item) => item.id === state.activeItineraryClientId));
    });
    els.itineraryModal.addEventListener("click", (event) => {
      if (event.target === els.itineraryModal) closeItineraryModal();
      const addTourOnDate = event.target.closest("[data-add-tour-date]");
      if (addTourOnDate) {
        const client = state.clients.find((item) => item.id === state.activeItineraryClientId);
        state.draftItinerarySteps.push(makeItineraryStep(client, addTourOnDate.dataset.addTourDate));
        state.itineraryDirty = true;
        renderItineraryDraft();
        return;
      }
      const addDinnerOnDate = event.target.closest("[data-add-dinner-date]");
      if (addDinnerOnDate) {
        const client = state.clients.find((item) => item.id === state.activeItineraryClientId);
        state.draftItinerarySteps.push(makeItineraryDinnerStep(client, addDinnerOnDate.dataset.addDinnerDate));
        state.itineraryDirty = true;
        renderItineraryDraft();
        return;
      }
      const addStandaloneTransfer = event.target.closest("[data-add-standalone-transfer]");
      if (addStandaloneTransfer) {
        const client = state.clients.find((item) => item.id === state.activeItineraryClientId);
        const step = makeItineraryStep(client, addStandaloneTransfer.dataset.addStandaloneTransfer);
        step.standaloneTransfer = true;
        state.draftItinerarySteps.push(step);
        state.itineraryDirty = true;
        renderItineraryDraft();
        return;
      }
      const createBookingDate = event.target.closest("[data-create-booking-date]");
      if (createBookingDate) {
        const client = state.clients.find((item) => item.id === state.activeItineraryClientId);
        if (!client) return;
        if (!window.confirm("Crear la reserva de los servicios y traslados cargados para esta fecha?")) return;
        const count = createBookingsForDraftDate(client, createBookingDate.dataset.createBookingDate);
        if (!count) {
          alert("No hay servicios ni traslados cargados para crear reserva en esta fecha.");
          return;
        }
        renderItineraryDraft();
        alert("Reserva creada en estado PENDIENTE (" + count + " servicio" + (count === 1 ? "" : "s") + "). Pasara a EN RESERVA automaticamente cuando el cliente este en estado Cerrado.");
        return;
      }
      const toggleTourDate = event.target.closest("[data-toggle-tour-date]");
      if (toggleTourDate) {
        const date = toggleTourDate.dataset.toggleTourDate;
        state.itineraryDayCollapsed[date] = !state.itineraryDayCollapsed[date];
        renderItineraryTourDays(state.clients.find((item) => item.id === state.activeItineraryClientId));
        return;
      }
      const leadBtn = event.target.closest(".toggle-participant-lead");
      if (leadBtn) {
        const rowL = leadBtn.closest("[data-participant-index]");
        const idxL = Number(rowL && rowL.dataset.participantIndex);
        const wasLead = !!(state.draftItineraryParticipants[idxL] && state.draftItineraryParticipants[idxL].lead);
        state.draftItineraryParticipants.forEach((p, i) => { p.lead = (i === idxL) && !wasLead; });
        state.itineraryDirty = true;
        renderItineraryParticipants();
        return;
      }
      const removeParticipant = event.target.closest(".remove-itinerary-participant");
      if (removeParticipant) {
        const row = removeParticipant.closest("[data-participant-index]");
        const index = Number(row.dataset.participantIndex);
        const removed = state.draftItineraryParticipants[index];
        state.draftItineraryParticipants.splice(index, 1);
        if (!state.draftItineraryParticipants.length) state.draftItineraryParticipants.push(normalizeItineraryParticipant({ name: "Integrante 1", type: "Adulto", age: "", drinksWine: true, dietary: "" }));
        if (removed) {
          state.draftItinerarySteps.forEach((step) => {
            step.participants = step.participants.filter((id) => id !== removed.id);
          });
          state.draftItineraryHotels.forEach((hotel) => {
            hotel.participants = normalizeParticipantIds(hotel.participants).filter((id) => id !== removed.id);
          });
        }
        ensureItineraryParticipantsOnSteps();
        renderItineraryDraft();
        return;
      }
      const removeHotel = event.target.closest(".remove-itinerary-hotel");
      if (removeHotel) {
        const row = removeHotel.closest("[data-hotel-index]");
        const index = Number(row.dataset.hotelIndex);
        state.draftItineraryHotels.splice(index, 1);
        renderItineraryHotels();
        const client = state.clients.find((item) => item.id === state.activeItineraryClientId);
        if (client) renderItineraryPreview(client);
        return;
      }
      const removeDiscount = event.target.closest(".remove-itinerary-discount");
      if (removeDiscount) {
        const row = removeDiscount.closest("[data-discount-index]");
        const index = Number(row.dataset.discountIndex);
        state.draftItineraryDiscounts.splice(index, 1);
        renderItineraryDraft();
        return;
      }
      const removeStep = event.target.closest(".remove-itinerary-step");
      if (removeStep) {
        const card = removeStep.closest("[data-step-index]");
        const index = Number(card.dataset.stepIndex);
        state.draftItinerarySteps.splice(index, 1);
        if (!state.draftItinerarySteps.length) {
          const client = state.clients.find((item) => item.id === state.activeItineraryClientId);
          state.draftItinerarySteps.push(makeItineraryTransferStep(client, "TRF IN"));
        }
        state.itineraryDirty = true;
        renderItineraryDraft();
      }
    });
    els.itineraryModal.addEventListener("input", (event) => {
      state.itineraryDirty = true;
      const participantInput = event.target.closest("[data-participant-field]");
      if (participantInput) {
        const index = Number(participantInput.closest("[data-participant-index]").dataset.participantIndex);
        const person = state.draftItineraryParticipants[index];
        if (!person) return;
        if (participantInput.dataset.participantField === "drinksWine") {
          person.drinksWine = participantInput.checked;
        } else if (participantInput.dataset.participantField === "type") {
          person.type = participantInput.value === "Menor" ? "Menor" : "Adulto";
          if (person.type === "Menor") person.drinksWine = false;
          else person.age = "";
        } else if (participantInput.dataset.participantField === "age") {
          person.age = participantInput.value;
        } else {
          person[participantInput.dataset.participantField] = participantInput.value;
        }
        return;
      }
      const hotelInput = event.target.closest("[data-hotel-field]");
      if (hotelInput && hotelInput.dataset.hotelField !== "participants") {
        const index = Number(hotelInput.closest("[data-hotel-index]").dataset.hotelIndex);
        updateItineraryHotel(index, hotelInput.dataset.hotelField, hotelInput.value);
        return;
      }
      const discountInput = event.target.closest("[data-discount-field]");
      if (discountInput) {
        const index = Number(discountInput.closest("[data-discount-index]").dataset.discountIndex);
        const discount = state.draftItineraryDiscounts[index];
        if (discount) discount[discountInput.dataset.discountField] = discountInput.value;
        return;
      }
      const transferSearch = event.target.closest("[data-transfer-search]");
      if (transferSearch) {
        const card = transferSearch.closest("[data-step-index]");
        const index = card ? Number(card.dataset.stepIndex) : -1;
        const step = state.draftItinerarySteps[index];
        const select = card ? card.querySelector("[data-itinerary-field='transferId']") : null;
        if (step && select) {
          fillItineraryTransferSelect(select, step, transferSearch.value);
          select.value = step.transferId || "";
        }
        return;
      }
      const input = event.target.closest("[data-itinerary-field]");
      if (!input) return;
      const card = input.closest("[data-step-index]");
      if (!card) return;
      const index = Number(card.dataset.stepIndex);
      const step = state.draftItinerarySteps[index];
      if (step) {
        const field = input.dataset.itineraryField;
        step[field] = input.type === "checkbox" ? input.checked : input.value;
        if (field === "transferValue" || field === "transferCurrency") {
          preserveManualTransferOverride(step);
          const freezeInput = card.querySelector("[data-itinerary-field='freezeTransferValue']");
          if (freezeInput) freezeInput.checked = Boolean(step.freezeTransferValue);
        }
      }
    });
    els.itineraryModal.addEventListener("change", (event) => {
      state.itineraryDirty = true;
      const participantInput = event.target.closest("[data-participant-field]");
      if (participantInput) {
        const index = Number(participantInput.closest("[data-participant-index]").dataset.participantIndex);
        const person = state.draftItineraryParticipants[index];
        if (!person) return;
        if (participantInput.dataset.participantField === "drinksWine") {
          person.drinksWine = participantInput.checked;
        } else if (participantInput.dataset.participantField === "type") {
          person.type = participantInput.value === "Menor" ? "Menor" : "Adulto";
          if (person.type === "Menor") person.drinksWine = false;
          else person.age = "";
        } else if (participantInput.dataset.participantField === "age") {
          person.age = normalizeMinorAge(participantInput.value);
        } else {
          person[participantInput.dataset.participantField] = participantInput.value;
        }
        renderItineraryDraft();
        return;
      }
      const hotelInput = event.target.closest("[data-hotel-field]");
      if (hotelInput) {
        const index = Number(hotelInput.closest("[data-hotel-index]").dataset.hotelIndex);
        updateItineraryHotel(index, hotelInput.dataset.hotelField, hotelInput.value);
        renderItineraryDraft();
        return;
      }
      const hotelParticipantChoice = event.target.closest("[data-hotel-participant-id]");
      if (hotelParticipantChoice) {
        const picker = hotelParticipantChoice.closest("[data-hotel-index]");
        const index = picker ? Number(picker.dataset.hotelIndex) : -1;
        const hotel = state.draftItineraryHotels[index];
        if (!hotel) return;
        const id = hotelParticipantChoice.dataset.hotelParticipantId;
        hotel.participants = Array.isArray(hotel.participants) ? hotel.participants : [];
        if (!hotel.participants.length) hotel.participants = state.draftItineraryParticipants.map((person) => person.id);
        if (hotelParticipantChoice.checked && !hotel.participants.includes(id)) hotel.participants.push(id);
        if (!hotelParticipantChoice.checked) hotel.participants = hotel.participants.filter((item) => item !== id);
        const summary = hotelParticipantChoice.closest(".participant-picker").querySelector("summary");
        if (summary) summary.textContent = hotelParticipantsSummary(hotel.participants);
        const client = state.clients.find((item) => item.id === state.activeItineraryClientId);
        if (client) {
          renderItineraryTotals(client);
          renderItineraryPreview(client);
        }
        return;
      }
      const participantChoice = event.target.closest("[data-participant-id]");
      if (participantChoice) {
        const picker = participantChoice.closest("[data-step-index]");
        const index = Number(picker.dataset.stepIndex);
        const step = state.draftItinerarySteps[index];
        if (!step) return;
        const id = participantChoice.dataset.participantId;
        if (participantChoice.checked && !step.participants.includes(id)) step.participants.push(id);
        if (!participantChoice.checked) step.participants = step.participants.filter((item) => item !== id);
        step.pax = String(step.participants.length);
        const card = participantChoice.closest("[data-step-index]");
        const paxInput = card ? card.querySelector("[data-itinerary-field='pax']") : null;
        if (paxInput) paxInput.value = step.pax;
        const summary = participantChoice.closest(".participant-picker").querySelector("summary");
        if (summary) summary.textContent = participantsSummary(step.participants);
        const client = state.clients.find((item) => item.id === state.activeItineraryClientId);
        if (client) {
          renderItineraryTotals(client);
          renderItineraryPreview(client);
        }
        return;
      }
      const wineOverride = event.target.closest("[data-wine-override-id]");
      if (wineOverride) {
        const picker = wineOverride.closest("[data-step-index]");
        const index = Number(picker.dataset.stepIndex);
        const step = state.draftItinerarySteps[index];
        if (!step) return;
        step.wineOverrides = step.wineOverrides || {};
        if (wineOverride.value) step.wineOverrides[wineOverride.dataset.wineOverrideId] = wineOverride.value;
        else delete step.wineOverrides[wineOverride.dataset.wineOverrideId];
        const client = state.clients.find((item) => item.id === state.activeItineraryClientId);
        if (client) {
          renderItineraryTotals(client);
          renderItineraryPreview(client);
        }
        return;
      }
      const transferCombo = event.target.closest("[data-transfer-combo]");
      if (transferCombo) {
        const card = transferCombo.closest("[data-step-index]");
        const index = card ? Number(card.dataset.stepIndex) : -1;
        const step = state.draftItinerarySteps[index];
        if (!step) return;
        const transfer = transferFromComboValue(transferCombo.value, step.transferId);
        if (transfer) {
          step.transferId = transfer.id;
          step.freezeTransferValue = false;
          snapshotTransfer(step, true);
        } else if (!transferCombo.value.trim()) {
          step.transferId = "";
          step.transferLabel = "";
          step.transferValue = "";
          step.transferDetails = "";
          step.freezeTransferValue = false;
        } else {
          alert("No encontre ese traslado. Escribi parte del nombre y elegilo del listado.");
        }
        renderItineraryDraft();
        return;
      }
      const discountPartChange = event.target.closest("[data-discount-participant]");
      if (discountPartChange) {
        const dRow = discountPartChange.closest("[data-discount-index]");
        const dIndex = Number(dRow.dataset.discountIndex);
        const disc = state.draftItineraryDiscounts[dIndex];
        if (disc) {
          disc.participants = Array.prototype.slice.call(dRow.querySelectorAll("[data-discount-participant]"))
            .filter(function(cb) { return cb.checked; })
            .map(function(cb) { return cb.getAttribute("data-discount-participant"); });
          renderItineraryDraft();
        }
        return;
      }
      const discountInput = event.target.closest("[data-discount-field]");
      if (discountInput) {
        const index = Number(discountInput.closest("[data-discount-index]").dataset.discountIndex);
        const discount = state.draftItineraryDiscounts[index];
        if (!discount) return;
        discount[discountInput.dataset.discountField] = discountInput.value;
        renderItineraryDraft();
        return;
      }
      const input = event.target.closest("[data-itinerary-field]");
      if (!input) return;
      const card = input.closest("[data-step-index]");
      if (!card) return;
      const index = Number(card.dataset.stepIndex);
      // OTRO HORARIO: si en el desplegable de horario eligen "Otro horario…", pedimos el
      // horario a mano y lo guardamos como el horario del paso. (restaurado 21/08)
      if (input.dataset.itineraryField === "time" && input.value === "__OTRO__") {
        const _step = state.draftItinerarySteps[index];
        const _prev = _step ? (_step.time || "") : "";
        const _typed = window.prompt("Escribí el horario de reserva (ej. 10:00):", _prev);
        if (_typed && _typed.trim()) {
          updateItineraryStep(index, "time", _typed.trim());
        }
        renderItineraryDraft();
        return;
      }
      updateItineraryStep(index, input.dataset.itineraryField, input.type === "checkbox" ? input.checked : input.value);
    });

    els.saveProviderButton.addEventListener("click", saveProviderFromForm);
    els.cancelProviderButton.addEventListener("click", clearProviderForm);
    els.providerPhotoInput.addEventListener("change", async () => {
      const file = els.providerPhotoInput.files && els.providerPhotoInput.files[0] ? els.providerPhotoInput.files[0] : null;
      if (!file) return;
      els.providerPhotoPreview.textContent = "Subiendo foto...";
      try {
        state.providerPhotoDraft = await mediaUrlFromFile(file, "provider-photos");
        renderProviderPhotoPreview();
      } catch (error) {
        console.warn("No se pudo cargar la foto del proveedor", error);
        els.providerPhotoPreview.textContent = "No se pudo cargar la foto";
      }
    });
    els.providerMenuImageInput.addEventListener("change", async () => {
      const file = els.providerMenuImageInput.files && els.providerMenuImageInput.files[0] ? els.providerMenuImageInput.files[0] : null;
      if (!file) return;
      if (els.providerMenuImagePreview) els.providerMenuImagePreview.textContent = "Subiendo menu...";
      try {
        state.providerMenuImageDraft = await mediaUrlFromFile(file, "service-menus");
        renderProviderMenuImagePreview();
      } catch (error) {
        console.warn("No se pudo cargar el menu del servicio", error);
        if (els.providerMenuImagePreview) els.providerMenuImagePreview.textContent = "No se pudo cargar el menu";
      }
    });
    els.saveProviderServiceButton.addEventListener("click", saveProviderServiceFromForm);
    if (els.providerPriceMonthSelect) els.providerPriceMonthSelect.addEventListener("change", () => switchProviderPriceMonth(els.providerPriceMonthSelect.value));
    if (els.addPriceMonthButton) els.addPriceMonthButton.addEventListener("click", addProviderPriceMonth);
    if (els.removePriceMonthButton) els.removePriceMonthButton.addEventListener("click", removeProviderPriceMonth);
