    const setLogisticaDate = (d) => {
      state.activeYear = d.getFullYear();
      state.activeMonth = d.getMonth() + 1;
      const y = d.getFullYear(), m = String(d.getMonth() + 1).padStart(2, "0"), da = String(d.getDate()).padStart(2, "0");
      const iso = y + "-" + m + "-" + da;
      // Hoy / Mañana = ver ese único día (Desde = Hasta).
      els.logisticaDateFilter.value = iso;
      if (logisticaDateToEl) logisticaDateToEl.value = iso;
      renderAll();
    };
