    if (restoreProvidersBtn && restoreProvidersInput) {
      restoreProvidersBtn.addEventListener("click", () => restoreProvidersInput.click());
      restoreProvidersInput.addEventListener("change", () => {
        const file = restoreProvidersInput.files && restoreProvidersInput.files[0];
        if (!file) return;
        const reader = new FileReader();
        reader.onload = function() {
          try {
            var data = JSON.parse(String(reader.result || ""));
            var provs = data.catalogProviders;
            if (!Array.isArray(provs) || !provs.length) { alert("El archivo no tiene proveedores."); return; }
            var ok = window.confirm(
              "RESTAURAR SOLO PROVEEDORES\n\n" +
              "Proveedores en el archivo: " + provs.length + "\n" +
              "Servicios: " + provs.reduce(function(t,p){return t+(p.services||[]).length;},0) + "\n\n" +
              "Los CLIENTES NO se tocan. Solo se reemplazan los proveedores.\n\nContinuar?"
            );
            if (!ok) return;
            state.catalogProviders = provs.map(normalizeCatalogProvider);
            if (Array.isArray(data.deletedProviderIds)) state.deletedProviderIds = data.deletedProviderIds;
            if (Array.isArray(data.deletedServiceIds)) state.deletedServiceIds = data.deletedServiceIds;
            if (Array.isArray(data.trashedProviders)) state.trashedProviders = data.trashedProviders;
            saveCatalogProviders();
            flushRemoteSave();
            alert("Proveedores restaurados! (" + state.catalogProviders.length + " proveedores)");
          } catch(e) { alert("Error: " + e.message); }
        };
        reader.readAsText(file);
        restoreProvidersInput.value = "";
      });
    }
