      if (button.dataset.action === "delete-payment") deletePayment(button.dataset.id);
      if (button.dataset.action === "delete-closure") deleteClosure(button.dataset.id);
      if (button.dataset.action === "edit-service") editService(button.dataset.id);
      if (button.dataset.action === "delete-service") deleteService(button.dataset.id);
      if (button.dataset.action === "reservation-message") showReservationMessage(button.dataset.id);
      if (button.dataset.action === "set-termas-reservation") setTermasReservation(button.dataset.id);
      if (button.dataset.action === "edit-fleet") editFleetVehicle(button.dataset.id);
